window.G6_TOEIC_LOOKUP_DATA = {"vocabularySetId":"toeic-vocab-tw","sourceRevision":"7b1f881c2474bcb96fa8eacfbb8f63754c8cccef","totalEntries":11238,"matchedCount":195,"unmatchedWordIds":["g6-p1-p2:adjectives:2:awake","g6-p1-p2:adjectives:22:loving","g6-p1-p2:pronoun:2:hers","g6-p1-p2:pronoun:7:ours","g6-p1-p2:pronoun:12:yours","g6-p1-p2:pronoun:14:her","g6-p1-p2:pronoun:15:him","g6-p1-p2:pronoun:16:its","g6-p1-p2:pronoun:17:me","g6-p1-p2:pronoun:18:our","g6-p1-p2:pronoun:19:their","g6-p1-p2:pronoun:20:them","g6-p1-p2:pronoun:21:these","g6-p1-p2:pronoun:22:they","g6-p1-p2:pronoun:23:those","g6-p1-p2:pronoun:24:us","g6-p1-p2:pronoun:25:we","g6-p1-p2:pronoun:26:whose","g6-p1-p2:adverb:2:afterward-s","g6-p1-p2:adverb:3:almost","g6-p1-p2:conjunction:1:and","g6-p1-p2:conjunction:2:as","g6-p1-p2:conjunction:4:but","g6-p1-p2:conjunction:5:if","g6-p1-p2:conjunction:6:or","g6-p1-p2:continents:2:australia","g6-p1-p2:country:5:uk-united-kingdom","g6-p1-p2:country:6:u-s-united-states","g6-p1-p2:country:7:britain","g6-p1-p2:country:11:russia","g6-p1-p2:people-language:2:german","g6-p1-p2:people-language:5:russian","g6-p1-p2:people-language:7:australian","g6-p1-p2:noun:5:reading","g6-p1-p2:noun:55:neighbour"],"matchesByG6WordId":{"g6-p1-p2:verbs:1:agree":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00271:agree","word":"agree","partOfSpeech":["verb"],"chineseMeaning":"同意；在討論或協商中達成一致意見","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"verb","forms":["agree","agrees","agreeing","agreed"]}],"examples":[{"english":"After reviewing the contract terms, both parties agreed to proceed with the partnership.","chinese":"在審閱合約條款後，雙方同意繼續合作。"},{"english":"The project manager asked the team to agree on the deadline before presenting it to the client.","chinese":"專案經理要求團隊在向客戶報告前先就截止日期達成一致。"}],"examTips":["介係詞搭配是核心考點：'agree with' 後接人或意見（例如：agree with the manager）；'agree to' 後接建議、計畫或合約條款；'agree on/upon' 則用於雙方對特定主題達成共識。","商業情境應用：在 TOEIC 閱讀 Part 7 常見 'reach an agreement' (達成協議) 或 'sign an agreement' (簽署合約) 等詞組，通常出現在合約談判或政策修訂的書信中。","文法結構注意：'agree' 後方可接不定詞 'to + V' (agree to provide the service)，表示同意執行某項動作。","相似詞辨析：'agree' 指意見一致；'approve' 側重權威性的批准或認可；'accept' 則指接受提議、道歉或邀請，解題時須根據上下文語境選擇。","聽力陷阱提示：在 Part 3 對話中，若聽到 'I couldn't agree more'，其含義是『我完全贊成』，考生常因看到否定詞 couldn't 而誤判為反對。"]}],"g6-p1-p2:verbs:2:announce":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00433:announce","word":"announce","partOfSpeech":["verb"],"chineseMeaning":"宣告；公佈；宣布","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["announce","announces","announcing","announced"]}],"examples":[{"english":"The CEO announced the company's record profits during the annual meeting.","chinese":"執行長在年度會議上宣布了公司創紀錄的利潤。"},{"english":"The airline announced a flight delay due to inclement weather.","chinese":"由於惡劣天氣，航空公司宣布航班延誤。"}],"examTips":["常見搭配詞組：常用於 announce a merger (宣布合併)、announce a new policy (宣布新政策) 或 make a formal announcement (發布正式聲明)。","商業情境應用：在多益中常出現在 Part 4 的公共廣播或 Part 7 的公司新聞稿，用來發布人事異動、產品上市或政策變更。","易混淆詞辨析：announce 強調『公開發布消息』，而 inform 則強調『通知特定對象』。語法上注意：announce something to someone，而 inform someone of something。","聽力與閱讀考點：在聽力測驗中，聽到 'I am pleased to announce...' 或 'We are here to announce...' 通常是主旨題或細節題的關鍵訊號詞。","答題注意事項：注意其名詞形式 announcement，常出現在 Part 5 的詞性題，並常與動詞 make 搭配使用（make an announcement）。"]}],"g6-p1-p2:verbs:3:arrive":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00589:arrive","word":"arrive","partOfSpeech":["verb"],"chineseMeaning":"抵達；到達","categoryZh":"旅遊與交通","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"verb","forms":["arrive","arrives","arriving","arrived"]}],"examples":[{"english":"The flight is scheduled to arrive at 10:00 AM.","chinese":"航班預計於上午 10:00 抵達。"},{"english":"Please inform us when your shipment arrives at our warehouse.","chinese":"請通知我們您的貨物抵達我們倉庫時。"}],"examTips":["介係詞的精確使用：arrive 是不及物動詞，後方必須搭配介係詞，習慣用法為 arrive at (小地點，如機場、車站、辦公室) 或 arrive in (大範圍，如城市、國家)，切記不可使用 arrive to。","與 reach 及 get to 的辨析：在 TOEIC 閱讀中常考動詞辨析，reach 為及物動詞直接加目的地 (reach the office)，get 則必須加 to (get to the office)，而 arrive 需依地點大小選用 at/in。","商業物流與行程情境：常出現在多益 Part 7 的電子郵件或貨物追蹤通知中，常見搭配如 scheduled to arrive (預計抵達)、arrive shortly (即將抵達) 或 arrive in installments (分批抵達)。","文法特性注意事項：arrive 作為不及物動詞，不具備被動語態，考試中若見到 is arrived 等被動結構通常是錯誤選項。","常見副詞搭配：多益聽力中常出現 arrive promptly (準時到達) 或 arrive ahead of schedule (提前到達)，掌握這些片語有助於快速理解行程安排。"]}],"g6-p1-p2:verbs:4:apologize":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00483:apologize","word":"apologize","partOfSpeech":["verb"],"chineseMeaning":"對造成的不便或錯誤表示遺憾並說明原因，以維護關係或彌補過失。","categoryZh":"客戶服務","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["apologize","apologizes","apologizing","apologized"]}],"examples":[{"english":"We apologize for the delay in delivering your order and will expedite the shipment.","chinese":"我們對訂單延遲表示歉意，並將加快出貨速度。"},{"english":"The account manager apologized to the client for the misunderstanding during the conference call.","chinese":"客戶經理在電話會議中對客戶的誤會表示歉意。"}],"examTips":["句型與介系詞搭配：在 TOEIC 考試中最常出現的句型是「apologize to [對象] for [原因]」，例如：We apologize to our customers for the delay。考生需特別注意 for 後面接名詞或 V-ing。","詞性辨析：常與其名詞形式 apology 進行對比考查。在 Part 5 的文法題中，需判斷空格處是否需要動詞，例如：We owe you an apology (名詞) vs. We apologize (動詞) for the error。","商業書信常用副詞：常與 sincerely, profusely 或 formally 等副詞連用，在閱讀測驗的道歉信或 email 中非常常見，是用來表達誠意的關鍵詞。","聽力與閱讀情境：多出現在「取消會議」、「產品瑕疵」或「服務延誤」的情境中。當聽到 apologize 時，通常後續會接續「提供補償」(offer a refund, discount) 或「解釋原因」，這是 Part 3/4 的重要解題線索。","易混淆詞辨析：需區分 apologize 與 regret。apologize 通常用於承認錯誤並致歉，而 regret 可能僅表達對不愉快情況的遺憾（如：We regret to inform you...），不一定代表公司有過失。"]}],"g6-p1-p2:verbs:5:bend":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01028:bend","word":"bend","partOfSpeech":["verb"],"chineseMeaning":"彎曲；屈服；(規則、政策等) 遵守","categoryZh":"辦公日常","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["bend","bends","bending","bent"]}],"examples":[{"english":"Please bend the metal rod slightly to fit the connector.","chinese":"請稍微彎曲金屬棒以使其適合連接器。"},{"english":"All employees are expected to bend to the company's new policy regarding remote work.","chinese":"所有員工都應遵守公司關於遠端工作的新規。"}],"examTips":["多見於聽力測驗第1部分（照片描述）：'bending over' 常指人正彎腰撿拾物品或俯身在櫃檯前，是描述動作的高頻詞彙。","商業情境中的隱喻用法：'bend the rules' 意指通融或稍微調整規定以適應特殊情況，常見於閱讀測驗第7部分的商務往來書信。","常見片語搭配：'bend down'（向下彎腰）或 'bend forward'（向前俯身）常用於描述員工在辦公室或倉庫操作的姿勢。","易混淆詞辨析：需區分 'bend'（彎曲）與 'fold'（折疊，如折疊紙張或衣服），在聽力測驗中兩者代表完全不同的物理動作。","聽力答題重點：在照片描述題中，若選項提到 'bending'，必須確認圖片中人物是否有明顯的軀幹彎曲，而非僅是低頭或傾斜（leaning）。"]}],"g6-p1-p2:verbs:6:borrow":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01183:borrow","word":"borrow","partOfSpeech":["verb"],"chineseMeaning":"借用；向...借入","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["borrow","borrows","borrowing","borrowed"]}],"examples":[{"english":"Could I borrow your pen while I finish this report?","chinese":"我完成這份報告時，能借用你的筆嗎？"},{"english":"The company borrowed a significant amount of capital to fund its expansion.","chinese":"公司借入大量資金以資擴張。"}],"examTips":["動作方向辨析：多益最常考 borrow (借入) 與 lend (借出) 的混淆。borrow 的動作方向是「進入」，句型為 borrow something from someone；而 lend 是「出去」，句型為 lend something to someone。","常見搭配詞：在辦公室情境中，常出現 borrow stationary (借文具)、borrow a projector (借投影機) 或 borrow a manual (借手冊)。","聽力常見陷阱：在 Part 1 或 Part 2 中，聽到 borrow 時要注意主詞是誰。若問句是 Could I borrow your...? 答句常會是 Certainly 或 I am using it right now，用以測試考生對借用情境的反應。","文法考點：borrow 是暫時性的借用，如果是支付租金的借用（如租房、租車），多益會使用 rent 而非 borrow。","替代詞辨析：在較正式的商業金融閱讀 (Part 7) 中，與金錢相關的借貸常用 loan 作為動詞或名詞，而 borrow 則多用於一般的物品借取。"]}],"g6-p1-p2:verbs:7:bounce":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01195:bounce","word":"bounce","partOfSpeech":["verb","noun"],"chineseMeaning":"（球類）彈跳；（想法、情緒）跳躍、傳播","categoryZh":"營運管理","starRating":3,"toeicScoreRange":"600-780","wordForms":[{"partOfSpeech":"verb","forms":["bounce","bounces","bouncing","bounced"]},{"partOfSpeech":"noun","forms":["bounce","bounces"]}],"examples":[{"english":"The ball bounced off the table, disrupting the meeting.","chinese":"球從桌子上彈跳，打斷了會議。"},{"english":"The company hopes its new marketing campaign will bounce ideas around and generate more leads.","chinese":"公司希望新的行銷活動能激發想法並產生更多潛在客戶。"}],"examTips":["金融情境中的支票退票：在多益的金融或商務書信考題中，「bounce」常用來形容支票因存款不足而被銀行退件，常見搭配為「a bounced check」。考生應注意此時其含義與「insufficient funds」(存款不足) 緊密相關。","經濟或業績的快速復甦：常用片語為「bounce back」，意指從挫折、低迷或病痛中快速恢復。在閱讀測驗中，若提到市場(market)或銷售額(sales)在下跌後回升，常會使用此表達方式。","商務溝通中的意見徵詢：片語「bounce ideas off someone」在多益聽力 Part 3 辦公室對話中偶爾出現，表示「找某人討論想法、聽取意見」以測試其可行性，而非物理上的彈跳。","易混淆詞辨析：需區分「bounce」(彈跳/退票) 與「bound」(前往某地的/必定的)。例如「The flight is bound for Seoul」(飛往首爾) 與「The economy will bounce back」(經濟將復甦) 語意截然不同。","答題注意事項：在聽力測驗中，若聽到關於銀行手續費(fee)與支票(check)的對話，出現「bounce」通常暗示交易失敗，需留意後續產生的違約金或補救措施。"]}],"g6-p1-p2:verbs:8:check":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01668:check","word":"check","partOfSpeech":["verb","noun"],"chineseMeaning":"核對；檢查；驗證（文件、帳戶等）","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"verb","forms":["check","checks","checking","checked"]},{"partOfSpeech":"noun","forms":["check","checks"]}],"examples":[{"english":"Please check the invoice for any discrepancies before making payment.","chinese":"付款前，請核對發票是否有任何差異。"},{"english":"The quality control department will check all products before shipment.","chinese":"品質控制部門會在出貨前檢查所有產品。"}],"examTips":["多重詞義辨析：在 TOEIC 中，'check' 作動詞時最常表示『核對、檢查』，如 'check the schedule' (核對行程)；作名詞時則常出現在餐廳情境指『帳單』(The check, please.)，或金融情境指『支票』(pay by check)。","核心搭配詞組：'check in/out' 是飯店與機場場景的必考詞；'double-check' 強重再次確認以確保無誤；'background check' 常見於人事招募(HR)情境中的背景調查。","商業情境應用：常出現在電子郵件或進度報告中，例如 'check the status of the order' (確認訂單狀態) 或 'check for availability' (確認是否有空位/現貨)。","相似詞辨析：在 Part 7 閱讀理解中，'check' 常與 'verify' 或 'confirm' 作為同義詞互換；與 'inspect' 相比，'check' 較為通用，而 'inspect' 則多用於正式的設施或設備安全檢驗。","聽力答題重點：在 Part 2 簡短問答中，若問題包含 'Did you check...?'，正確答案常會提到查看了某種文件或數據庫（如 database, report, log）。"]}],"g6-p1-p2:verbs:9:complete":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01999:complete","word":"complete","partOfSpeech":["adjective","verb"],"chineseMeaning":"完成；全部；完整","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["complete","more complete","most complete"]},{"partOfSpeech":"verb","forms":["complete","completes","completing","completed"]}],"examples":[{"english":"Please complete the form before submitting it to HR.","chinese":"請在提交給人資部門之前填寫完整表格。"},{"english":"The project was completed ahead of schedule and within budget.","chinese":"該專案已在預定時間和預算內完成。"}],"examTips":["詞性雙重身份：在多益中常考動詞「完成、填寫」與形容詞「完整的」。在 Part 5 詞性題中，需辨識其與副詞 (completely) 或名詞 (completion) 的區別。","商業常見搭配：常與行政文書連用，如 'complete a form' (填寫表格)、'complete an application' (完成申請) 或 'complete a survey' (填寫問卷)。在專案管理中則常用 'complete a task/project'。","易混淆辨析：與 'finish' 相比，'complete' 帶有「使之完整、達到要求」的正式感；與 'finalize' 相比，'finalize' 側重於最後階段的「拍板定案」。","考試陷阱：形容詞用法常接在 'a/an/the' 之後修飾名詞，例如 'a complete list of...' (一份完整的清單)；若出現在 Part 3/4 聽力，聽到 'complete' 往往暗示某項任務或流程已結束。","填答要點：若空格前有助動詞 (must, will) 或主詞，應選動詞原型；若空格位於名詞前，則優先考慮形容詞。"]}],"g6-p1-p2:verbs:10:continue":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02221:continue","word":"continue","partOfSpeech":["verb"],"chineseMeaning":"持續進行；延續","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["continue","continues","continuing","continued"]}],"examples":[{"english":"Please continue with your presentation; we're all eager to hear the next section.","chinese":"請繼續您的簡報，我們都期待聽到下一部分。"},{"english":"The company will continue to invest in research and development to maintain its competitive edge.","chinese":"公司將繼續投資於研發，以保持其競爭優勢。"}],"examTips":["語法結構與搭配：continue 後方可接不定詞 (to + V) 或動名詞 (V-ing)，語意幾乎相同，例如：'continue to work' 或 'continue working'。此外，'continue with + 名詞' 常用於表示『繼續進行某項任務或計畫』。","商業應用情境：在多益閱讀中常出現在『合約續約』(continue the contract) 或『職業教育』(continuing education) 的情境。另外，在會議記錄中常用來描述『會議將於稍後繼續』(the meeting will continue after lunch)。","易混淆詞辨析：需特別區分 'continue' (持續進行) 與 'resume' (中斷後重新開始)。在聽力測驗關於行程變動的題目中，若活動是因故暫停再開啟，正確答案通常會選 'resume' 而非 'continue'。","常考衍生詞：多益常考其形容詞 continuous (連續不斷的，強調中間無間斷) 與 continual (頻繁發生的，強調反覆發生)。在 Part 5 詞彙題中，需根據語境判斷是強調『不間斷』還是『斷斷續續的重複』。","聽力測驗陷阱：在 Part 3 或 Part 4 的商務報告中，當聽到 'continue' 時，考生應留意接下來提到的時間點或條件，這通常是關於計畫時程或後續步驟的考點。"]}],"g6-p1-p2:verbs:11:cover":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02389:cover","word":"cover","partOfSpeech":["noun","verb","adjective"],"chineseMeaning":"覆蓋；涵蓋；包覆；（文件、新聞等）報導","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["cover","covers"]},{"partOfSpeech":"verb","forms":["cover","covers","covering","covered"]},{"partOfSpeech":"adjective","forms":["cover","more covered","most covered"]}],"examples":[{"english":"The report needs to cover all aspects of the project's progress.","chinese":"這份報告需要涵蓋專案進度的所有面向。"},{"english":"Please cover your expenses during the business trip.","chinese":"請支付您的出差費用。"}],"examTips":["多樣化的商業釋義：在多益中 'cover' 最常見的含意並非字面的「蓋上」，而是「支付或負擔（費用）」，例如 cover the costs 或 cover the expenses，常出現在財務報表或出差報銷的情境中。","辦公室代班情境：在聽力 Part 3 或閱讀 Part 7 中，'cover someone's shift' 或 'cover for someone' 意指「代班」或「代理工作」，是常見的人事溝通考點。","保險與保障：當出現於保險合約情境時，'cover' 代表「保障範圍」或「理賠內容」，常見搭配為 insurance coverage 或 be covered by a policy。","易混淆詞辨析：注意 'cover' 與 'report' 的關聯，當作為媒體用語時，'cover a story' 是指報導某個新聞。與 'include' 的區別在於，'cover' 更多時候強調「足以支付」或「範圍涵蓋」。","答題重點：在 Part 5 詞彙題中，若空格後接 expenses (費用) 或 topic (話題)，應優先考慮 cover 作為正確選項。"]}],"g6-p1-p2:verbs:12:describe":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02778:describe","word":"describe","partOfSpeech":["verb"],"chineseMeaning":"描述；詳細說明（某事物或情境）","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"verb","forms":["describe","describes","describing","described"]}],"examples":[{"english":"Could you describe the problem you're experiencing with the software?","chinese":"您能描述一下您在使用軟體時遇到的問題嗎？"},{"english":"The project manager needs to describe the project's scope and objectives to the new team members.","chinese":"專案經理需要向新團隊成員描述專案的範圍和目標。"}],"examTips":["常見搭配詞：'describe in detail' (詳細描述) 與 'accurately describe' (精確描述) 常出現在閱讀測驗中，用來修飾產品說明或報表分析。","商業情境應用：此單字常出現在 Job Description (職位描述) 中，用來列舉應徵者的職責與必要技能。在產品開發中，則用於描述產品特點 (describe the features)。","易混淆詞辨析：需區分 'describe' (描述) 與 'prescribe' (開處方/規定)。TOEIC 聽力測驗中有時會利用發音相近的特點設定陷阱，需根據上下文判斷。","詞性變化考點：在 Part 5 語法題中，常考 'description' (名詞) 的形式，例如：'beyond description' (難以言表) 或 'fit the description' (符合描述)。","答題注意事項：在 Part 3 或 Part 4 的聽力中，若聽到 'Can you describe the issue?'，答案通常會指向具體的問題細節或故障情況，考生應留心接下來出現的細節名詞。"]}],"g6-p1-p2:verbs:13:explain":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03687:explain","word":"explain","partOfSpeech":["verb"],"chineseMeaning":"解釋；闡明；說明理由","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["explain","explains","explaining","explained"]}],"examples":[{"english":"Could you explain the reason for the project's delay to the stakeholders?","chinese":"您能向利害關係人解釋專案延遲的原因嗎？"},{"english":"The consultant will explain the new policy to all employees during the training session.","chinese":"顧問將在培訓課程中向所有員工解釋新的政策。"}],"examTips":["句型結構陷阱：explain 最核心的考點在於其句型結構為 'explain + 事物 + to + 人'。在 Part 5 中常出現 'explain me' 的錯誤選項，正確必須是 'explain to me'，這一點與 tell 或 inform 的用法完全不同。","商業情境應用：常出現在教育訓練或政策變更情境中，常見搭配詞如 explain the procedure (解釋程序)、explain the policy (解釋政策) 或 explain the technical specifications (解釋技術規格)。","聽力關鍵字：在 Part 3 和 Part 4 中，當說話者提到 'Let me explain...' 時，通常後面會緊跟著關於「操作方式」或「問題原因」的細節資訊，是答題的重要訊號。","詞類變化：考生需熟記其名詞形式 explanation。在 Part 6 閱讀填空題中，常考 provide a detailed explanation (提供詳盡解釋) 或 ask for a further explanation (要求進一步解釋) 等片語。","近義詞辨析：在 TOEIC 中，explain 與 clarify (澄清) 經常互換，但 clarify 更常用於消除誤解或確認細節；而與 describe (描述) 相比，explain 更強調說明原因或運作邏輯。"]}],"g6-p1-p2:verbs:14:enter":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03460:enter","word":"enter","partOfSpeech":["noun","verb"],"chineseMeaning":"進入；輸入（資料或資訊）","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["enter","enters"]},{"partOfSpeech":"verb","forms":["enter","enters","entering","entered"]}],"examples":[{"english":"Please enter your employee ID into the system before logging in.","chinese":"請在登入前將您的員工編號輸入系統。"},{"english":"The sales team will enter the new client data into the CRM by Friday.","chinese":"銷售團隊將於週五前將新客戶資料輸入 CRM 系統。"}],"examTips":["及物動詞與介係詞用法：在表示「進入空間」時，enter 為及物動詞，直接加地點（例如 enter the office），不加 into。但在商業合約情境，「enter into a contract/agreement」（簽訂合約）是固定用法，為常見考點。","資料處理情境：在辦公室情境中，enter 常指「輸入資訊」，搭配詞包含 enter data、enter information 或 enter a password，常用於聽力測驗的辦公設備操作對話。","市場經營用法：在商業閱讀（Part 7）中，enter the market 指「進入市場」，常用來描述公司業務擴張或競爭分析。","詞性辨析：注意其名詞 entry 與 entrance 的區別；entrance 指物理上的入口（如 entrance of the building），而 entry 除了指進入的動作，也指「報名參加」或「（會計）分錄」。","答題注意事項：若在文法題（Part 5）看到 enter 後面接 empty space，需先判斷受詞是實體空間還是抽象概念，以決定是否需要搭配 into。"]}],"g6-p1-p2:verbs:15:fill":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03900:fill","word":"fill","partOfSpeech":["verb","noun"],"chineseMeaning":"填寫；填充；裝滿；（文件等）填寫","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"verb","forms":["fill","fills","filling","filled"]},{"partOfSpeech":"noun","forms":["fill","fills"]}],"examples":[{"english":"Please fill out this form with your personal information before the meeting.","chinese":"請在會議前用您的個人資訊填寫此表格。"},{"english":"The warehouse needs to fill the order with 500 units of the product.","chinese":"倉庫需要用 500 個產品單位來完成訂單。"}],"examTips":["常見搭配詞與短語：多益最常考『fill out a form』（填寫表格）與『fill a position/vacancy』（補足職缺）。","商業情境應用：在供應鏈管理中，『fill an order』表示『履行訂單』或『出貨』，這是閱讀測驗 Part 7 的常見主題。","易混淆詞辨析：『fill out』多指完成整份申請書，而『fill in』通常指填寫特定空格；另外要注意『fulfill』與『fill』在『履行義務/訂單』時意義相近，但『fill』更常用於具體的職位遞補。","考試出題重點：在 Part 5 文法題中，常出現『fill the role』或『fill the requirement』，考查考生對商務動詞搭配的熟悉度。","聽力測驗技巧：在聽力 Part 1 或 Part 2 中，若聽到與表格（document/form）相關的對話，答案選項中常會出現 fill out 或 fill in 作為正確動作的描述。"]}],"g6-p1-p2:verbs:16:reach":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08138:reach","word":"reach","partOfSpeech":["verb","noun"],"chineseMeaning":"（達到）達成、接觸到、伸及","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["reach","reaches","reaching","reached"]},{"partOfSpeech":"noun","forms":["reach","reaches"]}],"examples":[{"english":"The company aims to reach a sales target of $1 million this quarter.","chinese":"本公司本季目標達成 100 萬美元的銷售額。"},{"english":"Please reach out to the project manager if you have any questions.","chinese":"如果您有任何問題，請聯繫專案經理。"}],"examTips":["常見搭配詞：在多益閱讀與聽力中，常出現 'reach an agreement' (達成協議)、'reach a consensus' (達成共識) 或 'reach a goal/target' (達成目標)，這是典型的商業談判與績效考核用語。","商業聯繫情境：常用於表達「聯絡某人」，例如在商務郵件末尾提到 'I can be reached at [phone number/email]' (可以透過...聯絡到我)，是多益 Part 7 閱讀的高頻考點。","文法辨析：'reach' 為及物動詞，後方直接加地點或受詞（如 reach the office），不可像 'arrive' (arrive at/in) 或 'get' (get to) 那樣加上介系詞，這在 Part 5 詞彙與文法題中極為常見。","市場行銷意義：在行銷情境下，'reach' 指「觸及受眾」，如 'reach a wider audience' (接觸更廣泛的觀眾) 或 'reach the target market' (觸及目標市場)。","慣用語辨識：注意 'within reach' (在手邊、指日可待) 與 'out of reach' (拿不到、力所不及) 的對比，常出現在描述物品擺放位置或目標可行性的情境中。"]}],"g6-p1-p2:verbs:17:receive":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08197:receive","word":"receive","partOfSpeech":["verb"],"chineseMeaning":"收到；獲得","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["receive","receives","receiving","received"]}],"examples":[{"english":"Please ensure all invoices are received by the accounting department before the deadline.","chinese":"請確保所有發票在截止日期前已收到會計部門。"},{"english":"The company will receive a shipment of new equipment next week.","chinese":"本公司下週將收到一批新設備。"}],"examTips":["常見搭配詞：在多益測驗中，receive 常與商務文件或財務相關詞彙搭配，如 receive a confirmation (收到確認)、receive an invoice (收到發票)、receive a refund (收到退款) 以及 receive a promotion (獲得晉升)。","商業情境應用：主要出現在電子郵件、物流追蹤及客服情境中。需特別注意其名詞形式 receipt (收據)，該字在聽力測驗中 p 不發音，且常出現在 Part 3 關於報帳或購物糾紛的對話。","易混淆詞辨析：考生需區分 receive 與 accept。receive 強調「收到」這個動作或事實（中性）；而 accept 則強調「接受、認可」的主觀意願（積極）。例如：He received the invitation but didn't accept it.","閱讀測驗考點：在 Part 7 閱讀理解中，receive 常作為同義字替換題的目標，常見的替換詞包括 get、obtain 或 acquire。此外，需留意其被動語態用法，如 The package was received by the front desk。","聽力陷阱：注意 receive 與 perceive (察覺)、deceive (欺騙) 等詞的發音差異。在 Part 1 圖片描述題中，若出現人員正在簽收包裹，描述句可能會使用 is receiving a package 或 is signing for a delivery。"]}],"g6-p1-p2:verbs:18:return":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08622:return","word":"return","partOfSpeech":["verb","noun"],"chineseMeaning":"歸還；返回；（商品）退回","categoryZh":"採購與物流","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"verb","forms":["return","returns","returning","returned"]},{"partOfSpeech":"noun","forms":["return","returns"]}],"examples":[{"english":"The supplier will return the defective goods within one week.","chinese":"供應商將在一週內退回有缺陷的商品。"},{"english":"Please return the completed form to the HR department by Friday.","chinese":"請在星期五前將填寫完畢的表格歸還給人資部門。"}],"examTips":["常見搭配詞與商務情境：在聽力與短對話中，'return a call' (回電) 是基礎考點；在零售情境中，'return an item' (退貨) 與 'return policy' (退貨政策) 極為常見。","財經專業術語辨析：'tax return' 意指「納稅申報單」而非退稅，這與考生常混淆的 'tax refund' (退稅金) 需嚴格區分。另外，'return on investment' (ROI) 指的是「投資報酬率」，此時 return 代表收益。","交通情境用法：在 Part 3 或 Part 4 的交通資訊中，英式英語常用 'return ticket' 來表示「來回票」(美式為 round-trip ticket)。","易混淆詞辨析：'return' 是指歸還物品的「行為」，而 'refund' 指的是退回來的「款項」。在閱讀測驗中，若提到物品損壞，通常會詢問是否 return (退貨) 以換取 refund (退款)。","固定片語考點：在 Part 5 文法題中，常考 'in return for' (作為...的回報) 的介係詞搭配，或是 'return to work' (復工) 等情境語境。"]}],"g6-p1-p2:verbs:19:repeat":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08473:repeat","word":"repeat","partOfSpeech":["verb","noun"],"chineseMeaning":"重複；重申；再次執行","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"verb","forms":["repeat","repeats","repeating","repeated"]},{"partOfSpeech":"noun","forms":["repeat","repeats"]}],"examples":[{"english":"Could you please repeat that? I didn't quite catch what you said.","chinese":"您能再重複一遍嗎？我沒有完全聽清楚。"},{"english":"The system automatically repeats the transaction if there's an error.","chinese":"如果出現錯誤，系統會自動重覆執行該交易。"}],"examTips":["常見搭配詞：在多益考試中，'repeat customer' (老顧客) 與 'repeat business' (回頭客) 是極高頻的複合名詞，常用於市場行銷或顧客滿意度調查情境。","商業應用：常用於請求重複訊息，如聽力測驗中對話者常說 'I beg your pardon? Could you repeat the address?'，這通常暗示接下來會出現答題關鍵字。","易混淆詞：'repeat' 是普通重複；'reiterate' (重申) 多用於會議中強調論點；'duplicate' 則指製作副本或重複進行已做過的工作（常帶有負面冗餘感）。","聽力考點：在 Part 1 或 Part 3 中，若出現 'repeating' 動作，常指在生產線上重複性操作，或在會議中重複對方的要求以確認細節。","文法注意：'repeat' 作為形容詞修飾名詞時，通常直接使用原型如 'repeat order'，而名詞形式為 'repetition'，需注意詞性填空題中的變化。"]}],"g6-p1-p2:verbs:20:remind":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08428:remind","word":"remind","partOfSpeech":["verb"],"chineseMeaning":"提醒；使想起","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["remind","reminds","reminding","reminded"]}],"examples":[{"english":"Please remind me to submit the report by Friday.","chinese":"請提醒我週五前提交報告。"},{"english":"The system will remind users to update their passwords regularly.","chinese":"系統會定期提醒使用者更新密碼。"}],"examTips":["核心語法結構：在多益考試中，remind 最常出現的句型為「remind someone to do something」（提醒某人去做某事）或「remind someone of something」（使某人想起某事）。注意其後方必須先接「人」作為受詞。","商務書信情境：此單字頻繁出現在 Part 6 與 Part 7 的電子郵件中，常見用法如「friendly reminder」（溫馨提醒），用於催繳款項、確認會議時間或提醒截止日期。","易混淆詞辨析：最常與 remember 混淆。remember 是「自己主觀記得」，而 remind 是「他人客觀提醒」。若空格後有受詞（人），通常應選 remind。","聽力與閱讀考點：在 Part 3 對話或 Part 4 簡短談話中，remind 常作為行動建議的出題重點。若聽到「I will remind the manager」，答案選項常會對應到「He will contact his supervisor」。","被動語態應用：在辦公室公告中常使用被動語態「Please be reminded that...」或「Staff are reminded to...」，後方常接 that 子句或 to 不定詞，這是多益文法題的常見考點。"]}],"g6-p1-p2:verbs:21:search":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08927:search","word":"search","partOfSpeech":["verb","noun"],"chineseMeaning":"搜尋；尋找（資訊、資料、資源等）","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["search","searches","searching","searched"]},{"partOfSpeech":"noun","forms":["search","searches"]}],"examples":[{"english":"The HR department is currently searching for a qualified accountant.","chinese":"人資部門目前正在搜尋一位合格的會計師。"},{"english":"Before making a purchase, it's advisable to search online for the best deals.","chinese":"在購買之前，建議在網上搜尋最佳優惠。"}],"examTips":["介係詞的關鍵用法：'search for' 是最頻率最高的考點，其後接尋找的目標（如 search for a replacement）；若 search 後直接接地點或物體，則表示對該處進行搜查（如 search the records）。","商業搭配詞（Collocations）：在職涯與行政情境中，常見 'job search'（求職）、'conduct a search'（進行搜尋）及 'executive search firm'（高階獵人頭公司）。","易混淆詞辨析：'search' 與 'find' 不同，search 強調尋找的『過程』，而 find 則強調『結果』；與 'seek' 相比，'seek' 語氣較正式且常用於抽象目標（如 seek assistance）。","聽力與閱讀的改寫（Paraphrasing）：在聽力測驗中，對話中的 'search' 經常在答案選項中被替換成 'look for'、'hunt for' 或 'try to find'，考生應建立同義詞連結。","科技情境應用：在 Part 7 的電子郵件或說明書中，'search engine'（搜尋引擎）與 'search criteria'（搜尋條件）是與資訊檢索相關的常見術語，需熟悉其在辦公室數位工具操作中的語境。"]}],"g6-p1-p2:verbs:22:separate":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09023:separate","word":"separate","partOfSpeech":["verb","adjective"],"chineseMeaning":"將...分開；區分；使獨立","categoryZh":"辦公日常","starRating":4,"toeicScoreRange":"600-780","wordForms":[{"partOfSpeech":"verb","forms":["separate","separates","separating","separated"]},{"partOfSpeech":"adjective","forms":["separate","more separate","most separate"]}],"examples":[{"english":"Please separate the invoices by date for easier reconciliation.","chinese":"請將發票按日期分開，以便更輕鬆地對帳。"},{"english":"The company decided to separate the marketing and sales departments to improve efficiency.","chinese":"為了提高效率，公司決定將行銷和銷售部門分開。"}],"examTips":["詞性與發音辨析：作動詞時發音為 /'sɛpəˌreɪt/，意為「分開、隔離」；作形容詞時發音為 /'sɛpərɪt/，意為「各別的、獨立的」。在聽力測驗中，需透過上下文判斷其詞性以理解句意。","商業信函常見用法：高頻短語 'under separate cover' 表示附件或物品「另行寄送」，這在閱讀測驗 Part 6 與 Part 7 的商業書信中是極為關鍵的固定用法。","常見搭配詞組：動詞時常接介系詞 from（separate A from B）；而在餐飲或商務活動中，'separate checks'（分開結帳）與 'separate accounts'（獨立帳戶）是多益聽力 Part 2 與 Part 3 的常見情境。","易混淆詞辨析：與 'divide' 相比，'separate' 強調的是「使本來在一起的人或物分開」，或強調個體間的「獨立性」；'divide' 則側重於「將一個整體切割成數份」。","文法考點：在 Part 5 中常考形容詞用法，特別是作為受詞補語的結構，例如 'please keep the two files separate'（請將這兩份檔案分開放），考生常會誤選副詞 separately。"]}],"g6-p1-p2:verbs:23:spend":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09480:spend","word":"spend","partOfSpeech":["verb","noun"],"chineseMeaning":"花費（金錢、時間、精力等）；使用","categoryZh":"金融與會計","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"verb","forms":["spend","spends","spending","spent"]},{"partOfSpeech":"noun","forms":["spend","spends"]}],"examples":[{"english":"The company plans to spend $5 million on marketing campaigns this quarter.","chinese":"本公司計劃在本季投放 500 萬美元用於行銷活動。"},{"english":"We need to spend more time training our employees to improve their skills.","chinese":"我們需要花更多時間培訓員工，以提升他們的技能。"}],"examTips":["核心文法結構：spend 的受詞後接動作時，必須使用動名詞 V-ing，不可使用不定詞 to-V。例如：spend time preparing the report。","介係詞用法：若受詞後接名詞，需搭配介係詞 on，例如：spend money on office supplies。在多益 Part 5 中常考此介係詞的搭配。","易混淆詞辨析：spend 的主詞必須是「人」。若主詞是「事物」，花費金錢需用 cost (e.g., The laptop cost $1,000)，花費時間則用 take (e.g., It took three hours to fly to Tokyo)。","商業情境應用：常出現在預算編列（budgeting）與資源分配的對話中，常見搭配詞如 spend a fortune (花大筆錢)、spend a budget (花費預算)。","詞性轉換：在閱讀測驗中，spend 有時會以名詞形式出現（如 total spend），意指「開支」或「花費額」，此用法在商業分析報告中非常普遍。"]}],"g6-p1-p2:verbs:24:report":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08489:report","word":"report","partOfSpeech":["noun","verb"],"chineseMeaning":"報告；陳述；（對某事）匯報","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["report","reports"]},{"partOfSpeech":"verb","forms":["report","reports","reporting","reported"]}],"examples":[{"english":"The marketing team needs to submit a quarterly sales report by the end of the month.","chinese":"行銷團隊需要在月底前提交一份季度銷售報告。"},{"english":"Please report any technical issues to the IT department immediately.","chinese":"請立即向 IT 部門報告任何技術問題。"}],"examTips":["常見搭配詞組與商務情境：'annual report' (年度報告)、'progress report' (進度報告) 與 'weather report' (天氣預報) 是聽力與閱讀的高頻詞彙。在商務書信中，'submit a report' (提交報告) 是標準用法。","職務隸屬關係：動詞用法 'report to [position/person]' 指的是「向某人匯報工作」或「其直接下屬」。例如 'The sales team reports to the director'，這在 Part 7 的組織結構題中是判斷職位層級的重要線索。","多義詞辨析：在 TOEIC 考試中，'report' 除了「報告」，還常指「報到」 (report to the front desk/security)，在聽力測驗中若聽到地點搭配，應優先考慮報到之意。","相似詞區分：'report' (具分析性質的報告) 與 'statement' (描述事實的聲明或帳單，如 bank statement) 需區分。'report' 通常包含調查結果與建議。","聽力考點提醒：在 Part 1 照片描述中，若看到人物在會議室看投影片，選項常出現 'presenting a report' (發表報告)；在 Part 3 & 4 中，注意 report 後方接的介係詞，如 'report on [topic]' 表示關於某主題的報告。"]}],"g6-p1-p2:verbs:25:clap":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01769:clap","word":"clap","partOfSpeech":["verb","noun"],"chineseMeaning":"拍手；（表示鼓勵、讚許等）拍掌","categoryZh":"溝通互動","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["clap","claps","clapping","clapped"]},{"partOfSpeech":"noun","forms":["clap","claps"]}],"examples":[{"english":"The audience clapped enthusiastically after the CEO's inspiring speech.","chinese":"在執行長發表演講後，觀眾熱烈地鼓掌。"},{"english":"Let's give a round of applause to the team for their successful project completion.","chinese":"讓我們為團隊成功完成專案而鼓掌。"}],"examTips":["在多益聽力第一大題（照片描述）中，clap 常與 applaud 互為替換詞。若照片中出現觀眾拍手，選項可能會用 'The audience is clapping' 或 'The crowd is applauding'。","常見搭配詞為 'clap for someone'，在商業慶祝會、頒獎典禮或演講結束後，主持人可能會說 'Please clap for our speaker' 或 'Let's give them a big round of applause' 以表讚賞。","注意易混淆詞 'clasp'（緊握、扣住），例如 'clasp hands' (握手/緊握雙手)，雖然發音與 clap 相近，但在商務情境中的意義完全不同。","在閱讀測驗中，此字可能出現在公司內部的通訊、新聞稿或活動側寫中，描述某個成功的專案或傑出員工獲得表揚的情境。","答題注意事項：clap 是規則動詞，其過去式與過去分詞需重複字尾 p 再加 ed (clapped)，在聽力辨識時需注意其閉鎖音的發音特點。"]}],"g6-p1-p2:verbs:26:rule":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08759:rule","word":"rule","partOfSpeech":["noun","verb"],"chineseMeaning":"規定；法則；規則","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["rule","rules"]},{"partOfSpeech":"verb","forms":["rule","rules","ruling","ruled"]}],"examples":[{"english":"All employees must follow company rules regarding internet usage.","chinese":"所有員工都必須遵守關於網路使用的公司規定。"},{"english":"The manager ruled that overtime work was necessary to meet the deadline.","chinese":"經理裁定為了趕上截止日期，必須加班。"}],"examTips":["詞性與多義性：名詞指「規則、規章」，例如 safety rules（安全守則）；動詞指「裁定、統治」，商務情境中常指法院或委員會做出正式決定。","必考片語 rule out：意為「排除、不考慮」，是 TOEIC 閱讀的高頻片語，例如 We cannot rule out the possibility of a delay（我們不能排除延期的可能性）。","常見搭配：常與動詞 follow、obey、comply with（遵守）或 break（違反）搭配使用；介係詞片語 as a general rule（通常、一般而言）也常出現在聽力與閱讀中。","相似詞辨析：rule 是規則的統稱；regulation 較正式，指政府或機構的「規章、法規」；policy 指公司的「政策」；procedure 則強調操作的「流程、步驟」。","考試重點：在 Part 5 詞彙題中常考與「遵守」相關的動詞搭配，在 Part 7 閱讀中若出現 rule change，通常是答案關鍵點，需特別注意新規則的實施日期或對象。"]}],"g6-p1-p2:verbs:27:travel":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10439:travel","word":"travel","partOfSpeech":["verb","noun"],"chineseMeaning":"出差、旅行（通常指商務目的的旅行）","categoryZh":"旅遊與交通","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["travel","travels","traveling","traveled"]},{"partOfSpeech":"noun","forms":["travel","travels"]}],"examples":[{"english":"The company reimburses employees for all travel expenses incurred during business trips.","chinese":"公司會退償員工在出差期間產生的所有差旅費用。"},{"english":"Frequent travel is often required for sales representatives to meet with clients.","chinese":"銷售代表通常需要頻繁出差以拜訪客戶。"}],"examTips":["常見搭配詞與情境：在多益考試中，此單字頻繁出現於商務出差情境，常見詞組如 'travel arrangements' (行程安排)、'travel expenses' (差旅費) 及 'business travel' (商務旅行)。","易混淆詞辨析：'travel' 通常作為不可數名詞或動詞使用，泛指「旅行」的概念；而 'trip' 是可數名詞，指一段具體的「旅程」。在填空題中，若空格前有不定冠詞 'a'，應選擇 'trip' 而非 'travel'。","聽力與閱讀考點：常出現在聽力第三、四大題及閱讀第七大題，情境多涉及機票預訂、飯店退改或行程變更。此外，常與 'reimbursement' (核銷/報帳) 連用，討論出差後費用的申請流程。","答題注意事項：需區分 'travel' 與 'commute' (通勤)。若題目描述的是每日往返住家與辦公室，正確選項通常是 'commute'；若涉及跨城市、跨國或長時間的公務行程，則使用 'travel'。"]}],"g6-p1-p2:verbs:28:wish":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:11112:wish","word":"wish","partOfSpeech":["verb","noun"],"chineseMeaning":"希望、期望；祝願","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["wish","wishes","wishing","wished"]},{"partOfSpeech":"noun","forms":["wish","wishes"]}],"examples":[{"english":"I wish to confirm my reservation for tomorrow morning.","chinese":"我希望確認我明天早上的預訂。"},{"english":"We wish you a successful business trip and a profitable quarter.","chinese":"祝您旅途順利，本季度業績豐厚。"}],"examTips":["語法重點：'wish' 常接虛擬語氣。對現在事實相反的願望使用過去式（如：I wish I were...），對過去遺憾則用過去完成式（如：I wish I had been...），這在閱讀測驗中常考語法時態。","區分 wish 與 hope：'hope' 用於可能實現的事情，而 'wish' 多用於表達難以實現的願望或正式請求。","商業書信應用：在正式書信結尾常用 'Best wishes'，或在詢問意願時使用 'If you wish to unsubscribe...' 作為 'want' 的正式替代詞。","常見搭配詞：'wish to do something'（等同於 want to）、'wish someone luck/success'（祝某人成功）。","聽力測驗陷阱：注意說話者使用 wish 時通常帶有「事與願違」或「遺憾」的情緒，有助於判斷對話隱含的意思或接下來的行動。"]}],"g6-p1-p2:verbs:29:work":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:11146:work","word":"work","partOfSpeech":["noun","verb"],"chineseMeaning":"工作；勞動；職責；業務","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["work","works"]},{"partOfSpeech":"verb","forms":["work","works","working","worked"]}],"examples":[{"english":"The project requires a lot of hard work to meet the deadline.","chinese":"為了趕上截止日期，這個項目需要投入大量的努力。"},{"english":"Employees are expected to work efficiently and collaboratively.","chinese":"員工預期能高效且協作地工作。"}],"examTips":["詞性與可數性辨析：在多益中，work 作為「工作/勞動」時為不可數名詞，不可加 s 或 a；但若指「作品/著作」則是可數的。","常見搭配詞：work overtime (加班)、work remotely (遠端辦公)、work on a project (致力於某計畫)。","常考片語：work out (解決問題、健身)、work around (避開困難)。","與 job 的區別：Job 是可數名詞，指特定的職位或任務；Work 是較廣義的不可數概念。","聽力考點：Part 1 照片題常出現 working at a desk (在書桌前工作) 或 working on a laptop (使用筆電) 的描述。"]}],"g6-p1-p2:verbs:30:cough":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02352:cough","word":"cough","partOfSpeech":["noun","verb"],"chineseMeaning":"咳嗽；(因感冒等引起的) 咳聲","categoryZh":"溝通互動","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["cough","coughes"]},{"partOfSpeech":"verb","forms":["cough","coughes","coughing","coughed"]}],"examples":[{"english":"The meeting was briefly interrupted when Mr. Lee started coughing.","chinese":"當李先生開始咳嗽時，會議被暫停了一下。"},{"english":"Please cover your mouth when you cough to prevent the spread of germs.","chinese":"請咳嗽時遮住嘴巴，以防止細菌傳播。"}],"examTips":["常見搭配詞：'persistent cough' (持續咳嗽)、'cough drops' (喉糖) 及 'cough syrup' (止咳糖漿)，常出現在藥局、門診或辦公室對話情境中。","商業情境應用：常出現在多益聽力 Part 3 的對話中，作為員工請病假 (sick leave) 的理由，或在 Part 7 的公司內部公告中提醒員工若有症狀應居家辦公。","聽力辨析：注意發音為 /kɔːf/，尾音是 /f/，需與 'coach' /koʊtʃ/ (教練) 及 'caught' /kɔːt/ (catch 的過去式) 進行區分，避免因發音相近而誤選。","閱讀考點：在閱讀測驗中，cough 常與 'symptoms' (症狀)、'pharmacy' (藥局) 或 'appointment' (預約) 等詞彙共同出現，考生應熟悉這類醫療健康相關的字組。","答題技巧：若在對話中聽到角色正在咳嗽，隨後的題目往往會詢問該角色的身體狀況或接下來的行動（如：去休息、去看醫生），掌握 cough 的關鍵訊號有助於快速定位正確答案。"]}],"g6-p1-p2:verbs:31:headache":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04685:headache","word":"headache","partOfSpeech":["noun"],"chineseMeaning":"頭痛；頭部不適","categoryZh":"辦公日常","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["headache","headaches"]}],"examples":[{"english":"I'm sorry, I can't focus on this presentation; I have a terrible headache.","chinese":"抱歉，我無法專注於這個簡報，因為我頭痛欲裂。"},{"english":"The employee requested to work from home today due to a persistent headache.","chinese":"這位員工因為持續的頭痛，請求今天在家工作。"}],"examTips":["雙重語意應用：在多益考試中，headache 除指生理上的『頭痛』外，在商業情境中極常被用來隱喻『令人頭痛的棘手問題』或『麻煩事』。","聽力與閱讀情境：生理意義多見於 Part 3 醫務或請假場景，而抽象意義則常見於 Part 7 的內部郵件或備忘錄，如指稱物流延遲（shipping delays）或預算縮減（budget cuts）是一個 major headache。","常見搭配詞：生理層面常接 have/develop a headache，形容嚴重時用 splitting headache；抽象層面常搭配 give someone a headache 或 a headache for the management。","辨析與替換：在克漏字（Part 6）或閱讀中，其同義詞可能為 nuisance, problem, 或 troublesome issue。","答題關鍵：若在商業對話中聽到此詞，應立即反應說話者正對某個程序或狀況感到困擾，而非單純身體不適。"]}],"g6-p1-p2:verbs:32:present":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:07708:present","word":"present","partOfSpeech":["noun","verb","adjective"],"chineseMeaning":"贈送物；禮物；當前；呈現","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["present","presents"]},{"partOfSpeech":"verb","forms":["present","presents","presenting","presented"]},{"partOfSpeech":"adjective","forms":["present","more present","most present"]}],"examples":[{"english":"The company presented a commemorative plaque to the retiring employee.","chinese":"公司向即將退休的員工贈送了一塊紀念牌匾。"},{"english":"Please present your business card when you meet the potential client.","chinese":"見面時請向潛在客戶展示您的名片。"}],"examTips":["注意詞性與發音的切換：當動詞時發音為 [prɪˈzent]，重音在後，意為『呈現、遞交、頒發』，如 present a proposal (提出提案) 或 present an award (頒獎)；當名詞或形容詞時發音為 [ˈpreznt]，重音在前，分別代表『禮物/現在』或『出席的/目前的』。","商業常見搭配詞：在閱讀測驗中常考 present identification (出示身分證件) 或 present a valid coupon (出示有效優惠券)。在辦公室情境中，present a report 指的是提交報告。","出席與缺席考點：形容詞用法 be present at the meeting (出席會議) 是聽力與閱讀的高頻詞彙，常用來描述人員動態，反義詞為 absent。","詞性辨析：在 Part 5 填空題中，需區分 present (動詞/形容詞)、presentation (名詞：簡報/呈現) 以及 presenter (名詞：主持人/報告者)。例如，give a presentation 是常見的商務活動。","時間副詞用法：presently 在多益中多指『目前』或『不久後』，常與現在進行式或未來式連用，解題時需留意語境中的時間線索。"]}],"g6-p1-p2:verbs:33:schedule":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08884:schedule","word":"schedule","partOfSpeech":["noun","verb"],"chineseMeaning":"排程；時間表；安排","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["schedule","schedules"]},{"partOfSpeech":"verb","forms":["schedule","schedules","scheduling","scheduled"]}],"examples":[{"english":"Please check your schedule for tomorrow's meeting with the marketing team.","chinese":"請查看明天與行銷團隊的會議排程。"},{"english":"We need to schedule a follow-up call with the potential client next week.","chinese":"我們需要在下週安排與潛在客戶的後續電話。"}],"examTips":["常見固定搭配詞組：'ahead of schedule' (超前進度)、'behind schedule' (進度落後) 及 'on schedule' (準時)，這些是 Part 5 介系詞填空的高頻考點。","商業情境中的詞性轉換：'schedule' 可作名詞（行程表）或動詞（安排）。例如：'be scheduled to + 原形動詞' (預定要做某事)，在聽力測驗中常用於確認會議或面試時間。","易混淆詞辨析：需區分 'schedule' (總體時間進度表)、'agenda' (會議議程) 與 'itinerary' (細節旅遊行程)，TOEIC 閱讀常在 Part 7 的商業信函或通知中測試考生對情境用字精確度的理解。","聽力測驗發音陷阱：注意美式與英式發音的顯著差異（美式讀作 /'skɛdʒul/，英式讀作 /'ʃɛdju:l/）。當對話中提到 'reschedule' (重新安排) 時，通常暗示原定計畫有變，考生應立即留意後續提到的新時間點。","常見描述用法：'tight schedule' 表示行程緊湊，常出現在 Part 3/4 的職場對話中，作為婉拒邀約、解釋忙碌或請求額外協助的理由背景。"]}],"g6-p1-p2:adjectives:1:asleep":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00624:asleep","word":"asleep","partOfSpeech":["adjective"],"chineseMeaning":"沉睡的；睡著的","categoryZh":"辦公日常","starRating":3,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["asleep","more asleep","most asleep"]}],"examples":[{"english":"The employee was found asleep at his desk after working overtime.","chinese":"這位員工在加班後被發現睡在辦公桌上。"},{"english":"Please ensure all security personnel remain alert and not asleep during their shifts.","chinese":"請確保所有保安人員在值班期間保持警惕，不要睡著。"}],"examTips":["常見搭配詞組：最常與動詞 fall 連用形成「fall asleep」(入睡)，或使用副詞修飾為「fast asleep」或「sound asleep」(熟睡)。","語法特性辨析：asleep 為敘述形容詞(predicative adjective)，只能放在連綴動詞（如 be, fall, seem）之後當補語，不可直接置於名詞前。例如：只能說「The baby is asleep」，不可說「an asleep baby」，後者應改用「a sleeping baby」。","易混淆詞辨析：需區分 asleep (形容詞，狀態為睡著的)、sleep (動詞/名詞，指睡眠行為) 與 sleepy (形容詞，指感到疲倦、想睡的)。多益詞性題常在此設陷阱。","聽力測驗考點：在 Part 1 照片描述中，若人物閉眼休息，正確選項可能包含「is asleep」。在 Part 3 或 Part 4 的商務情境中，可能出現在描述長途出差(business trip)或長途飛行中「fall asleep on the plane」的描述。","答題注意事項：在閱讀測驗中，若看到動詞 fall，後方空格應首選 asleep 而非 sleep 或 sleepy，這是固定搭配用法。"]}],"g6-p1-p2:adjectives:3:brave":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01226:brave","word":"brave","partOfSpeech":["adjective"],"chineseMeaning":"勇敢的；無畏的；面對挑戰時表現出堅強的意志","categoryZh":"溝通互動","starRating":3,"toeicScoreRange":"600-780","wordForms":[{"partOfSpeech":"adjective","forms":["brave","braver","bravest"]}],"examples":[{"english":"The company needs brave employees who are willing to take risks and innovate.","chinese":"公司需要勇敢的員工，他們願意冒險並創新。"},{"english":"Despite the challenging market conditions, she bravely presented her proposal to the board.","chinese":"儘管市場狀況充滿挑戰，她勇敢地向董事會提出了她的提案。"}],"examTips":["動詞用法辨析：在 TOEIC 中，brave 不僅是形容詞，亦常作為動詞使用，意為「勇敢面對（惡劣天氣、挑戰等）」，常見搭配詞如 'brave the weather' 或 'brave the elements'，常用於描述交通延誤或戶外活動的情境。","商業決策情境：當形容詞使用時，常與 decision、move 或 step 搭配（例如：a brave move），用來描述公司在市場不穩時採取的大膽創新或冒險行為，在 Part 7 閱讀測驗的公司評論中相當常見。","易混淆詞辨析：需區分 brave（勇敢）與 bold（大膽/粗體）。雖然兩者在描述決策時意思相近，但 bold 在商務文件中也常用於指「粗體字」或「顯眼的設計」。此外，也要注意 brave 與相似音單字如 brace（支撐/心理準備）或 bare（赤裸的/僅僅的）的區別。","詞性與考點：在 Part 5 詞彙題中，要注意形容詞與副詞（bravely）的選擇。若空格在動詞（如 stand 或 face）之後，通常應選擇副詞修飾其行為表現。","聽力應對：在聽力測驗中，brave 常出現於描述員工克服工作困難或在極端情況下完成任務的對話，考生需快速連結其正面評價的語義。"]}],"g6-p1-p2:adjectives:4:comfortable":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01917:comfortable","word":"comfortable","partOfSpeech":["adjective"],"chineseMeaning":"舒適的；令人感到放鬆的，符合需求的","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["comfortable","more comfortable","most comfortable"]}],"examples":[{"english":"The ergonomic chair is designed to make employees more comfortable during long working hours.","chinese":"符合人體工學的椅子旨在讓員工在長時間工作時更舒適。"},{"english":"The client felt comfortable discussing the project details with our experienced team.","chinese":"客戶與我們經驗豐富的團隊討論專案細節時感到很自在。"}],"examTips":["常見搭配詞：常與介係詞 'with' 連用，如 'feel comfortable with' 表示對於某項提議或決定感到自在、有信心。此外，'comfortable working environment'（舒適的工作環境）也是職場情境的高頻詞組。","商業情境應用：除了描述身體上的舒適，在多益中常指對某事感到「滿意」或「有把握」，例如在協商薪資時提到 'comfortable salary'，或對某個計畫的進度感到 'comfortable'。","易混淆詞辨析：最常與 'convenient' 混淆。'Comfortable' 指的是身心的「舒適、自在」，而 'convenient' 指的是「方便、省時」。例如：飯店房間很 comfortable，但飯店的地點很 convenient。","考試出題重點：在聽力測驗 Part 1 圖片題中，常出現描述人物坐在 'comfortable chair' 的情景；在閱讀測驗 Part 5 中，常考其形容詞字尾 '-able' 的詞性辨別，或是其副詞形式 'comfortably'（如 comfortably afford 輕鬆負擔）。","答題注意事項：留意其反義詞 'uncomfortable' 在職場對話中可能暗示對某事存有疑慮或不認同，需結合上下文語境判斷語氣。"]}],"g6-p1-p2:adjectives:5:curious":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02497:curious","word":"curious","partOfSpeech":["adjective"],"chineseMeaning":"好奇的；對...感興趣的，渴望了解的","categoryZh":"溝通互動","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["curious","more curious","most curious"]}],"examples":[{"english":"The client was curious about the new product features and requested a demonstration.","chinese":"這位客戶對新產品的功能感到好奇，並要求進行示範。"},{"english":"She is a curious employee who always asks insightful questions during team meetings.","chinese":"她是一位好奇的員工，在團隊會議中總是提出富有洞察力的問題。"}],"examTips":["常見搭配詞組：最常見的用法為 'be curious about'，後面接感興趣的事物或人。在 TOEIC 中，常出現於職場新人詢問公司制度或對新計畫表現出興趣的情境。","商業情境應用：常用於表達對市場研究、客戶回饋或新技術的求知欲，例如 'The marketing team is curious about the recent decline in sales'。","容易混淆詞辨析：需區分 'curious' (中性，好奇) 與 'nosy' (貶義，愛打聽私人閒事)。在 TOEIC 的正式職場情境中，絕大多數情況下都會使用 curious 來展現積極主動的學習態度。","聽力與閱讀考點：在 Part 3 與 Part 4 中，當說話者表示 'I'm curious to know...' 時，通常是提出請求或引發後續核心問題的訊號，考生應留意接下來出現的具體詢問內容。","詞性轉換注意事項：應掌握其名詞形式 'curiosity'，常見搭配如 'satisfy one's curiosity' (滿足某人的好奇心) 或 'out of curiosity' (出於好奇)，這些片語偶爾會出現在 Part 5 的詞彙填空題中。"]}],"g6-p1-p2:adjectives:6:closed":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01829:closed","word":"closed","partOfSpeech":["adjective"],"chineseMeaning":"關閉的；停止運營的","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["closed","closer","closest"]}],"examples":[{"english":"The office will be closed for renovations next week.","chinese":"辦公室下週將因裝修而關閉。"},{"english":"Due to the holiday, the bank is closed today.","chinese":"由於是假日，銀行今天關閉。"}],"examTips":["詞性辨析：在多益中常作為形容詞表示「關閉的」或「不營業的」，例如 'The office is closed for the holiday'，應與動詞 close 或形容詞 close (接近的) 區分。","常見搭配詞：多益閱讀公告中常出現 'closed for renovation' (因裝修而關閉) 或 'closed until further notice' (關閉直到另行通知)。","商業情境：常出現於門市營業時間變動、國定假日休假通知或「closed-door meeting」(秘密/封閉式會議) 的情境。","聽力考點：在第一部分照片描述題，常用於描述物品狀態，如 'The lid is closed' (蓋子是關上的) 或 'The shop is closed'。","答題注意：當空格出現在 be 動詞之後作為補語描述狀態時，應選形容詞性質的 'closed'；若指距離接近，則選 'close'。"]}],"g6-p1-p2:adjectives:7:closing":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01834:closing","word":"closing","partOfSpeech":["noun","verb","adjective"],"chineseMeaning":"結束；關閉；收尾；（信件、演講等）結尾","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["closing","closings"]},{"partOfSpeech":"verb","forms":["closing","closes","closed"]},{"partOfSpeech":"adjective","forms":["closing","closer","closest"]}],"examples":[{"english":"The closing remarks of the CEO emphasized the company's commitment to innovation.","chinese":"執行長在演講的結尾強調了公司對創新的承諾。"},{"english":"Please review the closing paragraph of the contract before signing.","chinese":"請在簽署合約之前，審閱合約的結尾段落。"}],"examTips":["常見搭配詞：'closing remarks'（閉幕詞）、'closing date'（截止日期）及 'closing ceremony'（閉幕典禮）。在多益聽力 Part 4 的講座或會議中，'closing remarks' 是預測最後一題答案的重要訊號詞。","商業交易情境：'closing a deal' 意指達成協議或完成交易。在閱讀 Part 7 的商業書信中，這個詞組常用來描述銷售流程的最終成功階段。","易混淆詞辨析：'closing' 常作為形容詞或動詞性名詞（如 closing shift 晚班），強調功能或過程；而 'closed' 則是形容詞，強調『已關閉』的狀態（如 the store is closed）。","財務與房地產考點：'closing costs' 指的是房地產成交時產生的各種手續費。在多益 Part 6 或 Part 7 的合約或帳單情境中，考生需將其識別為與交易成本相關的項目。","聽力答題技巧：在聽力測驗中，講者若提到 'In closing...'，即表示談話即將結束並進行總結，這通常是回答關於『講者下一步要做什麼』或『最後的提醒』等考點的關鍵轉折點。"]}],"g6-p1-p2:adjectives:8:difficult":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02884:difficult","word":"difficult","partOfSpeech":["adjective"],"chineseMeaning":"困難的；棘手的；具有挑戰性的","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["difficult","more difficult","most difficult"]}],"examples":[{"english":"The project timeline is quite difficult to meet given the current resource constraints.","chinese":"考慮到目前的資源限制，這個專案的時間表相當難以達成。"},{"english":"The software installation process can be difficult for users with limited technical experience.","chinese":"對於缺乏技術經驗的使用者來說，軟體安裝過程可能很困難。"}],"examTips":["常見搭配詞與句型：在多益考試中，'difficult' 常見於形容任務或決定，如 'difficult task' (艱鉅任務) 或 'difficult decision' (困難決定)；此外，固定句型 'find it difficult to + 原型動詞' (發現做某事很困難) 是 Part 5 的常考結構。","商業情境應用：此單字常用於描述市場挑戰或負面情況，例如 'difficult market conditions' (艱困的市場環境) 或 'difficult economic climate' (經濟低迷)。在正式商務通訊中，為了語氣委婉，有時會改用其近義詞 'challenging'。","相似詞辨析：雖然 'hard' 與 'difficult' 意義相近，但 'difficult' 更具正式感。在進階測驗中，考生應注意 'demanding' (耗費精力的) 或 'complex' (複雜難解的) 等詞彙，它們可能在閱讀測驗中作為 'difficult' 的替換選項。","閱讀考點與語義替換：在閱讀 Part 7 中，文意理解常涉及 Paraphrasing。例如原文提到 'The project was difficult to complete'，選項可能會對應 'The task was not easy' 或 'The project faced challenges'。","詞性與搭配注意事項：注意名詞形式 'difficulty' 的用法，常見短語為 'have difficulty (in) doing something' (做某事有困難)，此處動詞須用 V-ing 形式，是多益文法題的經典考點。"]}],"g6-p1-p2:adjectives:9:different":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02879:different","word":"different","partOfSpeech":["adjective"],"chineseMeaning":"不同的; 相異的; 各異的","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adverb","forms":["differently"]},{"partOfSpeech":"noun","forms":["difference"]}],"examples":[{"english":"We have different opinions on this matter.","chinese":"我們對這件事有不同的看法。"},{"english":"The two products are very different in quality.","chinese":"這兩款產品的品質大不相同。"}],"examTips":["常見搭配詞：'different from' 是多益語法中最標準的用法，在美式英語中亦常見 'different than'。此外，商務情境常出現 'different versions of the contract' (合約的不同版本) 或 'a different approach' (不同的方法)。","詞性辨析與考點：多益 Part 5 常考詞性轉換，考生須區分形容詞 'different'、名詞 'difference'、副詞 'differently' 與動詞 'differ'。看到形容詞時，通常位於 be 動詞後或修飾後方名詞。","同義詞替換：在閱讀測驗（Part 7）中，'different' 常作為 'various'、'diverse' 或 'distinct' 的替換詞。若文章提到 'different colors'，題目選項可能會以 'various options' 來表示。","易混淆詞辨析：注意 'indifferent'，其字首雖然相似，但意思為『漠不關心的』或『平庸的』，與『不同的』完全不同。","聽力測驗注意：在 Part 3 或 Part 4 的對話中，若出現 'different'，通常暗示著變動、修改或選擇另一種方案，是答題的關鍵信號。"]}],"g6-p1-p2:adjectives:10:dangerous":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02556:dangerous","word":"dangerous","partOfSpeech":["adjective"],"chineseMeaning":"危險的；具有潛在危害的，可能導致損害或傷害。","categoryZh":"法務合規與安全","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["dangerous","more dangerous","most dangerous"]}],"examples":[{"english":"The company halted operations due to the dangerous working conditions.","chinese":"由於工作環境危險，公司暫停了營運。"},{"english":"Employees must follow safety protocols to avoid any dangerous situations.","chinese":"員工必須遵守安全協議，以避免任何危險情況。"}],"examTips":["常見搭配詞與同義詞：在 TOEIC 職場安全或工業情境中，dangerous 常與 hazardous 互換使用，例如 dangerous chemicals 或 hazardous materials。","商業情境應用：此單字常出現在工廠安全手冊、設備維護公告或職業安全培訓中，例如 It is dangerous to operate this machine without proper training。","易混淆詞辨析：dangerous 是通用詞，指可能造成損害或生命危險；risky 則多用於描述商業投資、財務決策或計畫的成敗不確定性。在 TOEIC 閱讀中，hazardous 是其在專業領域最常見的高階同義詞。","考試重點：在聽力 Part 4 的公共服務公告或閱讀 Part 7 的公司內部通訊中，出現該詞時，考點通常圍繞在「應採取的安全預防措施」或「禁止進行的特定行為」。","詞性與結構：注意其名詞 danger、副詞 dangerously。考試中常考形容詞修飾名詞的填空題，或是 in danger (處於危險中) 這一類的固定片語。"]}],"g6-p1-p2:adjectives:11:special":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09452:special","word":"special","partOfSpeech":["adjective"],"chineseMeaning":"獨特的；特別的；與眾不同的，通常指具有附加價值或特殊意義的。","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["special","more special","most special"]}],"examples":[{"english":"The company offers a special discount for first-time customers.","chinese":"公司為首次顧客提供特別折扣。"},{"english":"This project requires special attention due to its complexity.","chinese":"由於其複雜性，這個專案需要特別關注。"}],"examTips":["常見搭配詞：包含 special offer (特惠)、special occasion (特殊場合)、special request (特別要求)。在多益聽力 Part 1 或 Part 2 中，若聽到 special offer，答案往往與價格折扣或促銷活動相關。","商業情境：此字頻繁出現在廣告與電子郵件，用以強調產品的獨特性或限時優惠，例如 'special promotion'。在邀請函中則常以 'special guest' 指稱主講人或貴賓。","易混淆詞辨析：需區分 'special' (特別的) 與 'specific' (特定的)。'Special' 強調優於一般或獨特，而 'specific' 強調精確的細節。例如 'special price' 是優惠價，而 'specific instructions' 是明確的指令。","詞性變化考點：應注意衍生字 'specialist' (名詞，專家/專員) 與動詞片語 'specialize in' (專精於)。在多益閱讀 Part 5 中，'specialize' 常與介系詞 'in' 連用，考點多在介系詞的搭配。","答題注意事項：在 Part 7 閱讀測驗中，若文中提及 'special project'，通常代表該任務非日常例行公事，應仔細留意文中對該任務期限或負責人的具體描述。"]}],"g6-p1-p2:adjectives:12:dead":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02578:dead","word":"dead","partOfSpeech":["adjective","adverb","noun"],"chineseMeaning":"死的；無生命的；已故的；不活躍的；完全地；死寂的","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["dead","deader","deadest"]},{"partOfSpeech":"adverb","forms":["dead"]},{"partOfSpeech":"noun","forms":["dead"]}],"examples":[{"english":"The phone battery is completely dead, so I can't make any calls.","chinese":"手機電池完全沒電了，所以我打不了電話。"},{"english":"She was dead serious about wanting to resign from her position.","chinese":"她對於辭職一事非常認真。"}],"examTips":["詞性與字形辨析：這是多益最基礎但也最常考的陷阱。考生需區分 dead (形容詞)、die (動詞)、death (名詞) 與 deadly (形容詞，意為致命的)。例如，在「The project is ____.」應填入形容詞 dead，而非動詞或名詞。","職場複合詞與搭配：最核心的單字是 deadline (截止日期)，在 Part 5 和 Part 7 極高頻出現。此外需注意 dead-end job (無升遷前景的工作) 以及 dead season (淡季，等同於 off-season)，這些多用於商業對話與文章。","副詞用法理解：在聽力測驗中，dead 有時當作副詞使用，意為「完全地」或「極其」，如 dead tired (極度疲勞) 或 dead certain (非常確定)，理解這層意涵有助於精確掌握講者的語氣。","設備與設施狀態：在辦公室或物業維護情境，dead 常指「失效或斷電」，例如 a dead battery (沒電的電池)、a dead outlet (沒電的插座) 或 a dead phone line (斷掉的電話線)，這是描述報修問題時的常見表達。"]}],"g6-p1-p2:adjectives:13:friendly":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04196:friendly","word":"friendly","partOfSpeech":["adjective"],"chineseMeaning":"友善的；和藹可親的，通常指待人接物時的態度。","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["friendly","friendlier","friendliest"]}],"examples":[{"english":"The receptionist was very friendly and welcoming, making a good first impression.","chinese":"接待員非常友善和熱情，給了良好的第一印象。"},{"english":"Our company strives to provide friendly and efficient customer service.","chinese":"我們公司致力於提供友善且高效的客戶服務。"}],"examTips":["詞性陷阱辨析：friendly 雖然以 -ly 結尾，但它是「形容詞」而非副詞。在 TOEIC 文法題中，若要表達副詞語意，通常會使用「in a friendly manner」或「in a friendly way」。","常見複合形容詞：TOEIC 閱讀中頻繁出現「名詞/副詞 + friendly」的結構，如 user-friendly（操作簡便的）、environmentally friendly（環保的）、budget-friendly（划算的），這是閱讀測驗中的加分關鍵。","商業情境應用：常用於描述企業文化（friendly work environment）或服務態度（friendly and helpful staff）。在聽力題中，聽到這些描述通常代表正面的公司評價或滿意的顧客經驗。","同義詞與層次：TOEIC 高分段會考查語氣更正式的同義詞，例如 amiable（和藹可親的）或 cordial（誠摯友好的，常用於商務信函結尾或正式接待）。","答題注意事項：在 Part 5 填充題中，若空格前有修飾語（如 very, highly），且空格後接名詞，應選擇形容詞 friendly，不可因看到 -ly 就誤判為副詞而排除。"]}],"g6-p1-p2:adjectives:14:finished":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03935:finished","word":"finished","partOfSpeech":["adjective","verb"],"chineseMeaning":"完成；結束；告一段落","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["finished","more finished","most finished"]},{"partOfSpeech":"verb","forms":["finished","finishes","finishing"]}],"examples":[{"english":"The project is finished ahead of schedule and under budget.","chinese":"這個專案已超前進度且低於預算完成。"},{"english":"Please submit your report by Friday; we need it finished by then.","chinese":"請在星期五前提交您的報告，我們需要在當時完成。"}],"examTips":["【文法關鍵】在多益 Part 5 的文法題中，動詞 finish 後方必須接動名詞 (V-ing) 作為受詞，例如 'finish reviewing the proposal'，這是常出的文法考點。","【商務慣用語】'finished products' 或 'finished goods' (製成品) 是物流與製造業情境的高頻詞彙，常用於 Part 6 或 Part 7 關於工廠生產或庫存管理的文章中。","【近義詞辨析】'finished' 與 'complete' 在多益中常可互換，但 'finalize' 則更強調對細節的『最後定案』(如 finalize a contract)，答題時需注意情境。","【聽力測驗要點】在 Part 3 簡短對話中，若問句提到 'Are you finished with the report?'，聽力選項中常會出現 'completed' 或 'done' 作為同義詞替換。","【常見組合】注意 'finishing touches' (最後修飾/潤飾) 這一成語，常出現在專案進度報告或產品設計討論的情境中，表示工作即將大功告成。"]}],"g6-p1-p2:adjectives:15:opposite":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06940:opposite","word":"opposite","partOfSpeech":["adjective","noun","preposition"],"chineseMeaning":"相反的；對面的；對立面；反義詞","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["opposite"]},{"partOfSpeech":"noun","forms":["opposite","opposites"]},{"partOfSpeech":"preposition","forms":["opposite"]}],"examples":[{"english":"The two departments have opposite goals for the project.","chinese":"兩個部門對這個專案有著截然不同的目標。"},{"english":"Her opinion is the exact opposite of mine.","chinese":"她的意見與我的恰恰相反。"}],"examTips":["聽力 Part 1 常考方位：opposite 常用來描述照片中人或物的位置，意為『在...對面』，在考試中常與 across from 互換使用。","詞性靈活用法：考生需辨識其三種主要用法：介系詞 (e.g., The bank is opposite the post office)、形容詞 (e.g., They went in opposite directions) 以及名詞 (e.g., The reality was the exact opposite)。","商業溝通情境：在會議或商務討論中，常出現 quite the opposite 或 the opposite is true 來表達對某項數據或預測的強烈對比與反駁。","易混淆詞辨析：注意與 opposed 的區別。Opposite 指位置或性質上的相反，而 opposed 常用於 be opposed to + Ving/N，表示『反對』某個計畫或提議。","閱讀理解焦點：在 Part 7 長篇文章中，看到 opposite 應立即反應文中可能存在對比關係，這通常是題目中出現 contrast 或 change 等關鍵字時的定位點。"]}],"g6-p1-p2:adjectives:16:serious":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09034:serious","word":"serious","partOfSpeech":["adjective"],"chineseMeaning":"嚴肅的；認真的；重要的","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["serious","more serious","most serious"]}],"examples":[{"english":"The manager emphasized the seriousness of the project deadline.","chinese":"經理強調了專案截止日期的重要性。"},{"english":"This is a serious matter; please handle it with utmost care.","chinese":"這是一個嚴肅的問題，請務必小心處理。"}],"examTips":["常見搭配詞：'serious problem'（嚴重的問題）、'serious consideration'（認真的考慮）、'serious consequences'（嚴重的後果）。在多益閱讀中，常出現於描述營運挑戰或政策評估時。","商業情境應用：常用於表達對某事的重視程度，例如 'take something seriously'（認真對待某事），這在商業談判或績效面談中非常常見。","易混淆詞辨析：'serious' 強調事態嚴重或態度認真；而 'severe' 則多用於描述天氣嚴酷、疾病嚴重或損害劇烈。在選擇題中要注意語境。","多益考點：在 Part 5 詞彙題中，常考 'serious' 作為形容詞修飾名詞的用法；在 Part 7 閱讀中，若出現 'Are you serious about this proposal?' 則是指對提案的『誠意』或『決心』。","答題注意事項：注意 serious 除了『嚴重』之外，還有『嚴肅』和『認真』的意思，不可一概而論，須根據前後文判定其具體含義。"]}],"g6-p1-p2:adjectives:17:silent":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09214:silent","word":"silent","partOfSpeech":["adjective"],"chineseMeaning":"沉默的；寂靜的；無聲的；不說話的","categoryZh":"溝通互動","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["silent","more silent","most silent"]},{"partOfSpeech":"adverb","forms":["silently"]},{"partOfSpeech":"noun","forms":["silence"]}],"examples":[{"english":"The audience remained silent during the emotional speech.","chinese":"在感人的演講中，觀眾保持了沉默。"},{"english":"Please keep your phones on silent mode during the meeting.","chinese":"會議期間請將手機調成靜音模式。"}],"examTips":["商業法律情境：常出現搭配詞 'silent partner'（隱名合夥人），指提供資金但不參與公司日常管理或決策的人，這在閱讀部分的合約或商業介紹中偶爾會出現。","拍賣情境：'silent auction'（無聲拍賣）是指投標者在紙上寫下金額而非口頭競價的拍賣方式，常出現在慈善活動或商務晚宴的相關報導中。","聽力常見指令：在機場、電影院或會議開始前，常聽到 'Please switch your mobile phones to silent mode'（請將手機轉為靜音模式）的警示，'silent mode' 為必考搭配詞。","詞性辨析：考生需區分形容詞 'silent' 與名詞 'silence'，在閱讀測驗的填空題中，應注意後方是否接續名詞，例如 'remain silent'（保持沉默）中 silent 為形容詞作補語。","易混淆詞辨析：'silent' 指完全無聲或不說話，而 'quiet' 則指聲音很小或環境安靜，在 TOEIC 考試中 'silent' 更多用於描述電子設備設定或特定的商業術語。"]}],"g6-p1-p2:adjectives:18:stomachache":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09673:stomachache","word":"stomachache","partOfSpeech":["noun"],"chineseMeaning":"胃痛；腹痛，通常指因飲食或其他原因引起的胃部不適。","categoryZh":"住宿與餐飲","starRating":3,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["stomachache","stomachaches"]}],"examples":[{"english":"I'm sorry, I can't attend the meeting today; I have a terrible stomachache.","chinese":"我很抱歉，我今天無法參加會議，因為我得了嚴重的胃痛。"},{"english":"The chef apologized for the customer's stomachache after they ate the spicy dish.","chinese":"顧客吃了辛辣的菜餚後感到胃痛，廚師表示歉意。"}],"examTips":["常見搭配詞：通常與動詞 have 或 suffer from 連用，例如 have a severe stomachache (嚴重的胃痛)。","商業情境應用：此單字常出現在 TOEIC 聽力 Part 3 的對話中，通常與請病假 (take sick leave)、取消預約 (cancel an appointment) 或更改會議時間 (reschedule a meeting) 相關。","相似詞辨析：需區分 stomachache (胃痛) 與 upset stomach (胃部不適/消化不良)，後者在多益情境中也常被提及，特別是在與餐飲或食物品質相關的對話中。","聽力與閱讀考點：考生應留意後續的補救行為，如聽到 stomachache 後，選項常出現 see a doctor (看醫生) 或 go home early (提早回家)。","構詞法注意事項：-ache 為字尾，表示持續的疼痛，類似的單字還有 headache (頭痛)、backache (背痛)，掌握此字根有助於擴展健康相關詞彙。"]}],"g6-p1-p2:adjectives:19:weak":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10990:weak","word":"weak","partOfSpeech":["adjective"],"chineseMeaning":"虛弱的；軟弱的；微弱的；無力的；差的","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["weaker","weakest"]}],"examples":[{"english":"Due to the economic downturn, the company's financial performance has been quite weak.","chinese":"由於經濟衰退，該公司的財務表現一直相當疲弱。"},{"english":"The signal in this area is very weak, making it difficult to connect to the internet.","chinese":"這個地區的訊號非常微弱，導致難以連接到網路。"}],"examTips":["常見搭配詞組：在商務英文中常與市場或財務狀況搭配，如 weak economy (經濟疲軟)、weak demand (需求疲軟)、weak performance (表現平平)、weak signal (訊號微弱)。","商業情境應用：常用於描述公司財報或業績不如預期，例如：'The company reported weak quarterly earnings.'，此時 weak 等同於 poor 或 disappointing。","易混淆詞與辨析：注意與同音字 week (星期) 的區分，在聽力測驗中須靠上下文判斷；另外，weak 為形容詞，其名詞為 weakness (弱點)，動詞為 weaken (削弱)，TOEIC 閱讀 Part 5 常考詞性選擇。","聽力與閱讀考點：在 Part 7 的公司分析或新聞報導中，常用來對比市場的強弱 (strong vs. weak)，掌握此對比能快速理解文章對市場趨勢的評價。","答題注意事項：若在聽力中聽到 weak proposal 或 weak argument，表示講者對該提議持否定態度，認為其說服力不足，這類語氣判斷常是 Part 3 或 Part 4 的解題關鍵。"]}],"g6-p1-p2:adjectives:20:alone":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00347:alone","word":"alone","partOfSpeech":["adjective","adverb"],"chineseMeaning":"獨自一人；孤單的","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["alone","more alone","most alone"]},{"partOfSpeech":"adverb","forms":["alone"]}],"examples":[{"english":"The manager felt alone in his decision to restructure the department.","chinese":"經理在重組部門的決定中感到孤單。"},{"english":"She prefers to work alone, as she finds it more productive.","chinese":"她喜歡獨自工作，因為她認為這樣更有效率。"}],"examTips":["辨析 alone 與 lonely：alone 表示客觀的「獨自一人」，而 lonely 表示主觀感受上的「孤單」。在 TOEIC 中，alone 常描述員工獨立完成任務的狀態。","詞性與位置：alone 可作形容詞或副詞，通常置於系動詞（如 be, feel）之後或一般動詞之後。注意 alone 不可用於名詞前（不說 an alone person），此點常在閱讀 Part 5 詞彙題中測驗。","搭配詞組與同義替換：常用 'by oneself' 替換 'alone'。常見詞組如 'all alone' (完全獨自一人) 或 'let alone' (更不用說)，後者在進階閱讀中可能出現。","商業強調用法：當 alone 置於名詞或數額之後，表示「單單/光是」，例如 'The CEO alone makes the decision' (光是執行長一人就能決定)。","聽力測驗陷阱：在 Part 1 照片題，若圖片中有多人，選項出現 alone 必為錯誤；在 Part 2 應答題，若問題問 'Who helped you?'，回答 'I did it alone.' 是常見的正確回答模式。"]}],"g6-p1-p2:adjectives:21:bright":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01255:bright","word":"bright","partOfSpeech":["adjective","adverb"],"chineseMeaning":"明亮的；鮮明的；（前景）有希望的","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["bright","brighter","brightest"]},{"partOfSpeech":"adverb","forms":["bright"]}],"examples":[{"english":"The presentation slides were too dark; please make them brighter so everyone can see clearly.","chinese":"簡報的投影片太暗了；請把它們調亮一點，以便每個人都能清楚地看到。"},{"english":"The company's future looks bright after securing the major contract.","chinese":"在簽訂這項主要合約後，該公司的未來前景一片光明。"}],"examTips":["多重語意辨析：在多益考試中，bright 具有物理上的『明亮的』與抽象上的『聰穎的、有前途的』兩種主要含義。考生需根據上下文判斷，例如描述辦公環境時指光線充足，而描述員工或計畫時則指潛力無窮。","常見商務搭配詞：常用於形容前景或應徵者，如『bright future』（光明的前景）、『bright prospects』（大好前程）及『a bright candidate』（聰明且有潛力的候選人）。","聽力第一部分考點：在 Part 1 的圖片描述題中，bright 常與自然光（natural light）或燈光相關聯，例如『The office is bright and airy』，用來描述空間感。","易混淆詞辨析：與 brilliant 相比，bright 較為普遍且中性，而 brilliant 帶有『卓越、才華橫溢』的強烈語氣。在描述燈泡亮度或一般潛力時，bright 是首選。","答題注意事項：在閱讀 Part 7 的公司年度報告或展望文章中，若出現 bright，通常代表積極、正面的商業預測，是找出文章基調（Tone）的重要線索。"]}],"g6-p1-p2:adjectives:23:fair":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03778:fair","word":"fair","partOfSpeech":["adjective","noun"],"chineseMeaning":"公平的；合理的；公正的；（展覽、市集等）的","categoryZh":"行銷與銷售","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["fair","fairer","fairest"]},{"partOfSpeech":"noun","forms":["fair","fairs"]}],"examples":[{"english":"The company strives to offer fair prices to all its customers.","chinese":"公司致力於向所有客戶提供合理的價格。"},{"english":"The annual trade fair attracts numerous potential buyers and sellers.","chinese":"年度貿易展覽吸引了眾多潛在的買家和賣家。"}],"examTips":["多義詞辨析：在多益考試中 fair 常以名詞形式出現，指「博覽會」或「市集」，常見如 job fair (就業博覽會) 或 trade fair (貿易展)；亦可作為形容詞表示「公平的」或「合理的」。","常見搭配詞：作為形容詞時常與價格連用，例如 fair price (合理的價格) 或 fair market value (公平市場價值)。","易混淆詞辨析：需特別注意與其同音異義詞 fare (車資、票價) 的區分，後者主要出現在交通運輸或旅遊相關的情境中。","聽力考點：在聽力 Part 2 或 Part 3 的口語對話中，常出現 fair enough，意指「有道理」或「我接受」，用來表達同意對方的觀點或解釋。","答題注意事項：在閱讀 Part 7 的公告或宣傳單中，若看到 fair 且首字母大寫或位於特定地點後，通常是指大型活動而非形容詞，需根據上下文快速判斷語意。"]}],"g6-p1-p2:adjectives:24:excellent":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03600:excellent","word":"excellent","partOfSpeech":["adjective"],"chineseMeaning":"極佳的；卓越的；優秀的，形容事物品質或表現非常優異。","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["excellent","better","best"]}],"examples":[{"english":"The presentation was excellent, and the client expressed great interest in our proposal.","chinese":"簡報非常精彩，客戶對我們的提案表達了濃厚的興趣。"},{"english":"The team's performance this quarter has been excellent, exceeding all expectations.","chinese":"本季團隊的表現非常出色，遠超預期。"}],"examTips":["常見搭配詞：在多益測驗中常出現 excellent performance (優異表現)、excellent reputation (良好的聲譽) 以及 excellent opportunity (極佳的機會)，通常與代表「品質」或「成果」的名詞結合。","商業情境應用：此字頻繁出現在績效考核、產品評論或客戶推薦信中。例如：\"The candidate has an excellent track record.\" (該應徵者有極佳的過往表現紀錄)。","易混淆詞辨析：需區分形容詞 excellent、動詞 excel (優於) 與名詞 excellence (卓越)。此外，多益閱讀常將 excellent 與 outstanding、superb 或 exceptional 作為同義詞替換考點。","聽力與閱讀考點：在 Part 3 或 Part 4 的聽力中，若聽到 excellent，通常代表說話者對某事持正面評價，這往往是決定答案選「推薦」或「同意」的關鍵訊號。","答題注意事項：注意詞性變化。Part 5 常考形容詞與副詞的區分，例如修飾動詞時需使用 excellently 而非 excellent，考生應觀察空格修飾的對象是名詞還是動詞。"]}],"g6-p1-p2:adjectives:25:excited":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03614:excited","word":"excited","partOfSpeech":["adjective"],"chineseMeaning":"感到興奮、雀躍的；因期待而激動的","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["excited","more excited","most excited"]}],"examples":[{"english":"The team was excited to hear about the new project and its potential for growth.","chinese":"團隊聽到這個新項目及其增長潛力，感到非常興奮。"},{"english":"She was excitedly anticipating the results of the sales presentation.","chinese":"她興奮地期待著銷售簡報的結果。"}],"examTips":["區分 -ed 與 -ing 形容詞：TOEIC 常考情感形容詞的分辨，'excited' 描述人的主觀感受（感到興奮的），而 'exciting' 則描述引起感受的事物（令人興奮的），考題中需判斷主詞是人還是物。","常見介系詞與搭配：最常搭配介系詞 'about'，如 'excited about the merger'；或接不定詞，如 'excited to collaborate'。在商業書信中，'We are excited to announce...' 是極高頻的開場句式。","近義詞與語氣辨析：'enthusiastic' (熱忱的) 常作為其進階替換詞，而 'eager' (渴望的) 則更強調期待某事的發生。在 Part 7 閱讀理解中，若提到員工對新政策感到 'excited'，通常代表該政策有利於員工。","聽力測驗考點：在 Part 3 對話中，'excited' 的出現通常伴隨著語氣的轉折，代表講者即將提到一個正面消息、獎勵或成功的項目進展。","答題注意事項：當空格後方出現形容的事對象時，應檢視主詞是否為人，避免誤選 'exciting'。例如：'The employees were excited (not exciting) by the bonus news.'"]}],"g6-p1-p2:adjectives:26:exciting":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03616:exciting","word":"exciting","partOfSpeech":["adjective"],"chineseMeaning":"令人興奮的；刺激的；引人入勝的","categoryZh":"行銷與銷售","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["exciting","more exciting","most exciting"]}],"examples":[{"english":"The new marketing campaign is expected to be very exciting for our target audience.","chinese":"我們預期新的行銷活動將會對目標受眾非常吸引人。"},{"english":"The company is launching an exciting new product line to boost sales.","chinese":"公司正在推出令人興奮的新產品線以提升銷售額。"}],"examTips":["分辨 -ing 與 -ed 形容詞：這是多益文法題（Part 5）的必考重點。exciting 用於形容事物本身具備的特性（如：an exciting news），而 excited 則用於形容人的感受（如：The staff members are excited about the bonus），作答時務必確認修飾對象。","常見商業搭配詞：在職場情境中常搭配 opportunity, project, development 或 product launch，例如 'an exciting opportunity for career advancement'（一個令人興奮的晉升機會）。","易混淆詞辨析：需注意與音近詞 'exacting'（嚴格的、要求高的）區分，exacting 常用於描述 'exacting standards' 或 'exacting work'。","聽力與閱讀考點：常出現在多益聽力的廣告（Part 4）或閱讀的促銷文案（Part 7）中，用來強化產品吸引力或公司發展前景，看到此詞通常代表正向積極的語氣。","答題注意事項：若題目中出現副詞修飾，例如 'highly exciting'，應將其視為一體，重點仍落在判斷主詞是 '事/物'（用 -ing）還是 '人'（用 -ed）。"]}],"g6-p1-p2:adjectives:27:silly":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09216:silly","word":"silly","partOfSpeech":["adjective"],"chineseMeaning":"愚蠢的；傻的；可笑的；不明智的","categoryZh":"溝通互動","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["sillier","silliest"]},{"partOfSpeech":"noun","forms":["silliness"]}],"examples":[{"english":"Don't be silly, you can definitely do it if you try.","chinese":"別傻了，只要你努力就一定能做到。"},{"english":"It was a silly mistake to forget to back up the files.","chinese":"忘記備份檔案是個愚蠢的錯誤。"}],"examTips":["語氣與情境辨析：'silly' 屬於較非正式 (informal) 的口語詞彙，多出現於 TOEIC 聽力測驗 Part 2 或 Part 3 的日常對話中。在正式商務書信或 Part 7 閱讀測驗中，描述錯誤或不合理的決策時，通常會選用更專業的詞彙如 'unreasonable'、'absurd' 或 'illogical'。","常見搭配詞組：最常見的組合是 'silly mistake' (愚蠢/粗心的小錯誤)。在聽力 Part 2 中，當某人對微不足道的疏忽表示歉意時，對方常回覆 'Don't be silly' (別傻了/別這麼客氣)，表示這沒什麼大不了。","易混淆詞與同義詞：'silly' 強調滑稽或不成熟的愚蠢；'foolish' 語氣稍重且較正式；而在 TOEIC 閱讀的高階詞彙中，'preposterous' 或 'ridiculous' 常被用來形容極度荒謬的情況。","考試出題重點：'silly' 在考試中常用於形容小規模的行政疏失 (clerical error) 或自嘲。若在 Part 3 聽到對話者提到 'silly error'，題目可能會詢問問題的嚴重性，通常答案會指向 'minor' (微小的) 或 'easily fixed' (容易修補的)。","答題注意事項：在單字填空題 (Part 5) 中，要注意修飾對象。如果修飾的是專業的商業策略，應避免選擇 'silly'，而應選擇 'imprudent' (不謹慎的) 或 'unwise' (不明智的)，因為 'silly' 的專業度不足以描述嚴肅的商務場合。"]}],"g6-p1-p2:adjectives:28:square":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09536:square","word":"square","partOfSpeech":["noun","adjective"],"chineseMeaning":"方形；廣場；平方（單位）","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["square","squares"]},{"partOfSpeech":"adjective","forms":["square","squarer","squarest"]}],"examples":[{"english":"The architect requested a square table for the conference room.","chinese":"建築師要求為會議室準備一張方形的桌子。"},{"english":"The company's office space is approximately 100 square meters.","chinese":"該公司的辦公空間約為 100 平方公尺。"}],"examTips":["在聽力測驗 Part 1 中，square 常指『正方形物品』或『廣場』，考生應留意圖中是否有露天廣場或幾何形狀的陳設。","商業片語『back to square one』代表『回到原點、白忙一場』，常用於 Part 3 與 Part 4 的對話情境中，表示提案被拒絕或需要重新開始。","在房地產或辦公室租賃相關的 Part 7 閱讀題中，『square footage』指『平方英呎（面積）』，常伴隨數字出現，是計算租金或空間分配的關鍵資訊。","形容詞用法可表示『結清的』，例如『square a debt』或『be all square』，在商務對帳或結帳情境中意指款項已付清、互不相欠。","辨析：注意 square 與 rectangle 的形狀區別，雖然多益較少考幾何定義，但在物流包裝（packaging）描述中，square 常與 cube (立方體) 相關連。"]}],"g6-p1-p2:adjectives:29:round":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08738:round","word":"round","partOfSpeech":["noun","adjective","verb"],"chineseMeaning":"圓形；一圈；（會議、討論等）一輪","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["round","rounds"]},{"partOfSpeech":"adjective","forms":["round","rounder","roundest"]},{"partOfSpeech":"verb","forms":["round","rounds","rounding","rounded"]}],"examples":[{"english":"The table was round, facilitating easy conversation among all attendees.","chinese":"那張桌子是圓形的，方便所有與會者輕鬆交流。"},{"english":"Let's go around the table and have each team member share their progress report.","chinese":"我們圍繞桌子，讓每個團隊成員分享他們的進度報告。"}],"examTips":["商務招聘與融資應用：在 TOEIC 中，round 常作為名詞使用，如『a round of interviews』(一輪面試) 或『funding round』(融資輪次)，考生需識別其代表階段或輪次的含意。","差旅情境：高頻詞彙『round-trip ticket』(來回票) 經常出現在交通與旅遊部分的聽力或閱讀題中，與 one-way ticket (單程票) 是常見的對應考點。","時間描述：片語『round-the-clock』意指 24 小時全天候，常用於描述物流、客戶服務或工廠運作的持續性。","數據處理與報表：在財務或統計情境中，動詞用法『round up』(向上進位) 或『round down』(向下捨去) 常見於對預算估算或數據修約的描述，需注意其與數字的搭配。","常見搭配詞辨析：在會議描述中，『roundtable discussion』(圓桌討論) 意指平等交流；而作為形容詞時，『a round number』則是指整數。考生在作答時應根據上下文判斷 round 的詞性是名詞、動詞、形容詞還是介係詞。"]}],"g6-p1-p2:adjectives:30:glad":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04406:glad","word":"glad","partOfSpeech":["adjective","adverb"],"chineseMeaning":"感到高興的；欣喜的","categoryZh":"溝通互動","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["glad","gladder","gladdest"]},{"partOfSpeech":"adverb","forms":["glad"]}],"examples":[{"english":"I'm glad to hear that the deal has been finalized.","chinese":"聽到這筆交易已完成，我感到很高興。"},{"english":"The manager was glad to accept the employee's proposal.","chinese":"經理很高興地接受了員工的建議。"}],"examTips":["常見搭配詞組：常用於 \"be glad to + 動詞原形\" 表示樂意做某事，或 \"be glad (that) + 子句\" 表達對於某個結果感到高興，例如 \"I am glad that we reached an agreement.\"。","商業情境運用：在商務書信或 Email 中，常用來展現禮貌與正向語氣，例如在開頭或結尾提到 \"I'm glad to be of service\" (我很樂意為您服務) 或 \"We are glad to inform you...\" (我們很高興通知您...)。","易混淆詞辨析：需區分 \"glad\" 與 \"grateful\"。 \"glad\" 單純表示高興、欣慰；而 \"grateful\" 則是表示「感激」，在正式感謝函中較常使用后者。此外，\"glad\" 主要是作表語（接在 be 動詞後），很少放在名詞前修飾（不常說 a glad man）。","聽力與閱讀考點：在聽力測驗 Part 2 (應答問題) 中，\"Gladly\" 常用來正面回應對方的請求或邀請；在閱讀 Part 7 中，此字常出現在正向反饋或客戶滿意的描述中。","語法結構注意：當表示「對某事感到高興」時，介係詞通常使用 \"about\" 或 \"at\"，例如 \"glad about the news\"，在作答時需注意後接成分的正確性。"]}],"g6-p1-p2:adjectives:31:far":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03806:far","word":"far","partOfSpeech":["adverb","adjective"],"chineseMeaning":"（副詞）遙遠地；距離或時間上很長；程度上很深；（形容詞）遙遠的；離得很遠的","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adverb","forms":["far","farther","further","farthest","furthest"]},{"partOfSpeech":"adjective","forms":["far","farther","further","farthest","furthest"]}],"examples":[{"english":"The new factory is located far from the downtown area, which helps reduce rental costs.","chinese":"新工廠位於離市中心很遠的地方，這有助於降低租金成本。"},{"english":"How far along are we with the preparations for the conference?","chinese":"我們為這次會議做的準備進度到哪裡了？"}],"examTips":["比較級修飾語：far 常在 Reading 第五部分中用來修飾比較級形容詞或副詞，例如 far more efficient 或 far better，表示『遠比...更...』，這是多益語法題的常見考點。","常見片語 so far：在商業報告或對話中表示『到目前為止』，常作為現在完成式（have/has + p.p.）的關鍵時間副詞。","最高級強調 by far：用來強調最高級，表示『顯然是、最...』，例如 by far the most expensive，常用於產品比較或市場分析情境。","程度否定用法 far from：表示『遠非、完全不』，常用於表示工作進度或目標達成狀態，如 The project is far from finished。","辨析 far 與 further：雖然 far 表示距離，但在商業書信中，further 多用於表示『進一步的』（如 further information），而 far 則常用於強調程度上的差異。"]}],"g6-p1-p2:adjectives:32:crazy":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02414:crazy","word":"crazy","partOfSpeech":["adjective"],"chineseMeaning":"瘋狂的，發狂的；熱衷的；不合理的；精神錯亂的","categoryZh":"一般專業","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adjective","forms":["crazier","craziest"]}],"examples":[{"english":"She's absolutely crazy about that new singer.","chinese":"她對那位新歌手完全著迷了。"},{"english":"It was a crazy idea, but somehow it worked out.","chinese":"那是一個瘋狂的想法，但不知怎地，它成功了。"}],"examTips":["In TOEIC listening (Part 3 & 4), 'crazy' is often used informally to describe an extremely busy schedule or work environment, such as 'Things have been crazy at the office,' which the test may paraphrase as 'hectic' or 'overwhelming.'","Common collocations include 'drive someone crazy' (to annoy) and 'go crazy' (to become very excited), though these are more common in dialogue than in formal business documents.","In the context of marketing or advertisements (Part 7), 'crazy prices' or 'crazy discounts' is a common idiomatic expression meaning 'exceptionally low prices' or 'unbeatable deals.'","For formal writing sections (Part 5 & 6), replace 'crazy' with professional alternatives such as 'absurd,' 'unreasonable,' or 'irrational' when describing business proposals or demands.","Be wary of phonetic traps in listening sections where 'crazy' might be confused with similar-sounding words like 'lazy' or 'hazy' in incorrect answer choices."]}],"g6-p1-p2:preposition:1:against":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00253:against","word":"against","partOfSpeech":["preposition","adverb"],"chineseMeaning":"對抗；反對；與...相對；根據","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[],"examples":[{"english":"The company is taking legal action against the supplier for breach of contract.","chinese":"該公司因違反合約而對供應商採取法律行動。"},{"english":"He argued strongly against the proposed budget cuts.","chinese":"他強烈反對預算削減的提議。"}],"examTips":["常見搭配詞與商業情境：在 TOEIC 閱讀與聽力中，常出現在決定或投票場景，如 'vote against' (投票反對) 或 'decide against' (決定不...)。在財務報告中，常用於數據比較，例如 'performance against last year's figures' (與去年數據相比的表現)。","物理位置與安全防護：常出現在 Part 1 照片描述中，如 'leaning against the wall' (靠在牆上)。在安全規範中常表示預防，如 'precaution against' (預防...的措施)。","易混淆詞辨析：注意 'against' 表示反對或對抗，而 'towards' 表示朝向或支持；在空間位置上，'against' 強調緊貼或支撐，與 'opposite' (在...對面) 不同。","聽力考點：在 Part 3 & 4 的對話中，若聽到 'go against the policy'，表示違反政策，這通常是解決問題過程中的關鍵阻礙。","答題建議：在介系詞填空題中，若空格後接 'regulations'、'the law' 或 'competitors'，通常應優先考慮 'against'，用以表示違反規則或與對手競爭。"]}],"g6-p1-p2:preposition:2:along":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00348:along","word":"along","partOfSpeech":["preposition","adverb"],"chineseMeaning":"沿著；依照；隨著","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adverb","forms":["along"]}],"examples":[{"english":"The project timeline will be adjusted along with the market trends.","chinese":"專案時程將會隨著市場趨勢進行調整。"},{"english":"Please walk along the corridor to find the conference room.","chinese":"請沿著走廊走，尋找會議室。"}],"examTips":["常見搭配詞組：'along with'（與...一起）在多益閱讀 Part 5 與 6 極為常見，常用於表示隨附文件或額外資訊，例如 'Please submit your resume along with two references.'。此外，'get along with'（與...相處）常出現在聽力對話或商業合作情境中。","商業情境運用：在辦公室指引或會議流程中，常用 'along' 來描述路徑或進展，如 'along the corridor'（沿著走廊）或 'all along'（始終、一直以來）。在物流或製造業情境，也常描述物品擺放位置，如 'arranged along the wall'。","易混淆詞辨析：最常與 'alone'（獨自的/地）混淆，'along' 具有方向性或伴隨意涵，而 'alone' 強調單獨；另外需區分 'alongside'（在...旁邊/並排），'alongside' 側重於位置的並列，而 'along' 側重於沿著一條線的移動或分佈。","聽力與閱讀考點：Part 1 照片描述題中，常出現物品或人『沿著』某處排列（e.g., 'Plants are placed along the edge of the terrace'）。在 Part 7 閱讀理解中，'along with' 常作為增加細節的連結詞，考生需辨識主要主體與附加對象。","答題注意事項：若在單字填空題看到空格後方接 'with'，且語意為『連同』或『加上』，應優先考慮 'along'。在描述進展時，'move along' 則代表進度順利進行中。"]}],"g6-p1-p2:preposition:3:except":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03602:except","word":"except","partOfSpeech":["preposition","conjunction"],"chineseMeaning":"除…之外；不包括（用於指出例外情況）","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[],"examples":[{"english":"All employees must submit their expense reports by Friday, except those who are on approved leave.","chinese":"所有員工必須在星期五前提交費用報告，除非已獲批准的休假者。"},{"english":"The new policy applies to all suppliers except those who have signed a grandfather clause.","chinese":"新政策適用於所有供應商，除非已簽署舊條款的供應商。"}],"examTips":["常見搭配詞與結構：最常見用法為 'except for + 名詞/代名詞' 或 'except that + 子句'。在多益閱讀中，'except' 常出現在規則、政策或時間表說明中。","易混淆詞辨析：最常與 'accept' (接受) 混淆。'Except' 是排除、除外，而 'Accept' 是接納、同意。在聽力測驗中，兩者發音極為相近，需根據上下文判斷是 '排除' 還是 '接受'。","與 'besides' 的區別：'Except' 代表從整體中扣除部分 (exclusion)，而 'besides' 則是除了原本之外再加上 (inclusion)。考試中若題目提及額外項目，應選 'besides' 而非 'except'。","多益閱讀 Part 7 關鍵字：當題目出現 'NOT mentioned' 或 'NOT true' 時，文章中常會出現 'except' 來帶出那個不包含的選項，是定位答案的重要線索。","商業情境應用：常用於退換貨政策或辦公規範，如 'Refunds are not possible except in cases of product defects' (除非產品瑕疵，否則不予退款)，考生需掌握其後接續的內容即為唯一的例外情況。"]}],"g6-p1-p2:preposition:4:since":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09232:since","word":"since","partOfSpeech":["preposition","conjunction","adverb"],"chineseMeaning":"自從；由於，因為","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"preposition","forms":["since"]},{"partOfSpeech":"conjunction","forms":["since"]},{"partOfSpeech":"adverb","forms":["since"]}],"examples":[{"english":"We haven't met since last year's conference.","chinese":"自從去年會議後我們就沒再見過面了。"},{"english":"Since the project deadline is approaching, we need to work overtime.","chinese":"由於專案截止日期將近，我們需要加班工作。"}],"examTips":["雙重語意辨析：在多益考試中，since 不僅表示『自從』的時間概念，更頻繁地作為『因為』(because/as) 的同義詞出現在商務書信中，用於解釋原因。","時態連動規則：當 since 表『自從』時，其引導的子句或動作通常使用過去式，而主句則必須使用現在完成式（have/has + p.p.），這是 Part 5 語法題的高頻考點。","介係詞與連接詞區分：since 可作為介係詞後接特定時間點（如 since 2010），或作為連接詞後接完整子句，注意與 for（後接一段時間，如 for five years）進行區分。","常見商務搭配詞：常見搭配包括 since its inception（自成立以來）、since further notice（直到另行通知，注意與 until 的用法混淆）、ever since（從那時起一直）。","聽力與閱讀考點：在 Part 3、4 的聽力中，since 常引導出問題的答案（原因）；而在 Part 7 閱讀中，看到句首的 Since 時，應優先將其理解為『因為』以快速掌握句意。"]}],"g6-p1-p2:pronoun:1:either":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03303:either","word":"either","partOfSpeech":["determiner","pronoun","conjunction","adverb"],"chineseMeaning":"（兩者中）任何一個；或者…或者…；（用於否定句）也（不）","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"determiner","forms":["either"]},{"partOfSpeech":"pronoun","forms":["either"]},{"partOfSpeech":"conjunction","forms":["either"]},{"partOfSpeech":"adverb","forms":["either"]}],"examples":[{"english":"You can choose either the blue shirt or the green one.","chinese":"你可以選擇藍色襯衫或綠色襯衫。"},{"english":"She said she didn't like the movie, and I didn't either.","chinese":"她說她不喜歡那部電影，我也不喜歡。"}],"examTips":["最常見的語法搭配為「either ... or ...」，用於連接兩個對等結構（如名詞、動詞或子句），在閱讀部分若看到 or 應反射聯想 either。","區分「either」與「neither」：either 表示「兩者擇一」，neither 則是「兩者皆非」，且 neither 需搭配 nor，這在文法題中是高頻考點。","掌握單複數一致性：當「either of + 複數名詞」作為主詞時，動詞通常使用單數（如 Either of the candidates is suitable），這在 Part 5 挑錯或選詞中經常出現。","聽力測驗中常見於否定句末尾表示「也不」，例如「I haven't received the report either」，在 Part 2 的回應題中是正確選項的常見形式。","在商業決策情境中，用於提出備選方案，考生應留意對話中提到的兩個選項，因為正確答案往往涉及其中之一。"]}],"g6-p1-p2:pronoun:3:mine":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06350:mine","word":"MINE","partOfSpeech":["pronoun","noun","verb"],"chineseMeaning":"我的 (所有格代名詞); 礦場，礦坑；地雷 (名詞); 挖掘，開採 (動詞)","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"pronoun","forms":["mine"]},{"partOfSpeech":"noun","forms":["mine","mines"]},{"partOfSpeech":"verb","forms":["mine","mined","mining","mines"]}],"examples":[{"english":"This report is mine; I spent all night working on it.","chinese":"這份報告是我的；我熬夜製作它。"},{"english":"The company plans to open a new mine to extract precious minerals.","chinese":"該公司計劃開設一座新礦以開採珍貴礦物。"}],"examTips":["多重詞性辨析：在多益中需區分「mine」作為所有格代名詞（我的東西）與名詞（礦坑、豐富的來源）的用法。","商業情境應用：名詞用法常出現在產業報導中，如「coal mine」（煤礦）或「gold mine」（金礦），亦常用於比喻「a mine of information」（資訊寶庫），形容某人或某資源非常博學或實用。","動詞與數據分析：在現代商業英文中，「mine」常指「開採」或「挖掘」，如「data mining」（資料探勘）是科技與行銷篇章的常見詞彙。","易混淆詞辨析：需注意與所有格形容詞「my」的區別，代名詞「mine」後面不可接名詞（例如：This desk is mine.），而「my」後必須接名詞。","聽力與閱讀考點：在聽力 Part 1 或 Part 2 中，常測試對所有格代名詞的理解；在閱讀 Part 5 語法題中，則常考代名詞與形容詞的選用。"]}],"g6-p1-p2:pronoun:4:nothing":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06720:nothing","word":"nothing","partOfSpeech":["pronoun","adverb"],"chineseMeaning":"一無所有；沒有任何事物","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["nothing"]},{"partOfSpeech":"adverb","forms":["nothing"]}],"examples":[{"english":"I'm afraid there's nothing we can do about the delayed shipment at this point.","chinese":"很抱歉，目前我們對這批延遲的貨物無能為力。"},{"english":"The report indicates nothing unusual in the company's financial performance.","chinese":"報告顯示公司財務表現沒有任何異常情況。"}],"examTips":["常見搭配詞「nothing but」：意同於「only」或「merely」，在 TOEIC 閱讀 Part 5 或 Part 6 中，常出現在句子中表示「僅僅、只不過是」，例如「The delay was nothing but a minor technical glitch」。","商業情境常用語「have nothing to do with」：此片語表示「與...無關」，在商務會議或電子郵件中常用於澄清責任歸屬或解釋變數之間的無關聯性，例如「The decline in sales has nothing to do with the new marketing campaign」。","語法結構辨析：考生需區分「nothing」與「anything」的用法。在包含否定詞（如 don't, won't）的句子中應使用 anything，而在肯定動詞後表達否定含義時使用 nothing（例如：I have nothing to report 意同於 I don't have anything to report）。","聽力 Part 2 答題技巧：當問題以「What...」開頭詢問某事物的內容或進展時，「Nothing」或「Nothing yet」是常見的簡潔正確選項，表示「沒什麼」或「目前還沒有」。","高階慣用語「next to nothing」：在描述預算、利潤或成本時，此詞組表示「幾乎沒有」或「極少」，例如「The startup costs were next to nothing」，考生應能迅速辨識其含義為接近零。"]}],"g6-p1-p2:pronoun:5:none":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06683:none","word":"none","partOfSpeech":["pronoun","adjective"],"chineseMeaning":"沒有；無；不存在","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[],"examples":[{"english":"There are no available slots for the training session next week.","chinese":"下週的培訓課程沒有任何空位。"},{"english":"We have none of the requested documents on file at this time.","chinese":"目前我們沒有任何要求的文檔。"}],"examTips":["代名詞用法與結構：'none' 是代名詞，用於替代前面提到的名詞，常用結構為 'none of the [複數名詞/不可數名詞]'。需注意它與形容詞 'no' 的區別，'no' 後方必須緊跟名詞，而 'none' 則獨立擔任主語或賓語。","主動詞一致性：在 TOEIC 語法題中，'none of the + 複數名詞' 後接的動詞在正式用法中傾向於使用單數（如 None of the equipment is working），但在口語中接複數動詞也屬常見；解題時應優先觀察上下文的正式程度。","聽力 Part 2 常考答句：'none' 經常作為 'How many' 或 'How much' 開頭疑問句的簡短回答，用來表示『一個也沒有』或『完全沒有』，是極為常見的正確選項模式。","易混淆詞辨析：區分 'none' 與 'no one/nobody'。'none' 可指代人或物，通常指特定群體中的否定（none of them）；'no one' 僅指人，且多為泛指。","商業實務用法：在商業閱讀中，常出現於合約或表單的 'none of the above'（以上皆非）選項，或用於報告中描述資源短缺，如 'none of the candidates met the criteria'（沒有一位應徵者符合標準）。"]}],"g6-p1-p2:pronoun:6:nobody":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06671:nobody","word":"nobody","partOfSpeech":["pronoun"],"chineseMeaning":"沒有人； niemand","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["nobody"]}],"examples":[{"english":"Nobody attended the optional training session.","chinese":"沒有人參加了這場可選的培訓課程。"},{"english":"Nobody knows the exact details of the contract negotiations.","chinese":"沒有人知道合約談判的確切細節。"}],"examTips":["主詞動詞一致性：'nobody' 在文法上始終視為單數代名詞，其後接動詞必須使用單數型態（如：Nobody is, Nobody has, Nobody knows），這在 Part 5 的主動詞一致性題目中是常見考點。","聽力測驗 Part 2 答題技巧：當問句以 'Who' 開頭時（例如：Who is attending the seminar?），'Nobody' 或 'No one' 是非常典型的答案，考生應練習快速辨識此種否定應答。","語意辨析與正式度：在多益閱讀測驗的正式商務書信或合約中，通常較常出現 'no one'，而 'nobody' 則多出現在 Part 3 與 Part 4 的非正式口語對話中，兩者意義相同。","避免雙重否定：'nobody' 本身已具備否定含意，因此不可與 'not' 並用（例如應為 Nobody knows 而非 Nobody doesn't know），在 Part 6 段落填空中需注意邏輯的一致性。","常見情境搭配：在多益聽力中常出現於辦公室情境，如 'Nobody is available at the moment'（目前沒人在）或 'Nobody has seen the report'（沒人看過那份報告），用來表示資訊的缺失或人力的缺乏。"]}],"g6-p1-p2:pronoun:8:ourselves":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06997:ourselves","word":"ourselves","partOfSpeech":["pronoun"],"chineseMeaning":"我們自己；我們自身（強調主語是我們自己）","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["ourselves"]}],"examples":[{"english":"We need to review our procedures to ensure we are meeting all regulatory requirements ourselves.","chinese":"我們需要審查我們的流程，以確保我們自己符合所有法規要求。"},{"english":"The team decided to handle the project themselves to maintain quality control.","chinese":"團隊決定自行處理專案，以維持品質控制。"}],"examTips":["反身代名詞用法：當句子的主詞是 We 且受格也是同一群人時，必須使用 ourselves，常見於 Part 5 的代名詞選填題。","常用搭配詞組：'by ourselves' 表示『靠我們自己』或『獨立完成』，在商業情境中常用於強調團隊在不需外部顧問或資源的情況下完成任務。","易混淆詞辨析：區分 ourselves (反身代名詞) 與 us (受格代名詞)；若動作的發出者與接收者相同，則選 ourselves，例如 'We pride ourselves on quality service'。","強調用法：ourselves 可以放在 We 之後或句尾，用來加強語氣，強調是『我們親自』做了某事，如 'We ourselves will handle the negotiations'。","考試陷阱：題目若出現 'between ____' 且主詞為 We 時，要注意 context，若指『我們彼此之間』通常用 between us，除非是強調自我內部的互動。"]}],"g6-p1-p2:pronoun:9:somebody":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09385:somebody","word":"somebody","partOfSpeech":["pronoun"],"chineseMeaning":"某人；有人（指未指明的人）","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["somebody"]}],"examples":[{"english":"Somebody left their briefcase in the conference room.","chinese":"有人把公事包忘在會議室裡。"},{"english":"If somebody knows the answer to this question, please raise your hand.","chinese":"如果有人知道這個問題的答案，請舉手。"}],"examTips":["主詞動詞一致性：somebody 在語法上視為單數，後接動詞須用單數形式，如 'Somebody has left their umbrella'，這是閱讀測驗文法題的基礎考點。","肯定句的使用慣例：somebody 主要用於肯定句；在聽力測驗中，若出現在疑問句中，通常隱含說話者預期答案為『是』或正在提出請求。","商業情境中的模糊代稱：常用於指代職位不明或不需具名的人員，例如 'Somebody from accounting'，考生需透過上下文判斷該對象的職能。","與 anybody 的區別：anybody 用於否定句或不確定的疑問句，而 somebody 則用於指代『某個具體存在但未指名的人』，這在克漏字中常作為選項干擾。","形容詞修飾位置：若有形容詞修飾，必須置於其後，例如 'somebody qualified'，這在 TOEIC 閱讀的詞類排列題中是常見的陷阱。"]}],"g6-p1-p2:pronoun:10:someone":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09388:someone","word":"someone","partOfSpeech":["pronoun"],"chineseMeaning":"某人；不具名的人","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["someone"]}],"examples":[{"english":"Someone left their briefcase in the conference room.","chinese":"有人把公事包忘在會議室裡。"},{"english":"If someone has any questions, please feel free to ask.","chinese":"如果有人有任何問題，請隨時提出。"}],"examTips":["單數主詞一致性：someone 在文法上視為單數代名詞，在多益 Part 5 中常考其後接單數動詞（如 is, has, takes），考生需注意主謂一致性。","與 anyone 的用法辨析：someone 通常用於肯定句中，代表某個特定但未具名的人；而 anyone 則用於否定句或疑問句中。但在表示禮貌性的請求或提議（如：Would you like someone to help?）時，亦可使用 someone。","聽力測驗情境：在 Part 1 照片描述中，若無法辨識人物職位，選項常以 someone is... 開頭來描述其動作。在 Part 2 答句中，常用於指派任務或回報狀況，如 Someone from the marketing team will call you back。","搭配詞組：常見用法包括 someone in charge (負責某事的人) 或 someone with experience (有經驗的人)，在閱讀測驗的徵才廣告或內部公告中經常出現。","代名詞指稱：在多益長篇文章中，someone 之後可能會使用 they/them/their 作為性別中性的代名詞，雖然文法上 someone 為單數，但這種指代方式在現代商業英語中非常普遍。"]}],"g6-p1-p2:pronoun:11:something":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09389:something","word":"something","partOfSpeech":["noun","pronoun"],"chineseMeaning":"某事；某物（指未明確說明或不重要的事物）","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["something","somethings"]}],"examples":[{"english":"The manager mentioned there's something wrong with the shipment, but he didn't specify what.","chinese":"經理提到貨運出了點問題，但他沒有具體說明是什麼。"},{"english":"Is there something I can do to help you with your project?","chinese":"我能為您的專案做些什麼嗎？"}],"examTips":["形容詞後置語法：在 TOEIC Part 5 中常考 something 的修飾位子，形容詞必須置於其後，例如 something innovative 或 something urgent。","與 anything 的區別：something 通常用於肯定句，或是語氣較為肯定的請求與建議；anything 則多用於否定句或一般疑問句。","商業對話常見搭配：\"do something about\" 表示「針對某事採取行動」，常用於處理客訴或專案問題；\"something like\" 則用來表達「大約」或「類似於」，在聽力測驗中常見於討論預算或時程。","代名詞指代：在閱讀 Part 7 中，something 常指代前文提到的抽象概念或具體需求，需透過上下文判讀其確切指涉對象。","非正式口語表達：聽力 Part 3 中常出現句尾加 \"or something\" 表示「之類的」，考生需理解這是一種不確定但涵蓋相關範疇的語氣。"]}],"g6-p1-p2:pronoun:13:yourself":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:11225:yourself","word":"yourself","partOfSpeech":["pronoun"],"chineseMeaning":"指代自己；親自","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["yourself"]}],"examples":[{"english":"Please review the document yourself before submitting it to your supervisor.","chinese":"請在提交給您的主管之前，親自審閱文件。"},{"english":"Make sure you familiarize yourself with the company's policies and procedures.","chinese":"請務必熟悉公司的政策和流程。"}],"examTips":["反身代名詞核心用法：在 TOEIC Part 5 文法題中，當句子的主詞是 You 且受詞也是同一人時，必須使用 yourself。特別注意在「祈使句」中（如：Please introduce yourself），主詞 You 被省略，考生需能判斷出此時受詞應選反身代名詞。","固定搭配與同義轉換：常見片語「by yourself」等於「on your own」，意指「獨自」或「靠你自己」。這在 Part 7 的商業書信中常用來描述員工獨立完成專案的能力。","強調用法辨析：yourself 可緊跟在代名詞 You 之後或放在句尾，用來強調「你本人」。例如：「You yourself are responsible for the report.」（你本人需對報告負責），這類結構常用於釐清責任歸屬。","常見商業情境表達：在多益聽力 Part 3 中，常出現如「Help yourself to some coffee.」（請隨意享用咖啡）或「Make yourself at home.」（別拘束）等辦公室招待情境，熟悉這些口語表達有助於快速掌握對話重點。","答題注意事項：考生容易混淆 You（受格）與 Yourself。解題關鍵在於尋找動作的發起者（主詞），若主詞與受詞皆指涉同一對象，應優先考慮反身代名詞。"]}],"g6-p1-p2:pronoun:27:anything":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00475:anything","word":"anything","partOfSpeech":["pronoun","adverb"],"chineseMeaning":"任何事物；無論什麼","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["anything"]},{"partOfSpeech":"adverb","forms":["anything"]}],"examples":[{"english":"Is there anything I can do to help you with your presentation?","chinese":"有什麼我可以幫你準備簡報的嗎？"},{"english":"We appreciate any information you can provide regarding the shipment delay.","chinese":"我們感謝您能提供關於貨物延遲的任何資訊。"}],"examTips":["否定與疑問句的基本用法：在 TOEIC 聽力 Part 1 與 Part 2 中，anything 常用於否定句（如 I haven't heard anything）或疑問句中，表示「任何事」。","易混淆片語辨析：重點區分「anything but」（絕非、一點也不）與「nothing but」（僅僅、只有），這在 Part 5 詞彙題中是常見的高階陷阱。","形容詞後置修飾：anything 必須接形容詞在後，例如「anything urgent」（任何緊急的事）或「anything specific」（任何具體的事），這在 Part 6 短文填空或 Part 7 商業書信中經常出現。","商業對話常見搭配：在 Part 3 與 Part 4 的客戶服務情境中，常聽到「Is there anything else I can help you with?」（還有其他我能幫您的嗎？），需對此固定搭配保持敏感度。","條件句用法：常用於 if 引導的條件句，例如「If you need anything, please let me know」，此為商業電子郵件最常見的結尾語之一。"]}],"g6-p1-p2:pronoun:28:anybody":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00471:anybody","word":"anybody","partOfSpeech":["pronoun"],"chineseMeaning":"任何人；無論誰","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["anybody"]}],"examples":[{"english":"Is anybody home?","chinese":"家裡有人嗎？"},{"english":"Does anybody have a pen I can borrow?","chinese":"有沒有人有筆可以借我？"}],"examTips":["動詞單複數一致性：anybody 在英文文法中視為單數代名詞，其後的動詞必須使用單數形式（例如：has, is, works），這是 TOEIC 閱讀 Part 5 句型填空題中常見的基礎考點。","肯定句中的特殊含意：雖然 anybody 常見於否定句與疑問句中，但在肯定句中表示「任何人、無論是誰」的意思，例如：「Anybody can access the file.」(任何人都能存取這份文件)，這在商務公告或規則說明中頻率極高。","與 anyone 的辨析：anybody 與 anyone 在語意上幾乎完全相同且可互換，但在商務寫作與正式文件中，anyone 出現的頻率通常高於 anybody，後者則較常用於口語對話與聽力測驗情境中。","常見搭配詞組：考試中常出現「anybody else」（還有其他人）或接形容詞如「anybody interested」（任何感興趣的人），例如在徵才或內部培訓的商務情境中：「If anybody is interested in the workshop, please sign up.」。","代名詞的一致性：在現代商務英文或聽力測驗中，為了避免性別偏見，當指稱前面出現的 anybody 時，常會使用複數代名詞 they、them 或 their 來指代，考生在聽力理解時應注意這種語法習慣。"]}],"g6-p1-p2:pronoun:29:anyone":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00474:anyone","word":"anyone","partOfSpeech":["pronoun"],"chineseMeaning":"任何人；任何一人（通常用於表示不確定性或詢問是否有人符合條件）","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["anyone"]}],"examples":[{"english":"Is there anyone who can speak fluent Spanish to assist our client?","chinese":"請問有誰能流利地說西班牙語來協助我們的客戶嗎？"},{"english":"Anyone interested in the project should submit their application by Friday.","chinese":"對這個專案有興趣的人請在星期五前提交申請。"}],"examTips":["代名詞單複數一致性：'anyone' 在文法上被視為單數，其後的動詞必須使用單數型態（例如：anyone who wants），這在 Part 5 的主詞動詞一致性題目中經常出現。","與分詞的搭配：在閱讀測驗中，'anyone' 常與現在分詞（V-ing）搭配作為後置修飾，例如 'anyone interested in the position'（對該職位感興趣的人）或 'anyone wishing to attend'（想參加的人），考生需能辨識出省略了 'who is' 的結構。","與 someone 的區別：'anyone' 常用於否定句、疑問句或 if 條件句；而在肯定句中，'anyone' 意指 '任何人、無論誰'，語氣比 'someone' 更廣泛。","商業情境用法：常用於公司公告（announcements）中，邀請員工參與活動或收集反饋，例如 'Anyone who has a conflict with the schedule should notify the manager.'。","倒裝句應用：在正式書信結尾常出現 'Should anyone have questions...'，這與 'If anyone has questions...' 意思相同，是多益 Part 6 常考的高階句型。"]}],"g6-p1-p2:pronoun:30:everybody":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03570:everybody","word":"everybody","partOfSpeech":["pronoun"],"chineseMeaning":"每個人；全體人，指包含所有人","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["everybody"]}],"examples":[{"english":"Everybody is required to attend the mandatory safety training session.","chinese":"每個人都必須參加強制性的安全培訓課程。"},{"english":"The manager announced that everybody would receive a bonus based on company performance.","chinese":"經理宣布，根據公司業績，每個人都會獲得獎金。"}],"examTips":["單複數一致性：這是 TOEIC 文法測驗中最常見的考點，'everybody' 雖然意思是指『每個人』(所有人)，但在語法上必須視為『單數』，後接動詞需加 s 或使用 is/has。","正式程度辨析：在商務書信或正式公告中，通常會使用 'everyone' 取代 'everybody'，後者口語色彩較濃，常用於辦公室日常交談或非正式會議中。","代名詞呼應：當需要用代名詞指代 'everybody' 時，現代英語（包含多益考試情境）常用 'they/them/their' 來避免性別偏差，例如：'Everybody should bring their own laptop.'。","常見搭配情境：在聽力測驗 Part 1 或 Part 4 的公告中，常出現 'Everybody is requested to...' 或 'Everybody is reminded that...' 等句型，用來對全體員工發布指令。","排除干擾項：在閱讀 Part 5 選擇題中，若選項同時出現 'all' 與 'everybody'，需注意 'all' 通常接複數動詞，而 'everybody' 必接單數動詞。"]}],"g6-p1-p2:pronoun:31:everyone":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03572:everyone","word":"everyone","partOfSpeech":["pronoun"],"chineseMeaning":"每個人；所有人（指不分個人，包含所有成員）","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"pronoun","forms":["everyone"]}],"examples":[{"english":"Everyone is expected to attend the mandatory training session.","chinese":"每個人都預計參加強制性培訓課程。"},{"english":"Everyone should review the updated company policy before the meeting.","chinese":"在會議之前，每個人都應該審閱更新後的公司政策。"}],"examTips":["主詞動詞一致性：everyone 雖然語意上指多人，但在文法上視為「單數代名詞」，其後的動詞必須使用單數形式（如：Everyone has, Everyone is）。這是 Part 5 語法題最常見的考點。","商業信件開場：在職場 Email 中，常使用 \"Hi everyone\" 或 \"Dear everyone\" 作為對全體同仁的非正式稱呼。","易混淆詞辨析：區分 everyone（所有人）與 every one（每一個）。\"Every one\" 通常後接 of，強調群體中的每一個個體（如：Every one of the reports is ready）。","代名詞指代：在現代英文中，為了性別中立，常使用 they/them/their 來指代 everyone（如：Everyone should bring their own laptop），這在聽力測驗中經常出現。","常見考點陷阱：題目常在 everyone 之後加入介係詞片語干擾（如：Everyone in the two departments IS attending...），考生需避開複數名詞的干擾，鎖定單數主詞。"]}],"g6-p1-p2:pronoun:32:everything":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03573:everything","word":"everything","partOfSpeech":["pronoun"],"chineseMeaning":"所有事物；一切事物（通常指數量眾多的事物或範圍廣泛的事物）","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[],"examples":[{"english":"Please double-check everything before submitting the report.","chinese":"請在提交報告前仔細檢查所有內容。"},{"english":"We need to review everything to ensure compliance with the new regulations.","chinese":"我們需要審查所有內容，以確保符合新的法規。"}],"examTips":["主詞動詞一致性：everything 為單數不定代名詞，在文法上必須搭配單數動詞（如 is, has, works），這是 Part 5 基礎文法題的常考點。","商業情境運用：在辦公室溝通中常出現於確認狀態，例如 'Everything is on schedule'（一切按進度進行）或 'Is everything ready for the meeting?'（會議的一切都準備好了嗎？）。","與 All 的辨析：everything 指「每一件事物」的集合，不接名詞；而 all 則常後接名詞（如 all the files），兩者在句子結構上的位置不同。","聽力 Part 2 技巧：在問答部分，當聽到有關專案狀態或準備工作的疑問句時，以 'Everything' 開頭的回答往往是確認任務已全面完成的正確選項。","常見搭配詞：常用搭配包括 everything else（其餘所有事物）、everything included（包含一切費用或項目）、make sure everything is in order（確保一切井然有序）。"]}],"g6-p1-p2:pronoun:33:everywhere":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03574:everywhere","word":"everywhere","partOfSpeech":["adverb"],"chineseMeaning":"無處不在；各處","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adverb","forms":["everywhere"]}],"examples":[{"english":"The company's logo is displayed everywhere in the office building.","chinese":"公司的標誌在辦公大樓的各處都可見。"},{"english":"Due to the widespread adoption of remote work, employees can now access company resources everywhere.","chinese":"由於遠端工作的廣泛採用，員工現在可以在各處存取公司資源。"}],"examTips":["副詞性質：everywhere 是副詞，表示「到處、各處」，在使用時其前面通常不需要加介係詞，例如要說 go everywhere 而非 go to everywhere。","商業情境應用：在 TOEIC 考試中，此單字常用於描述市場覆蓋率或產品的可用性，例如 'The new smartphone is available everywhere in the city'。","相似詞辨析：與 anywhere 相比，everywhere 強調的是「全部的地方」，而 anywhere 則常用於否定句或疑問句中表示「任何地方」。","聽力考點：在聽力測驗 Part 1 的照片描述中，若照片顯示物品散落各處，選項中可能會出現此字。","閱讀理解：在 Part 7 的廣告或促銷信件中，everywhere 常用來強調品牌影響力或服務網絡的廣泛性。"]}],"g6-p1-p2:pronoun:34:herself":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04749:herself","word":"herself","partOfSpeech":["pronoun"],"chineseMeaning":"她自己；她本人","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[],"examples":[{"english":"She handled the project entirely by herself.","chinese":"她完全靠自己處理了這個專案。"},{"english":"She taught herself to use the new software.","chinese":"她自學了如何使用新的軟體。"}],"examTips":["反身代名詞的基本用法：在 TOEIC 閱讀第五部分中，常考反身代名詞作為動詞或介系詞受格的用法。當主詞與受詞是同一人時必須使用 herself，例如：'She taught herself how to use the new software.'。","強調用法：herself 可用來強調主詞本身，通常放在主詞後或句尾。在商務情境中，這常用來表示某位女性主管「親自」處理某事，如：'The CEO herself attended the meeting.'。","固定搭配片語：最常考的搭配是 'by herself'，意同於 'alone' 或 'on her own'，表示「獨自一人」或「不靠他人幫助地」。","詞性辨析與陷阱：在解題時，須區分受格 (her)、所有格代名詞 (hers) 與反身代名詞 (herself)。若空格前有及物動詞且主詞為女性，應檢查動作是否回到主詞身上來判斷是否選用 herself。","聽力測驗考點：在 Part 1 或 Part 2 中，herself 常出現在描述人物動作的句子中，考生需注意主詞與動詞受格的一致性。"]}],"g6-p1-p2:pronoun:35:himself":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04771:himself","word":"himself","partOfSpeech":["pronoun"],"chineseMeaning":"自己（反身代名詞，強調主語和賓語是同一人或事物）","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[],"examples":[{"english":"He taught himself how to use the new software.","chinese":"他自學了如何使用新的軟體。"},{"english":"The manager decided to handle the situation himself.","chinese":"經理決定自己處理這個情況。"}],"examTips":["反身代名詞核心用法：在 TOEIC Part 5 中常考主詞與受詞為同一人的情況，考生需確認句中主詞為單數男性（如 He, Mr. Smith, the CEO），受詞則應選 himself。","強調用法：himself 可置於主詞後或句尾用來強調「本人」，例如：'The President himself signed the contract.'，在閱讀測驗中識別此結構有助於理解強調點。","固定搭配片語：最常見的是 'by himself'，意指 'alone'（單獨）或 'without help'（靠自己），在描述商務專案獨立完成的情境中頻率極高。","易混淆辨析：常與受格 him、所有格 his 或所有格代名詞 his 混淆；判斷標準在於「主格是否與該代名詞指代同一人」，若非同一人則不可選 himself。","作為介系詞受詞：在商務書信中常出現如 'He took the initiative upon himself'（他主動承擔責任）或 'He kept the information to himself'（他對資訊保密）等用法，需注意介系詞的搭配。"]}],"g6-p1-p2:pronoun:36:myself":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06545:myself","word":"myself","partOfSpeech":["pronoun"],"chineseMeaning":"我自己；本人","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[],"examples":[{"english":"I'll handle this project myself to ensure it's completed on time.","chinese":"我會自己處理這個專案，以確保它能按時完成。"},{"english":"Please review the contract yourself before signing it.","chinese":"請在簽署合約前自行審閱。"}],"examTips":["反身代名詞基本用法：當主詞與受詞為同一人時（即 I 作為主詞），受詞必須使用 myself。在 TOEIC Part 5 填空題中，若空格前的主詞是 I，且語意上動作回歸到主詞，應選 myself 而非 me。","強調用法：myself 常放在句尾或主詞 I 之後，用以強調『本人親自』完成某事，例如：'I will review the proposal myself'（我會親自審核這份提案）。","常見介系詞搭配 'by myself'：這是多益極常見的片語，等於 alone 或 on my own，意指『獨自一人』或『靠自己（無他人協助）』。","易混淆詞辨析：區分 me (受格) 與 myself (反身代名詞)。關鍵在於檢查主詞，若主詞不是 I，則不能使用 myself。例如：'She sent the email to me' (正確)，不可用 myself。","商業情境應用：在聽力 Part 2 或閱讀 Part 7 中，常用於自我介紹（Let me introduce myself）或表達負責特定項目的自主權（I managed the project by myself）。"]}],"g6-p1-p2:adverb:1:absolutely":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00044:absolutely","word":"absolutely","partOfSpeech":["adverb"],"chineseMeaning":"完全地；絕對地，表示肯定或無疑。","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adverb","forms":["absolutely"]}],"examples":[{"english":"I absolutely agree with your proposal to streamline the workflow.","chinese":"我完全同意你簡化工作流程的建議。"},{"english":"The project must be completed absolutely on time, no exceptions.","chinese":"這個項目必須絕對準時完成，不允許有任何例外。"}],"examTips":["常見搭配詞與語法：常用於修飾極限形容詞（extreme adjectives），如 absolutely necessary（絕對必要）、absolutely essential（絕對關鍵）或 absolutely free（完全免費）。在 Part 5 文法題中，注意它作為副詞修飾形容詞的用法。","聽力測驗的強烈認同：在 Part 2 簡短問答或 Part 3 對話中，Absolutely 常作為獨立的回答，表示完全同意對方的觀點或提議（同義於 Definitely 或 Certainly），是判斷說話者態度（Agreement）的重要關鍵。","商業情境中的承諾：在 Part 4 的短文中，常用於強調公司對品質或服務的保障，例如「We absolutely guarantee client satisfaction」，此時代表百分之百的保證。","辨析注意事項：避免將 absolutely 與修飾「一般形容詞」的副詞混淆，例如通常不說 absolutely good（應說 very good），而說 absolutely fantastic；且不可修飾比較級形容詞（如不可說 absolutely faster）。","閱讀理解考點：在 Part 7 的商業信函中，若出現該詞通常代表某種先決條件或不可變動的截止日期，考生需留意其背後所強調的強制性。"]}],"g6-p1-p2:adverb:4:already":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00353:already","word":"already","partOfSpeech":["adverb"],"chineseMeaning":"表示動作或情況已經發生，通常用於強調時間先後或完成。","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adverb","forms":["already"]}],"examples":[{"english":"The report is already submitted, so please do not send a reminder.","chinese":"報告已經提交，請不要發送提醒。"},{"english":"We have already confirmed the meeting with the vendor.","chinese":"我們已經確認了與供應商的會議。"}],"examTips":["詞彙辨析：在 TOEIC 文法題（Part 5 & 6）中，常與 yet 和 still 進行對比。already 通常用於肯定句，表示事情比預期更早完成；yet 常用於疑問或否定句；still 則強調動作持續中。","語法位置：already 常用於現在完成式，典型位置在助動詞 (have/has) 與過去分詞 (P.P.) 之間，例如：The shipment has already been delivered。","易混淆詞辨析：務必區分 already (副詞，已經) 與 all ready (片語，全部準備好)。兩者在聽力中發音相近，需透過上下文判斷，例如：The team is all ready for the workshop。","商業情境應用：常用於確認訂單狀態或回報任務進度，例如：I have already processed your refund 或 The seats are already reserved。","聽力與閱讀考點：在 Part 2 簡短問答中，聽到 already 常意味著某動作已完成，可用來排除表示「尚未開始」或「正在計畫」的錯誤選項。"]}],"g6-p1-p2:adverb:5:ahead":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00282:ahead","word":"ahead","partOfSpeech":["adverb","preposition"],"chineseMeaning":"在...之前；領先；提前","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adverb","forms":["ahead"]}],"examples":[{"english":"The project is currently ahead of schedule and we expect to complete it by next week.","chinese":"該專案目前進度領先，我們預計下週完成。"},{"english":"Please submit your expense report ahead of the deadline to ensure timely reimbursement.","chinese":"請在截止日期前提交您的費用報告，以確保及時報銷。"}],"examTips":["最常見的商業搭配詞為 'ahead of schedule'（進度超前），這在 Part 7 的專案進度報告或電子郵件中極高頻出現，常與 'behind schedule' 作為對比考點。","在聽力 Part 2 或 Part 3 的對話中，'go ahead' 常用來表示「請繼續」或「給予許可」，例如：'Please go ahead with the proposal'（請開始執行該提案）。","區分 'ahead' 與 'front'：'ahead' 通常作副詞或形容詞，指在前方或時間提前；而 'front' 多作名詞或形容詞，指具體的正面位置。","'Plan ahead'（預先計畫）是常見的職場建議用語，在公告或內部Memo中經常用來強調未雨綢繆的重要性。","在表達競爭力時，'ahead of the curve' 或 'ahead of competitors' 常用於公司簡介或產業評論，描述某企業在技術或市場份額上的領先地位。"]}],"g6-p1-p2:adverb:6:completely":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02001:completely","word":"completely","partOfSpeech":["adverb"],"chineseMeaning":"完全地；徹底地","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adverb","forms":["completely"]}],"examples":[{"english":"The report needs to be reviewed completely before it's submitted to the board.","chinese":"在提交給董事會之前，報告需要完全審閱。"},{"english":"The project was completed completely on schedule and within budget.","chinese":"這個專案完全按照計畫和預算完成。"}],"examTips":["常見搭配詞組：常用於強調程度，例如 'completely satisfied' (完全滿意)、'completely different' (完全不同)、'completely free of charge' (完全免費) 以及 'completely agree' (完全同意)。","商業情境應用：在 TOEIC 閱讀的滿意度調查中，常出現於選項或問卷結果中，用來表示客戶對服務或產品的極端正面評價；在專案報告中，則用於表示任務已百分之百達成，如 'the project is completely finished'。","易混淆詞辨析：需區分 'completely' 與 'thoroughly'。'Completely' 側重於整體或數量的完整性，而 'thoroughly' 則側重於過程的詳盡與徹底。","TOEIC 考點分析：在 Part 5 詞彙或詞性題中，常考副詞修飾形容詞或過去分詞的位置。例如：'The renovation is (completely) finished.'，此時需選擇副詞而非形容詞。","答題注意事項：注意 'completely' 為絕對性副詞，在聽力測驗中，若選項含有此類強烈語氣詞，需仔細回聽原文是否有相符的絕對含意，避免掉入過度推論的陷阱。"]}],"g6-p1-p2:adverb:7:differently":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02883:differently","word":"differently","partOfSpeech":["adverb"],"chineseMeaning":"不同地；以不同的方式","categoryZh":"溝通互動","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adverb","forms":["differently"]}],"examples":[{"english":"We need to approach this project differently to meet the new deadline.","chinese":"為了達到新的截止日期，我們需要以不同的方式來處理這個專案。"},{"english":"The marketing team decided to promote the product differently this quarter.","chinese":"行銷團隊決定在本季以不同的方式來推廣產品。"}],"examTips":["詞性辨析考點：TOEIC 第五部分（句子填空）極常考察形容詞 different 與副詞 differently 的區分。當空格位於一般動詞（如 handle, approach, view, operate）之後用以修飾動作執行的方式時，應優先選擇副詞 differently。","常見搭配詞組：常用於 think differently（以不同方式思考/創新）、approach the situation differently（以不同方式處理情況）或 handle the task differently（以不同方式處理任務）。","商業情境應用：在會議討論或政策變更的閱讀篇章中，常用來描述流程的改進，例如 \"The new system allows us to process orders differently.\"。","與介係詞的搭配：在閱讀測驗中，differently 常與 from 連用（differently from...），用來比較新舊方案或競爭對手的策略，考生應注意此固定用法。","聽力與閱讀的改寫（Paraphrasing）陷阱：在 Part 7 閱讀中，文章若提到 \"in a new way\" 或 \"a modified approach\"，正確選項常會使用 differently 來進行同義替換，考生需具備這種語義轉換的敏感度。"]}],"g6-p1-p2:adverb:8:else":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03343:else","word":"else","partOfSpeech":["adverb","conjunction"],"chineseMeaning":"除此之外；別的；其他的","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adverb","forms":["else"]}],"examples":[{"english":"If you need anything else, please don't hesitate to contact us.","chinese":"如果您需要任何其他協助，請隨時與我們聯繫。"},{"english":"We can offer you a discount, or else we can provide free shipping.","chinese":"我們可以提供您折扣，或者我們可以提供免費運送。"}],"examTips":["常見搭配詞與語法位置：else 通常緊跟在不定代名詞（如 something, anything, someone, nothing）或疑問詞（如 what, who, where）之後。在多益聽力中，常聽到 'Is there anything else?' (還有別的事嗎？) 作為客服或會議結尾。","商業情境應用：else 常出現在協商或替代方案的討論中，例如 'If the first candidate declines, we will look for someone else.'（如果第一位候選人拒絕，我們會尋找其他人選）。","易混淆詞辨析：需區分 else 與 other 的位置。else 置於代名詞後（e.g., somewhere else），而 other 置於名詞前（e.g., other places）。在 Part 5 填空題中，若空格在 someone 之後，應選 else 而非 other。","常見慣用語 'or else'：在合約或要求中，'or else' 用來表示「否則」，引出不履行義務的後果。例如：'The payment must be made by Friday, or else a late fee will apply.'。","答題注意事項：注意 'else's' 的所有格用法，雖然在多益中較少見，但在閱讀測驗中若看到 'someone else's desk'，應理解為「別人的辦公桌」，不要誤認為語法錯誤。"]}],"g6-p1-p2:adverb:9:sincerely":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09234:sincerely","word":"sincerely","partOfSpeech":["adverb"],"chineseMeaning":"真誠地；誠懇地","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"adverb","forms":["sincerely"]}],"examples":[{"english":"I sincerely apologize for the inconvenience caused by the delayed shipment.","chinese":"對於延遲交貨造成的困擾，我深感抱歉。"},{"english":"We appreciate your feedback and will address your concerns sincerely.","chinese":"我們感謝您的回饋，並將誠懇地處理您的疑慮。"}],"examTips":["商務書信結尾：sincerely 是 TOEIC 閱讀測驗（Part 6 & 7）中最常見的商務書信結尾用語，通常位於信末簽名前。常見寫法為 'Sincerely,' 或 'Sincerely yours,'。","常見搭配詞：常與動詞搭配表示誠意，如 'sincerely apologize'（誠摯道歉）或 'sincerely hope'（誠摯希望），這在聽力測驗 Part 3 & 4 的正式聲明中經常出現。","易混淆詞辨析：需區分 seriously (認真地/嚴重地) 與 severely (嚴厲地)。sincerely 強調態度真誠，而非事情的嚴重性。","詞性考點：在 Part 5 詞彙題中，常考副詞詞性。若空格位於動詞前後或句首/句末修飾全句，應選擇副詞形式 sincerely 而非形容詞 sincere。","語氣辨識：sincerely 帶有正式且尊重的語氣，可用來判斷文章或對話的正式程度，幫助解答有關說話者意圖或關係的題目。"]}],"g6-p1-p2:adverb:10:suddenly":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09828:suddenly","word":"suddenly","partOfSpeech":["adverb"],"chineseMeaning":"突然地；驟然地","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adverb","forms":["suddenly"]}],"examples":[{"english":"The meeting was cancelled suddenly due to unforeseen circumstances.","chinese":"由於突發狀況，會議突然被取消。"},{"english":"The power went out suddenly, disrupting the presentation.","chinese":"電力突然中斷，導致簡報被打亂。"}],"examTips":["常見搭配詞與同義替換：在多益測驗中 suddenly 常與 change, stop, occur 等動詞連用，表示情況的突發性。常見的同義片語為 \"all of a sudden\" 或副詞 \"unexpectedly\"，在聽力測驗中常作為換句話說的考點。","商業情境應用：常用於描述市場趨勢的驟變或突發的人事變動（例如：suddenly resign）。在閱讀測驗的商業書信中，它常用來引出一個需要立即處理的意外狀況。","易混淆詞辨析：與 abruptly 相似，但 abruptly 帶有「生硬、無禮」或「戛然而止」的語感；其反義詞為 gradually (逐漸地)，這對反義詞常在描述業績或股價變動的圖表題中作為干擾項。","聽力與閱讀考點：在多益聽力第三、四部分，suddenly 往往標示著劇情的轉折或問題的發生，是定位答案（如：What is the problem?）的重要訊號字。","詞性判斷技巧：多益 Part 5 常考詞性辨析，考生應注意空格處若修飾動詞且強調動作發生的時間狀態，應優先選擇副詞型態 suddenly 而非形容詞 sudden。"]}],"g6-p1-p2:adverb:11:yet":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:11217:yet","word":"yet","partOfSpeech":["adverb","conjunction"],"chineseMeaning":"至今；還；尚未；仍然；但是；然而","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adverb","forms":["yet"]},{"partOfSpeech":"conjunction","forms":["yet"]}],"examples":[{"english":"Has the new software update been released yet?","chinese":"新的軟體更新發布了嗎？"},{"english":"She was tired, yet she continued to work on the presentation.","chinese":"她很累，但她仍然繼續製作簡報。"}],"examTips":["否定與疑問句中的基本用法：在 TOEIC 聽力與閱讀中，yet 常出現在句尾，於否定句中表示「尚未」，於疑問句中表示「已經...了嗎」。例如：The shipment has not arrived yet.","高頻考點 have yet to 結構：這是 TOEIC 最愛考的文法點之一，have yet to + 原形動詞 等同於 have not yet + 過去分詞，表示「尚未做某事」。例如：We have yet to confirm the schedule.","作為轉折連接詞：yet 可作為等立連接詞使用，意思等同於 but 或 nevertheless，表示「然而」。在閱讀測驗長難句中若看到 yet 連接兩個句子，需注意語氣的轉折。","與最高級連用表示「迄今為止」：常用於 the + 最高級 + yet 結構，如 our most ambitious project yet，表示到目前為止最野心勃勃的計畫。","易混淆詞辨析：在 Part 5 詞彙題中，需區分 yet（通常用於否定）、already（通常用於肯定）與 still（強調動作持續）。若空格位於否定句句尾，yet 通常是首選答案。"]}],"g6-p1-p2:occupation:1:baker":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00828:baker","word":"baker","partOfSpeech":["noun"],"chineseMeaning":"麵包師傅；烘焙師","categoryZh":"住宿與餐飲","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["baker","bakers"]}],"examples":[{"english":"The hotel is looking for a skilled baker to create fresh pastries for breakfast.","chinese":"飯店正在尋找一位熟練的麵包師傅，為早餐製作新鮮的糕點。"},{"english":"Our bakery's baker specializes in sourdough bread and custom cakes.","chinese":"我們麵包店的麵包師傅專門製作酸種麵包和客製化蛋糕。"}],"examTips":["職業與場所區分：在TOEIC第一部分(Part 1)照片描述題中，常出現 baker（麵包師）與 bakery（麵包店）的區分。注意圖片中是強調「人」的動作，還是「場地」的佈置。","常見搭配詞與場景：常出現於 local baker (當地麵包師) 或 head baker (主廚麵包師)。在 Part 7 閱讀測驗中，常以小型企業店主或供應商身分出現在商業書信或廣告中。","相似職位辨析：雖然與 chef (主廚) 或 pastry chef (西點師) 相關，但 baker 專指製作麵包或烘焙製品。聽力中若出現 knead dough (揉麵糰)、oven (烤箱) 或 fresh bread 等關鍵字，即是與此職業高度相關的線索。","考試重點：在招聘廣告 (Job Posting) 中，針對 baker 的職缺常會強調 certificates (證照) 與 previous experience (過往經驗)，考生需注意徵才條件。"]}],"g6-p1-p2:occupation:2:writer":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:11194:writer","word":"writer","partOfSpeech":["noun"],"chineseMeaning":"撰稿人；作家，通常指專業的寫作者或記者。","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["writer","writers"]}],"examples":[{"english":"Our company is seeking a skilled writer to create engaging marketing content.","chinese":"我們公司正在尋找一位技巧嫻熟的撰稿人，以創建引人入勝的行銷內容。"},{"english":"The writer spent weeks researching the topic before drafting the report.","chinese":"撰稿人在撰寫報告之前花了幾週的時間研究這個主題。"}],"examTips":["常見搭配詞：在TOEIC中常出現 'freelance writer' (特約作家/自由撰稿人)、'technical writer' (技術文件撰寫員) 或 'staff writer' (正職編輯)，考生需熟悉這些職位描述。","商業情境應用：通常出現在招聘廣告、合約簽署或出版業相關的文章中。例如在應徵內容創作職位時，常提及寫作經驗與截止日期 (deadlines) 的控管。","易混淆詞辨析：需區分 'writer' (通稱寫作者)、'author' (通常指已出版書籍的作者/創始者) 以及 'editor' (負責校對與修改內容的編輯)，在閱讀測驗中需從上下文判斷該角色的職責。","聽力與閱讀考點：常出現在多重選擇題中，詢問某篇信件或文章的作者職務為何。注意關鍵字如 'manuscript' (手稿)、'publish' (出版) 或 'article' (文章) 來判定身份。","答題注意事項：雖然 'writer' 是基礎單字，但在TOEIC中可能與其工作成果（如 'proposals', 'reports', 'manuals'）連結，答題時應注意動詞的搭配，如 'drafting a report' (草擬報告) 而非僅限於文學創作。"]}],"g6-p1-p2:occupation:3:worker":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:11158:worker","word":"worker","partOfSpeech":["noun"],"chineseMeaning":"勞工；工作人員；從事特定工作的人","categoryZh":"人力資源","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["worker","workers"]}],"examples":[{"english":"The company is looking for skilled workers to fill the vacant positions in the factory.","chinese":"該公司正在尋找熟練的勞工來填補工廠的空缺職位。"},{"english":"The management team needs to ensure the workers' safety and well-being.","chinese":"管理團隊需要確保勞工的安全和福祉。"}],"examTips":["常見搭配詞：在 TOEIC 中常出現 blue-collar worker (藍領工人)、white-collar worker (白領員工)、co-worker (同事) 以及 temporary worker (臨時工) 等組合。","商業情境應用：常用於人力資源 (HR) 招募、工廠安全準則或勞資關係討論。例如：'The company is hiring more part-time workers to handle the seasonal demand.'","易混淆詞辨析：worker 泛指所有勞動者，特別是基層或體力勞動者；employee 則是指受雇於公司的「雇員」，語氣較正式。此外，請注意 staff 為集合名詞，代表全體員工，不可用 a staff 形容個人，應使用 a staff member 或 a worker。","聽力與閱讀考點：在第一部分 (Photographs) 常用來描述工地或辦公室的人員動作；在第七部分 (Reading) 則常出現在 union (工會) 或 labor safety (勞工安全) 的公告中。","答題注意事項：當題目出現 colleague (同事) 時，可視為 co-worker 的同義詞替換。注意單複數形式，並留意 worker 與 working (工作中的) 或 workplace (職場) 在詞性上的區別。"]}],"g6-p1-p2:occupation:4:singer":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09238:singer","word":"singer","partOfSpeech":["noun"],"chineseMeaning":"歌手；演唱者，通常指專業的音樂表演者。","categoryZh":"溝通互動","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["singer","singers"]}],"examples":[{"english":"Our company is looking for a singer to endorse our new beverage.","chinese":"我們公司正在尋找一位歌手來代言我們的最新飲料。"},{"english":"The singer's performance at the corporate event was a huge success, boosting employee morale.","chinese":"這位歌手在公司活動中的表演非常成功，提升了員工士氣。"}],"examTips":["常見搭配詞：lead singer (主唱)、backup singer (和聲歌手)、professional singer (職業歌手)。","商業情境：在 TOEIC 中常出現於活動策劃（event planning）情境，例如公司週年慶、尾牙或宣傳活動中聘請表演者。","易混淆詞辨析：需區分 singer 與 vocalist，後者通常較正式且多指古典或爵士樂歌手；另需注意與 sign (簽名) 的發音差異，避免聽力測驗誤判。","聽力與閱讀考點：在 Part 1 照片描述題中，常考對著麥克風（microphone）或在舞台（stage）上表演的動作；在 Part 3/4 則常涉及演唱會門票銷售或藝人經紀合約。","答題注意事項：注意 singer 常與 perform (表演)、rehearse (排練) 及 release an album (發行專輯) 等詞組連動，在填空題中需根據動詞推斷受詞身分。"]}],"g6-p1-p2:occupation:5:pilot":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:07440:pilot","word":"pilot","partOfSpeech":["noun","verb"],"chineseMeaning":"飛行員；駕駛員（通常指飛機或船舶的駕駛員）","categoryZh":"旅遊與交通","starRating":4,"toeicScoreRange":"600-780","wordForms":[{"partOfSpeech":"noun","forms":["pilot","pilots"]},{"partOfSpeech":"verb","forms":["pilot","pilots","piloting","piloted"]}],"examples":[{"english":"The airline requires all pilots to undergo regular safety training.","chinese":"航空公司要求所有飛行員定期接受安全培訓。"},{"english":"The company is looking for experienced pilots to operate its new fleet of cargo planes.","chinese":"公司正在尋找有經驗的飛行員來操作其新的貨機隊。"}],"examTips":["常見搭配詞：多益考試中最常出現 'pilot project' (試驗性計畫)、'pilot program' (試行方案) 或 'pilot study' (初步研究)，表示在大規模實施前的測試。","商業情境用法：除了名詞指『飛行員』外，在多益中更常作為形容詞或動詞，指在正式推出產品或制度前的『試辦』或『小規模測試』。","易混淆詞與辨析：注意與 'pirate' (海盜/盜版) 的發音差異；在字義上，與 'initial' (最初的) 或 'experimental' (實驗性的) 常作為同義詞代換。","考試考點：在閱讀 Part 7 的公司內部公告中，若提到將在某分部先行試辦某套新軟體，常會使用 'piloting a new system'，答題時需將其理解為『測試階段』而非『駕駛系統』。","答題注意事項：若在聽力中聽到此單字，應快速從上下文判斷是關於『航空交通』還是『計畫啟動』，避免被單一字義誤導。"]}],"g6-p1-p2:occupation:6:doctor":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03082:doctor","word":"doctor","partOfSpeech":["noun"],"chineseMeaning":"醫生；醫療專業人員","categoryZh":"人力資源","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["doctor","doctors"]}],"examples":[{"english":"The company provides comprehensive health insurance, including coverage for doctors' visits.","chinese":"公司提供全面的健康保險，包括就診醫生的費用。"},{"english":"To ensure employee well-being, we offer on-site medical doctors for routine check-ups.","chinese":"為了確保員工的健康，我們提供現場醫生進行例行檢查。"}],"examTips":["常見搭配詞：'doctor's appointment' (預約看診) 與 'doctor's note' (醫生證明)。在多益閱讀 Part 7 中，醫生證明常作為請病假 (sick leave) 的必要憑證，是商務辦公情境的高頻單字。","商業情境應用：'doctor' 常出現在公司福利相關考題，如醫療保險 (health insurance) 或醫療支出報銷 (medical reimbursement)。考生需熟悉在員工手冊或通知中關於看病相關的行政程序。","同義詞辨析：'physician' 是 'doctor' 在多益中最常見的同義替換詞，題目中若出現 'doctor'，選項中常會以 'physician' 或 'medical professional' 作為轉述。","易混淆詞與職稱：在多益中需區分一般家醫 (General Practitioner, GP) 與專科醫生 (Specialist)，例如 'surgeon' (外科醫生)。此外，注意 'Dr.' 縮寫後接姓氏在信件或對話中的正式稱呼用法。","聽力考點轉述：在 Part 3 對話中，若聽到 'I have to see a doctor'，正確選項通常會改寫為 'visit a clinic' 或 'seek medical attention'，需具備同義替換的敏感度。"]}],"g6-p1-p2:occupation:7:farmer":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03811:farmer","word":"farmer","partOfSpeech":["noun"],"chineseMeaning":"農夫；農民","categoryZh":"一般專業","starRating":3,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["farmer","farmers"]}],"examples":[{"english":"The farmer harvested his crops early this morning.","chinese":"這位農夫今天一大早就收割了他的莊稼。"},{"english":"Many farmers are concerned about climate change's impact on their yields.","chinese":"許多農民擔心氣候變遷對他們的收成造成的影響。"}],"examTips":["常見搭配詞與情境：在 TOEIC 考試中，「farmer」最常出現在「farmer's market」（農夫市集）情境，通常與「local produce」（在地農產品）、「organic」（有機的）及「freshly harvested」（現採的）等詞連用。","聽力第一部分（照片描述）：此單字常出現在描述田園或戶外工作的照片中。考生應注意動作詞，如「harvesting crops」（採收作物）、「tilling the soil」（耕地）或「loading crates」（裝載板條箱）。","易混淆詞辨析：需區分「farmer」（經營農場的人）與「gardener」（園丁/處理花圃的人）及「rancher」（牧場主人）。此外，發音上需注意不要與「firm」（公司/堅固的）混淆，尤其是在聽力測驗語速較快時。","閱讀測驗考點：在 Part 7 的短文中，常出現在關於地方活動、社區支持農業（CSA）或供應鏈管理的文章。考生應熟悉相關動作動詞，如「plant」（種植）、「cultivate」（耕作）與「distribute」（分銷）。","答題注意事項：在聽力題中，如果聽到「farmer」，選項中常會出現與農業工具（tools）、拖拉機（tractor）或穀倉（barn）相關的視覺線索，若照片中沒有這些元素，需謹慎選擇該選項。"]}],"g6-p1-p2:occupation:8:actor":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00136:actor","word":"actor","partOfSpeech":["noun"],"chineseMeaning":"演員；表演者（通常指電影、電視或舞台上的）","categoryZh":"行銷與銷售","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["actor","actors"]}],"examples":[{"english":"The company hired a well-known actor to endorse their new product.","chinese":"該公司聘請了一位知名的演員來代言他們的新產品。"},{"english":"The actor's performance in the commercial significantly boosted sales.","chinese":"這位演員在廣告中的表現顯著提升了銷售額。"}],"examTips":["常見搭配詞：包含 'voice actor' (配音員)、'lead actor' (主角)、'supporting actor' (配角)，常出現在娛樂產業相關的廣播或報導中。","易混淆詞辨析：'actor' 指演員（現代英語中常作為中性詞），而 'actress' 特指女演員；需注意 'cast' 為集合名詞，指全體演員。","聽力考點：在 TOEIC 聽力第三或四部分中，常出現在電影節公告、舞台劇宣傳或演員訪談的情境，需注意其提到的作品名稱或演出時間。","商業延伸意：在較難的閱讀文章中，'actor' 可能指「參與者」或「行動者」（如 economic actors 指經濟參與者），而不僅限於演藝人員。","答題注意事項：Part 1 照片題若出現表演情境，應注意人物動作（如 performing, bowing）與 actor 的關聯性，若選項提到 'cast' 則需確認是否指涉一整群人。"]}],"g6-p1-p2:occupation:9:actress":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00137:actress","word":"actress","partOfSpeech":["noun"],"chineseMeaning":"女演員；表演電影、電視或舞台的女性。","categoryZh":"行銷與銷售","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["actress","actresses"]}],"examples":[{"english":"The company hired a famous actress to endorse their new product line.","chinese":"該公司聘請了一位知名女演員來代言他們的新產品線。"},{"english":"The actress delivered a captivating performance at the film festival, drawing significant media attention.","chinese":"這位女演員在電影節上奉獻了一場引人入勝的表演，引起了媒體的廣泛關注。"}],"examTips":["常見搭配詞：'award-winning actress' (獲獎女演員)、'lead actress' (女主角)、'supporting actress' (女配角) 以及 'aspiring actress' (有志成為女演員者)。","考試情境：在多益聽力第一部分的圖片描述題中，常出現在表演、拍攝或舞台場景；在閱讀測驗中則常出現在電影節公告、劇院節目表或名人代言的產品宣傳稿中。","詞義辨析：雖然現代英語趨向使用中性的 'actor' 來統稱男女演員，但在多益考試的正式書面語或特定獎項描述中，'actress' 仍被明確用來指女性演員。","職務區分：需辨別影視產業中的相關角色，如 'director' (導演)、'producer' (製片) 與 'scriptwriter' (編劇)，考題常藉此測試考生對對話背景或文章主角身分的理解。","聽力干擾項注意：聽力測驗中需注意字音相近的單字，例如 'actress' 與 'address' (地址/演說) 或 'access' (途徑/進入)，應根據上下文語境判斷正確含義避免誤選。"]}],"g6-p1-p2:occupation:10:artist":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00600:artist","word":"artist","partOfSpeech":["noun"],"chineseMeaning":"藝術家；以繪畫、雕塑或其他藝術形式從事創作的人。","categoryZh":"行銷與銷售","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["artist","artists"]}],"examples":[{"english":"The company hired an artist to create a unique logo for their new product line.","chinese":"該公司聘請了一位藝術家為他們的新產品線設計一個獨特的標誌。"},{"english":"The gallery is showcasing the works of several emerging artists.","chinese":"畫廊正在展示幾位新晉藝術家的作品。"}],"examTips":["常見搭配詞與職業：在多益考試中，artist 常與專業領域結合，例如「graphic artist」(平面設計師)、「makeup artist」(化妝師) 或「local artist」(當地藝術家)，多出現在與行銷或社區活動相關的閱讀測驗中。","商業情境應用：此單字常出現在飯店、藝廊或商業活動的宣傳文宣中，如「commissioning an artist」(委託藝術家創作) 或是提及公司辦公室的裝潢(office decor)。","易混淆詞辨析：考生需區分 artist (藝術家/創作者) 與 artisan (工匠/手工藝人)，前者強調創意，後者強調實用技術。此外，也要區分 artistic (形容詞，有藝術天分的) 與 artificial (形容詞，人造的)。","聽力考點：在 Part 1 照片描述題中，若圖片出現畫架或正在創作的人，artist 為常考選項。在 Part 3 簡短對話中，可能涉及討論展覽開幕(exhibition opening)或聘請專業設計師。","答題注意事項：注意字尾 -ist 通常代表「人」，在詞性找補題中，若句意是指稱「職業角色」，應優先考慮 artist 而非抽象名詞 art (藝術)。"]}],"g6-p1-p2:occupation:11:chef":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01684:chef","word":"chef","partOfSpeech":["noun"],"chineseMeaning":"主廚；烹飪師傅","categoryZh":"住宿與餐飲","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["chef","chefs"]}],"examples":[{"english":"The hotel is looking for an experienced chef to manage the kitchen.","chinese":"這家飯店正在尋找一位有經驗的主廚來管理廚房。"},{"english":"Our restaurant's chef specializes in authentic Italian cuisine.","chinese":"我們餐廳的主廚擅長製作道地的義大利料理。"}],"examTips":["常見搭配詞與專業職稱：在 TOEIC 中常出現 'executive chef' (行政主廚)、'sous chef' (副主廚) 或 'pastry chef' (點心主廚)。看到這些搭配詞時，通常與餐飲管理或飯店營運情境相關。","易混淆詞辨析：需區分 'chef' 與 'cook'，前者強調受過專業訓練的「主廚」，後者則是泛稱「廚師」；另外需注意拼寫相近的 'chief' (首領/主管)，在聽力測驗中兩者發音極為相似，必須透過上下文（如有無提到廚房或餐點）來判斷。","典型商務情境：常出現在 Part 7 的餐廳評論、主廚更換公告 (personnel changes) 或飯店餐飲部的會議記錄中。","聽力照片描述考點：在 Part 1 中，若圖片顯示有人在廚房穿著白色制服、戴廚師帽操作廚具，正確選項常包含 'chef' 或 'preparing food'。","相關詞彙延伸：掌握與 'chef' 同時出現的高頻字，如 'culinary' (烹飪的)、'recipe' (食譜)、'catering' (餐飲外燴) 與 'hospitality industry' (服務業/飯店業)。"]}],"g6-p1-p2:occupation:12:dentist":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02729:dentist","word":"dentist","partOfSpeech":["noun"],"chineseMeaning":"牙醫；牙科醫生","categoryZh":"人力資源","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["dentist","dentists"]}],"examples":[{"english":"The company offers comprehensive health insurance, including dental coverage and regular visits to the dentist.","chinese":"公司提供全面的健康保險，包括牙科保險和定期拜訪牙醫。"},{"english":"To maintain employee well-being, we encourage all staff to schedule a check-up with the dentist annually.","chinese":"為了維護員工的健康，我們鼓勵所有員工每年安排一次牙醫檢查。"}],"examTips":["常見搭配詞組：常用 'make/schedule an appointment with a dentist' 表示預約牙醫，或使用 'dental check-up' 表示牙齒檢查。在保險討論中常出現 'dental insurance coverage' (牙醫保險給付範圍)。","聽力測驗考點：在 Part 1 圖片描述中，常見牙醫正在 'examine a patient' (檢查病人) 或病人 'leaning back in a chair' (往後靠在椅子上)。在 Part 3 對話中，主題通常圍繞在 'reschedule an appointment' (重新安排預約) 或因為 'toothache' (牙痛) 需要請假。","易混淆詞辨析：'dentist' 是職業名詞，形容詞為 'dental' (如 dental clinic 牙醫診所)，學科則為 'dentistry' (牙醫學)。注意不要與一般內科醫生 'physician' 混淆，多考點在於其專業技術的特定性。","商業與生活情境：在 TOEIC 中，這類單字常出現在福利制度 (Employee Benefits) 的閱讀篇章中，提到公司提供醫療與牙醫保險。","答題注意事項：當聽到或看到 'dentist' 時，預期對話內容可能包含診療時間、醫療費用或診所地點的變更。"]}],"g6-p1-p2:occupation:13:driver":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03185:driver","word":"driver","partOfSpeech":["noun","verb"],"chineseMeaning":"駕駛員；（電腦）驅動程式","categoryZh":"旅遊與交通","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["driver","drivers"]},{"partOfSpeech":"verb","forms":["driver","drives","driving","drove","driven"]}],"examples":[{"english":"The company is looking for experienced truck drivers to handle long-distance deliveries.","chinese":"公司正在尋找有經驗的卡車司機來處理長途運輸。"},{"english":"Please ensure the driver has a valid license and insurance before dispatching the vehicle.","chinese":"在調派車輛之前，請確保司機持有有效的駕照和保險。"}],"examTips":["商業含義擴展：在多益閱讀中除了表示「司機」，常指「驅動力」或「關鍵因素」，如「economic drivers」（經濟驅動力）或「key driver of growth」（增長的主要動力）。","常見搭配詞：在交通與物流情境中，常出現「delivery driver」（送貨司機）、「driver's license」（駕照）以及「designated driver」（指定駕駛）。","易混淆辨析：聽力中需注意「driver」與「dryer」（烘乾機）的發音區別；在職業稱呼上，與「chauffeur」（私人司機）相比，「driver」較為通用且常見於多益各類情境。","考試情境重點：聽力第一部分（照片描述）常出現司機正在裝載貨物或操作車輛的場景；閱讀部分則常出現在徵人廣告中，強調應徵者需具備良好的「driving record」（駕駛紀錄）。","答題注意事項：若在分析報告類文章中看到此詞，應優先聯想其「因素/動力」的抽象意義，而非具體的人員，以確保正確理解商業邏輯。"]}],"g6-p1-p2:occupation:14:firefighter":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03943:firefighter","word":"firefighter","partOfSpeech":["noun"],"chineseMeaning":"消防員","categoryZh":"一般專業","starRating":2,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["firefighters"]}],"examples":[{"english":"The brave firefighter rescued the child from the burning building.","chinese":"勇敢的消防員從燃燒的建築物中救出了孩子。"},{"english":"Firefighters work long hours and face dangerous situations regularly.","chinese":"消防員工作時間長，並經常面臨危險情況。"}],"examTips":["常見搭配詞：常與 'put out a fire' (滅火)、'extinguish' (撲滅) 或 'emergency services' (緊急服務) 連用。","聽力第1部分考點：常出現在照片描述中，考生應留意圖中人物是否穿著 'uniform' (制服)、戴著 'helmet' (頭盔) 或操作 'hose' (水管)。","易混淆詞辨析：需區分 firefighter 與 paramedic (急救人員)，前者核心職責是滅火，後者則是現場醫療救護，TOEIC 有時會在聽力選項中以不同職稱干擾考生。","商業情境應用：此單字常出現在 'fire safety drill' (消防演習) 或 'evacuation procedure' (疏散程序) 的公司內部公告中，背景通常是辦公大樓的公安檢查。","聽力答題重點：在 Part 3 或 Part 4 的對話與短文裡，若聽到 'smoke' (煙)、'alarm' (警報) 或 'hydrant' (消防栓)，應立即聯想到與 firefighter 相關的緊急應變場景。"]}],"g6-p1-p2:occupation:15:librarian":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:05787:librarian","word":"librarian","partOfSpeech":["noun"],"chineseMeaning":"圖書館員；負責管理圖書館資源並提供資訊服務的專業人員。","categoryZh":"辦公日常","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["librarian","librarians"]}],"examples":[{"english":"The company is looking for a librarian to manage the corporate library and assist employees with research.","chinese":"公司正在尋找一位圖書館員來管理公司圖書館並協助員工進行研究。"},{"english":"Could you ask the librarian for assistance in locating relevant industry reports?","chinese":"您可以請圖書館員協助您找到相關的產業報告嗎？"}],"examTips":["常見搭配詞：'head librarian' (圖書館長)、'reference librarian' (參考諮詢館員) 以及 'consult the librarian' (諮詢圖書館員)。","易混淆詞：注意 'library' (圖書館) 與 'librarian' (圖書館員) 的差異，前者為地點，後者為職業人稱。","出題重點：常出現在 Part 1 照片題，動作可能包括 'stacking books' (堆疊書籍) 或 'organizing shelves' (整理書架)。","相關場景：常伴隨 'circulation desk' (借還書櫃台)、'overdue fines' (逾期罰金) 或 'due date' (到期日) 等單字出現。","聽力關鍵：字尾 -ian 代表職業，在 Part 2 針對 'Who' 類型的提問時，librarian 是常見的職稱答案選項。"]}],"g6-p1-p2:occupation:16:nurse":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06753:nurse","word":"nurse","partOfSpeech":["noun"],"chineseMeaning":"護士；負責照護病患的醫療人員","categoryZh":"人力資源","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["nurse","nurses"]}],"examples":[{"english":"The company is seeking experienced nurses to fill positions in the new hospital wing.","chinese":"公司正在尋找有經驗的護士來填補新醫院翼的職位。"},{"english":"The nurse administered the medication to the patient according to the doctor's instructions.","chinese":"護士按照醫生的指示給病人服用藥物。"}],"examTips":["名詞與動詞雙重身分：在 TOEIC 中最常用作名詞表示「護理師」，但要注意動詞用法意為「照料」或「看顧」，在 Part 7 的長篇文章中若提到照顧病患或老人的情境時常會出現。","職場相關搭配詞：常見搭配包含「head nurse (護理長)」、「registered nurse (RN, 註冊護理師)」以及「nursing staff (護理人員)」。在公司福利或健康保險的情境中，「occupational health nurse (職場護理師)」是常見職位。","易混淆詞辨析：必須區分「nurse (護理師)」與「nursery (托兒所/苗圃)」。TOEIC 閱讀測驗中，nursery 常出現在幼教或園藝相關的廣告中，若將其誤認為 nurse 會導致理解偏差。","典型考試情境：常出現在 Part 3 與 Part 4 的對話或廣播中，情境多為醫院預約 (appointments)、身體檢查 (check-ups) 或醫療理賠。考生應熟悉相關字彙如 physician (醫師)、clinic (診所) 與 prescription (處方箋)。","照片描述題 (Part 1) 注意事項：若照片中出現醫療場景，應注意 nurse 正在執行的動作，例如「checking a patient's pulse (測量脈搏)」或「writing on a chart (在病歷表上記錄)」。"]}],"g6-p1-p2:occupation:17:scientist":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08896:scientist","word":"scientist","partOfSpeech":["noun"],"chineseMeaning":"科學家；研究人員，通常指從事科學研究或實驗的人。","categoryZh":"科技與技術支援","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["scientist","scientists"]}],"examples":[{"english":"Our company employs several scientists to develop innovative solutions for our clients.","chinese":"我們公司僱用多位科學家，為客戶開發創新的解決方案。"},{"english":"The scientist presented her research findings at the international conference.","chinese":"這位科學家在國際會議上發表了她的研究成果。"}],"examTips":["常見搭配詞：常與形容詞連用形成特定職稱，如 research scientist (研究科學家)、environmental scientist (環境科學家) 或 leading scientist (頂尖科學家)。","詞性辨析：在 Part 5 詞彙題中，需區分名詞 scientist (人)、science (學科) 與形容詞 scientific (科學的)，通常空格前有形容詞或動詞時需選名詞。","出題情境：常用於 R&D (研發部) 相關聽力或閱讀文本，討論新產品開發、實驗結果或醫療技術突破。","字尾識別：字尾 -ist 代表「專家」或「從事者」，類似單字如 specialist (專家)、receptionist (接待員)，有助於快速判斷人稱。","混淆詞：注意與 science (學科) 的差異，scientist 是指執行科學研究的人，在句子結構中常作為主詞執行動作 (例如：Scientists conduct experiments)。"]}],"g6-p1-p2:occupation:18:dancer":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02551:dancer","word":"dancer","partOfSpeech":["noun"],"chineseMeaning":"舞者，舞蹈家","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["dancers"]}],"examples":[{"english":"The lead dancer captivated the audience with her elegant moves.","chinese":"首席舞者以她優雅的舞步吸引了觀眾。"},{"english":"She has been a professional dancer for over ten years.","chinese":"她已經是一名專業舞者超過十年了。"}],"examTips":["常見搭配詞組：在 TOEIC 中常出現 professional dancer（職業舞者）、backup dancer（伴舞）、lead dancer（領舞）等組合，多用於描述藝文演出。","情境應用：常出現在第一部分照片描述題（例如描述一個人在舞台上跳舞）或第七部分的活動公告、宣傳海報及演藝新聞中。","易混淆詞辨析：需區分 dancer（指執行舞蹈動作的人）與 dance（指跳舞的動作或舞會）以及 dancing（指舞蹈藝術或行為），在填空題中需注意詞性選擇。","聽力考點：在聽力測驗中，要注意 dancer 與 danger 或 dinner 的發音差異，雖然語境通常明顯，但在快速發音下仍需仔細辨認。","商業連結：在多益的商業情境中，此字常與 entertainment industry（娛樂產業）、event planning（活動策劃）或 performance contract（演出合約）相關聯。"]}],"g6-p1-p2:conjunction:3:because":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00985:because","word":"because","partOfSpeech":["conjunction"],"chineseMeaning":"因為；由於","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"conjunction","forms":["because"]}],"examples":[{"english":"I couldn't attend the meeting because I had a prior engagement.","chinese":"我無法出席會議，因為我已有先前的約會。"},{"english":"We need to finish this report by Friday because the deadline is approaching.","chinese":"我們需要在週五前完成這份報告，因為截止日期快到了。"}],"examTips":["語法結構辨析：'because' 為連接詞，其後必須接完整的子句（主詞+動詞）；而在 TOEIC Part 5 中常考其與 'because of' (介係詞) 的區別，後者只能接名詞、代名詞或動名詞。","商業書信代換：在正式商業情境中，'because' 常與 'since' 或 'as' 互換，均表示已知的原因。另外，'due to the fact that' 也是書信中常見的更正式表達方式。","聽力 Part 2 技巧：針對 'Why' 開頭的問句，'Because' 是最直接的回答標誌，但要注意近年來考試趨勢常會省略 'Because' 而直接說明理由，考生需專注聽取後續內容。","閱讀 Part 7 定位：當題目詢問動機或原因（如：Why is the event being rescheduled?）時，'because' 是一個關鍵的定位字，能幫助考生快速找到文章中解釋決策背景的段落。","邏輯連貫注意：需區分原因連接詞 'because' 與結果連接詞 'therefore' 或 'so' 的邏輯差異，避免在克漏字中選錯邏輯方向。"]}],"g6-p1-p2:conjunction:7:while":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:11055:while","word":"while","partOfSpeech":["conjunction","noun","verb"],"chineseMeaning":"在...期間；當...時候；然而，儘管；與此同時；一會兒，一段時間；消磨時間","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"conjunction","forms":["while"]},{"partOfSpeech":"noun","forms":["while"]},{"partOfSpeech":"verb","forms":["while","whiles","whiled","whiling"]}],"examples":[{"english":"While the manager was reviewing the proposal, the team was preparing the presentation.","chinese":"當經理審核提案時，團隊正在準備簡報。"},{"english":"We need to wait for a while before the system restarts.","chinese":"我們需要等一會兒，系統才會重啟。"}],"examTips":["詞性與結構辨析：while 為連接詞，後方必須接包含主詞與動詞的子句，常在 Part 5 中與介系詞 during (後接名詞) 進行對比考查。","分詞句型縮減：多益閱讀中常見「while + V-ing」結構（如 While reviewing the files），此為省略主詞與 be 動詞的用法，考生需能識別其主動含義。","語意轉折考點：除了表達「當...之時」的同步性，while 也常作為「雖然」(although) 或「然而」(whereas) 使用，用來連接兩個對比的商業數據或觀點。","常見搭配詞組：商務情境中常出現「while supplies last」（直到貨完為止）於促銷廣告中，或「worthwhile」（值得的）作為形容詞修飾投資或計畫。","聽力答題關鍵：在 Part 1 圖片題中，若選項描述兩人在同一場景同時進行不同動作，常會使用 while 連接，需仔細觀察圖片中主體與動作的對應是否準確。"]}],"g6-p1-p2:continents:1:world":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:11172:world","word":"world","partOfSpeech":["noun"],"chineseMeaning":"全球；世界各地；國際","categoryZh":"營運管理","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["world","worlds"]}],"examples":[{"english":"Our company aims to expand its operations into the global market.","chinese":"我們公司旨在將業務拓展到全球市場。"},{"english":"The conference brought together industry leaders from around the world.","chinese":"這次會議匯集了來自世界各地的業界領袖。"}],"examTips":["常見搭配詞與商業用法：在多益考試中，'world' 常見於 'around the world' (全世界) 或 'world-class' (世界級的/頂尖的)，後者常用來形容公司產品或服務的品質。","聽力辨析考點：在聽力測驗中，考生需特別注意 'world' 與 'word' (單字/話語) 的發音差異。'world' 結尾有顯著的 /ld/ 音，常出現在 Part 1 描述地點或 Part 3/4 的背景介紹中。","閱讀情境應用：多益閱讀常出現 'real-world' (現實世界的/實際的) 作為形容詞，例如 'real-world experience' (實務經驗)，在徵才廣告或個人履歷中是關鍵詞。","擴展商業詞彙：注意其衍生詞 'worldwide'，在 Part 7 的公司新聞稿中，常與 'expansion' (擴張) 連用，描述企業在全球市場的佈局。","答題注意事項：當題目出現 'global' 時，選項中常會用 'world' 或 'international' 進行同義換照 (Paraphrasing)，務必具備這種詞彙轉換的敏感度。"]}],"g6-p1-p2:continents:3:africa":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00246:africa","word":"africa","partOfSpeech":["noun"],"chineseMeaning":"非洲，指非洲大陸及其相關地區，在商務情境中常指代非洲市場或非洲地區的業務。","categoryZh":"行銷與銷售","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["africa","Africas"]}],"examples":[{"english":"Our company is exploring opportunities to expand its market share in Africa.","chinese":"我們公司正在探索在非洲擴大市場份額的機會。"},{"english":"The sales team needs to research the specific consumer preferences in Africa before launching the new product.","chinese":"在推出新產品之前，銷售團隊需要研究非洲的特定消費者偏好。"}],"examTips":["商業擴張背景：在多益考試中，Africa 常作為「新興市場 (emerging markets)」的代名詞，出現在關於企業全球擴張、設立海外分公司 (overseas branches) 或子公司 (subsidiaries) 的閱讀測驗中。","常見搭配詞：常見組合如「the African market」(非洲市場)、「expansion into Africa」(進軍非洲) 以及「South Africa」(南非，常作為具體的商務地點)。","詞性辨析：考生需清楚區分專有名詞 Africa (非洲) 與形容詞 African (非洲的、非洲人的)，在語法題 (Part 5) 中，若位於名詞前修飾，應使用形容詞形式。","聽力辨識：在聽力 Part 3 和 Part 4 中，Africa 常出現在物流運輸 (logistics) 或商務旅行 (business trips) 的情境裡，應注意其發音以快速定位資訊。","特定產業連結：非洲在多益考題中常與採礦業 (mining)、基礎建設 (infrastructure) 或電信業 (telecommunications) 相關的企業報告連結，掌握這些背景知識有助於預測文意。"]}],"g6-p1-p2:continents:4:asia":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00618:asia","word":"asia","partOfSpeech":["noun"],"chineseMeaning":"亞洲；亞洲地區","categoryZh":"行銷與銷售","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["asia","Asias"]}],"examples":[{"english":"Our company is expanding its market share in Asia, focusing on emerging economies.","chinese":"我們公司正在擴展在亞洲的市場份額，專注於新興經濟體。"},{"english":"The sales team needs to tailor its marketing strategies to suit the diverse cultures of Asia.","chinese":"銷售團隊需要調整其行銷策略以適應亞洲多樣的文化。"}],"examTips":["常見搭配詞：在多益中常以「Asia-Pacific region」(亞太地區)或「the Asian market」(亞洲市場)的形式出現，考生需辨識其縮寫「APAC」常代表此區域。","商業情境：此單字頻繁出現在有關「expansion」(擴張)、「global supply chain」(全球供應鏈)或「emerging markets」(新興市場)的報導或會議內容中。","易混淆詞辨析：注意形容詞「Asian」與名詞「Asia」的詞性差異，題目常考空格處應填入名詞作為受詞，還是形容詞修飾後方的名詞(如 Asian stock markets)。","聽力考點：在聽力第三、四部分，若提到「overseas office」(海外辦公室)，常會具體指名地點在 Asia 的某個城市(如 Singapore 或 Tokyo)，需具備基本的地理連結能力。","答題注意事項：當文章提到「pan-Asian」(全亞洲的)時，意指涵蓋整個亞洲範圍，通常出現在跨國企業的策略描述中，這是一個高階考點。"]}],"g6-p1-p2:continents:5:asian":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00619:asian","word":"asian","partOfSpeech":["noun","adjective"],"chineseMeaning":"亞洲人；亞洲的；亞洲風格的","categoryZh":"人力資源","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["asian","Asians"]},{"partOfSpeech":"adjective","forms":["asian","more Asian","most Asian"]}],"examples":[{"english":"The company is committed to building a diverse workforce, including a significant number of Asian employees.","chinese":"公司致力於建立多元化的人力資源，包括相當數量的亞洲員工。"},{"english":"The restaurant offers authentic Asian cuisine, appealing to a wide range of customers.","chinese":"這家餐廳提供正宗的亞洲美食，吸引了廣泛的顧客。"}],"examTips":["常見搭配詞組：在多益考試中，常用於描述市場或區域，例如 \"Asian markets\" (亞洲市場)、\"Asian branch\" (亞洲分部) 及 \"Asian headquarters\" (亞洲總部)。","商業情境運用：常用於國際貿易、企業全球擴張計畫，或討論亞太地區 (Asia-Pacific) 的經濟發展與物流策略。","易混淆詞辨析：注意 \"Asia\" (名詞) 與 \"Asian\" (形容詞) 的詞性變化。此外，多益閱讀常出現 \"ASEAN\" (東南亞國家協會) 或 \"APAC\" (亞太地區)，應具備基本的縮寫辨識能力。","考試出題重點：在多益閱讀第七部分的商業報導或公司公告中，常作為地理範圍的限定詞，用以說明該政策或分部所屬的區域。","答題注意事項：聽力或閱讀測驗常出現「改寫」技巧，例如文本提到具體國家名（如 China, Vietnam），選項中可能會以 \"Asian country\" 或 \"Asian region\" 作為同義替代詞。"]}],"g6-p1-p2:continents:6:europe":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03547:europe","word":"europe","partOfSpeech":["noun"],"chineseMeaning":"歐洲 (地區)，指位於歐亞大陸西部的地區，在商業情境中常指歐洲市場或歐洲國家。","categoryZh":"行銷與銷售","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["europe","Europes"]}],"examples":[{"english":"Our company is planning to expand its operations into the European market.","chinese":"我們公司計劃將業務拓展到歐洲市場。"},{"english":"The European Union has implemented new trade regulations.","chinese":"歐盟已實施新的貿易法規。"}],"examTips":["詞性辨析：多益考試中常區分 Europe (地名/名詞) 與 European (歐洲的/形容詞)。考生應注意 European 雖然以 E 開頭，但其發音起始音為子音 /j/，因此冠詞需使用 'a European company' 而非 'an'。","商業搭配詞：常見組合包含 European headquarters (歐洲總部)、European market (歐洲市場)、expand into Europe (向歐洲擴張) 以及 Europe-wide (全歐洲範圍的)。","聽力陷阱：Europe 的發音 /'jʊr.əp/ 開頭帶有 /j/ 音，在快速對話中若與前一個單字連讀需特別留意。","閱讀情境：在多益閱讀 Part 7 的公司簡介或新聞報導中，Europe 常與其主要商業中心如 London, Frankfurt, Paris 併用，作為說明跨國企業營運規模的關鍵詞。","相關組織：注意多益常考的 European Union (EU, 歐盟) 概念，通常與國際貿易規章、歐元 (Euro) 或跨國勞工政策相關。"]}],"g6-p1-p2:continents:7:america":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00384:america","word":"america","partOfSpeech":["noun"],"chineseMeaning":"美國（指美國聯邦政府或美國地區），在商務情境中通常指美國市場或美國公司。","categoryZh":"行銷與銷售","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["america","Americas"]}],"examples":[{"english":"Our company is expanding its operations into the Americas.","chinese":"我們公司正在將業務拓展到美洲市場。"},{"english":"The marketing campaign needs to be tailored to the American consumer.","chinese":"這個行銷活動需要針對美國消費者進行調整。"}],"examTips":["區域劃分與物流：在多益考試的運輸與物流情境中，America 常與 North, South 或 Central 連用。考生需注意聽力或閱讀中提到的具體區域，因為這通常涉及運費計算、交貨時間或區域辦公室的設置。","商業術語 Corporate America：此詞彙常出現在商業評論或新聞報導類型的閱讀題中，用來泛指美國大型企業的集合體或美國商業環境，理解此意象有助於掌握文章大意。","地理與市場範圍：常見搭配詞如 North American market (北美市場) 或 Latin America (拉丁美洲)，在分析市場擴張 (market expansion) 的題目中是重要的背景資訊。","形容詞辨析：注意 America (名詞) 與 American (形容詞) 的用法差異。在聽力測驗中，American branch (美國分公司) 或 American citizens (美國公民) 是常見的組合。","跨國公司情境：多益常考「總部與分部」關係，America 經常作為 North American headquarters (北美總部) 的所在地出現，需留意其與 European 或 Asian 辦公室的對照。"]}],"g6-p1-p2:country:1:france":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04161:france","word":"france","partOfSpeech":["noun"],"chineseMeaning":"法國，一個位於西歐的國家，在國際貿易和商業活動中經常被提及。","categoryZh":"旅遊與交通","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["france","Frances"]}],"examples":[{"english":"Our company is exploring potential partnerships with businesses in France.","chinese":"我們公司正在探索與法國企業建立合作夥伴關係。"},{"english":"The logistics team is coordinating shipments to France and Germany.","chinese":"物流團隊正在協調向法國和德國的貨物運輸。"}],"examTips":["詞性辨析與應用：France 為國家名詞，而 French 為形容詞（法國的）或名詞（法語、法國人）。在 TOEIC Part 5 文法題中，介系詞 in 之後應接 France (in France)，而修飾產品或分支機構時應選用 French (French subsidiary)。","常見商務搭配詞：在國際貿易與企業擴張情境中，常出現 'headquartered in France' (總部位於法國)、'expanding into France' (擴展至法國市場) 或 'export to France' (出口至法國) 等表達方式。","聽力場景考點：在 Part 1 至 Part 4 的聽力中，France 常出現在旅遊安排、商務出差或國際會議的對話中。考生需注意其發音，並與 IT、物流或市場調查等場景連結。","閱讀理解定位：在 Part 7 的商務信件、新聞稿或電子郵件中，France 常作為國際業務的地理背景，考生應快速辨識其為歐洲市場的代表，這有助於理解文章中提及的歐盟規則或歐元匯率影響。","易混淆點提醒：雖然 France 本身簡單，但在快速聽力中需注意不要將其與 sounds-like 詞彙混淆，且在填空時需確保首字母大寫，維持專有名詞的正確格式。"]}],"g6-p1-p2:country:2:germany":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04343:germany","word":"germany","partOfSpeech":["noun"],"chineseMeaning":"德國，一個位於歐洲的國家，在國際貿易和商業中扮演重要角色。","categoryZh":"辦公日常","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["germany","Germanys"]}],"examples":[{"english":"Our company is expanding its operations into Germany next quarter.","chinese":"我們公司下個季度將擴展業務至德國。"},{"english":"The import documents from Germany are currently being processed by customs.","chinese":"來自德國的進口文件目前正在由海關處理。"}],"examTips":["地理背景與聽力測驗：在聽力 Part 3 或 Part 4 中，Germany 常作為出差目的地、總部所在地或產品原產地出現。考生應留意與之連結的細節資訊，例如班機時間、會議日期或分公司位置。","詞性辨析：需嚴格區分 Germany (國家名詞) 與 German (德語、德國人的、德國的)。在 Part 5 語法題中，注意介係詞 in 或 from 之後通常接國名 Germany，而形容詞 German 則用於修飾產品或職稱，如 German engineer。","商業情境連結：Germany 常出現在製造業、汽車業或工程科技相關的商業文章中。若閱讀測驗提及該國，常涉及國際貿易、分公司擴張或展覽 (trade fairs) 等情境。","常用介係詞搭配：常見搭配如 'headquartered in Germany' (總部位於德國) 或 'a business trip to Germany' (去德國出差)，正確掌握介係詞用法可幫助快速選出閱讀題答案。","專有名詞識別：在聽力測驗中，Germany 作為專有名詞應快速被識別為地點，考生不應因其為專有名詞而感到困惑，應將注意力放在動詞或時間等關鍵字上。"]}],"g6-p1-p2:country:3:japan":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:05462:japan","word":"japan","partOfSpeech":["noun"],"chineseMeaning":"日本，一個位於東亞的國家，在國際貿易和商業活動中經常被提及。","categoryZh":"辦公日常","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["japan","japans"]}],"examples":[{"english":"Our company is exploring potential partnerships with businesses in Japan.","chinese":"我們公司正在探索與日本企業建立合作夥伴關係。"},{"english":"The logistics team is coordinating shipments to Japan and South Korea.","chinese":"物流團隊正在協調向日本和韓國的貨物運輸。"}],"examTips":["詞性辨析：在 Part 5 語法題中，需區分專有名詞 Japan 與形容詞 Japanese。例如，Japan 是國家名稱，而 Japanese 則指日本的或日本人、日語。常見複合名詞如 'Japan branch' (日本分公司) 與形容詞用法 'Japanese electronics' (日本電子產品)。","商業地理情境：在 Part 7 閱讀測驗中，Japan 常出現在跨國企業的背景介紹，與 'headquartered in' (總部位於)、'subsidiary' (子公司) 或 'regional office' (區域辦公室) 等詞彙搭配，用以說明企業的市場佈局。","聽力考點：在 Part 3 與 Part 4 中，Japan 常用於出差情境，搭配 'flight to'、'itinerary' (行程) 或 'business trip'。考生需留意其發音，並注意與其他類似發音的地名區隔。","物流與製造：在 TOEIC 常見的供應鏈場景中，常出現 'shipped from Japan' (從日本運送) 或 'imported from Japan' (自日本進口)，用於討論存貨 (inventory) 或交貨時間 (lead time)。","易混淆點：需注意 'Japan-based' (以日本為基地的) 是一個常見的複合形容詞，用來修飾公司，指該公司的主體位於日本，在閱讀測驗中看到此詞應立即聯想到該公司的國籍背景。"]}],"g6-p1-p2:country:4:india":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:05131:india","word":"india","partOfSpeech":["noun","adjective"],"chineseMeaning":"印度，一個位於南亞的國家，在國際貿易和商業活動中經常被提及。","categoryZh":"旅遊與交通","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["india","Indias"]},{"partOfSpeech":"adjective","forms":["india","more Indian","most Indian"]}],"examples":[{"english":"Our company is exploring new markets, with India being a key target for expansion.","chinese":"我們公司正在探索新市場，印度是我們擴張計劃中的關鍵目標。"},{"english":"The Indian subsidiary reported a significant increase in sales this quarter.","chinese":"印度子公司本季報告銷售額顯著增長。"}],"examTips":["地理情境與外包：在多益聽力或閱讀中，India 常與 IT 外包、軟體開發或客服中心 (BPO) 相關聯，考生應注意文中提到的技術轉移或遠端協作情境。","常見搭配詞：常出現在 \"based in India\" (總部/基地位於印度)、\"expansion into the Indian market\" (進軍印度市場) 或 \"Indian subsidiary\" (印度子公司) 等片語中。","詞性辨析：區分國家名稱 India (名詞) 與形容詞/國籍 Indian。聽力測驗中若聽到 \"Indian\"，選項中可能出現 \"India\" 作為干擾項。","城市聯想：多益考題偶爾會提及 Mumbai (孟買)、Bangalore (班加羅爾) 或 New Delhi (新德里)，看到這些城市名應立即聯想到 India，這對於判斷公司所在地或商務旅行目的地非常有幫助。","聽力陷阱：在 Part 1 或 Part 2 中，發音與 \"Indiana\" (美國印第安那州) 或 \"Indonesia\" (印尼) 相似，需根據上下文（如亞太地區或美國本土）來確認具體地點。"]}],"g6-p1-p2:country:8:china":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01707:china","word":"china","partOfSpeech":["noun"],"chineseMeaning":"指中國，或與中國相關的事物、文化或商業。","categoryZh":"辦公日常","starRating":2,"toeicScoreRange":"780-900","wordForms":[{"partOfSpeech":"noun","forms":["china","chinas"]}],"examples":[{"english":"Our company is expanding its operations into China.","chinese":"我們公司正在擴展業務至中國。"},{"english":"The import documents from China are currently being processed by customs.","chinese":"來自中國的進口文件目前正在由海關處理。"}],"examTips":["詞義辨析與大小寫：在 TOEIC 測驗中，小寫開頭的「china」主要指「瓷器」或「精緻餐具」，而非國家名稱。考生在閱讀 Part 7 廣告或 Part 1 圖片題時，應注意上下文情境是否與餐飲、家居用品或飯店設備相關。","常見搭配詞組：常用搭配包括「fine china」(高級瓷器)、「bone china」(骨瓷)、「china cabinet」(碗盤櫃) 以及「a piece of china」(一件瓷器)。這些詞組常出現在百貨公司促銷活動或餐飲業採購清單中。","商業應用情境：此單字常出現於「Hospitality」(餐旅業) 相關考題，例如討論餐廳裝潢、飯店房內設施或高端禮品的採購契約。在聽力測驗中，若聽到有關「fragile items」的運送，也可能提及瓷器。","易混淆詞與辨析：須區分「china」(瓷器)、「pottery」(陶器) 及「ceramics」(陶瓷)。china 通常指更為輕薄、半透明且高品質的產品；在多益中若看到桌上擺放精緻碗盤，描述句可能會使用「china」而非一般的「dishes」。","答題注意事項：在 Part 1 攝影描述題中，若圖片顯示餐桌擺設，選項中提及「The china is being arranged on the table」是常見的敘述方式，需熟悉此字作為餐具的非地理含義。"]}],"g6-p1-p2:country:9:canada":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01441:canada","word":"canada","partOfSpeech":["noun"],"chineseMeaning":"加拿大，一個位於北美洲的國家，以其豐富的自然資源和多元文化而聞名，在國際貿易和商業活動中經常被提及。","categoryZh":"旅遊與交通","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["canada","Canadas"]}],"examples":[{"english":"Our company is exploring potential partnerships with businesses in Canada.","chinese":"我們公司正在探索與加拿大企業建立合作夥伴關係。"},{"english":"The import duties for goods from Canada are outlined in the attached document.","chinese":"來自加拿大的貨品進口關稅的詳細資訊請參閱附件。"}],"examTips":["常用搭配詞與地理情境：在 TOEIC 考試中，「Canada」常出現在描述公司規模或國際業務的脈絡中，常見用法如「headquartered in Canada」（總部設於加拿大）、「the branch in Canada」（加拿大分公司）或「Canada-based company」（總部設於加拿大的公司）。","詞性辨析：考生需清楚區分專有名詞「Canada」（國家名）與其形容詞「Canadian」（加拿大的/加拿大人）。在 Part 5 語法題中，若空格後接名詞（如 company, employee），應選擇形容詞形式，例如「a Canadian firm」。","聽力測驗考點：在 Part 1 至 Part 4 的聽力題中，「Canada」常被提及為商務旅行（business trip）的目的地或物流貨運（shipping）的終點站，聽到時應迅速聯想其位於北美（North America）的地理位置。","商業背景應用：常出現在跨國合約、跨國連鎖零售或北美市場開發的閱讀題材中。例如提到「North American operations」時，通常指包含美國與加拿大的業務，這對於推論題（Inference questions）非常重要。","答題注意事項：注意 Canada 與相關地名（如 Toronto, Vancouver, Montreal）的關聯。若題目中出現這些城市名，即便沒有直接寫出 Canada，考生也應具備基本的地理常識以進行資訊整合。"]}],"g6-p1-p2:country:10:england":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03435:england","word":"england","partOfSpeech":["noun"],"chineseMeaning":"英格蘭，英國（通常指英格蘭地區，涵蓋政治、經濟、文化等面向）","categoryZh":"旅遊與交通","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["england","Englands"]}],"examples":[{"english":"Our company is expanding its operations into England to tap into the European market.","chinese":"我們公司正擴展業務至英格蘭，以進入歐洲市場。"},{"english":"The business traveler was impressed by the efficient public transportation system in England.","chinese":"這位商務旅客對英格蘭高效的公共交通系統印象深刻。"}],"examTips":["辨析地理與行政概念：在 TOEIC 閱讀中，需區分 England、Great Britain 與 United Kingdom (UK)。雖然在一般口語中常混用，但在正式的商務合約或物流文件中，England 指的是大不列顛島南部的特定區域，而非整個英國。","常見商務搭配詞：常與總部、分部或航點相關聯，如 'based in England' (總部位於英格蘭)、'shipped from England' (從英格蘭發貨) 或 'London, England' (地名後接行政區域)。","詞性與指代辨析：注意 England (名詞，國家/地區名) 與 English (形容詞/名詞，英格蘭的/英文/英國人) 的區別。在人才招募情境中，'English' 通常指語言能力要求，而非特定國籍。","聽力測驗關鍵字：在聽力測驗的第三或第四部分，若出現地名 England，通常是用來確立背景，幫助考生判斷接下來可能涉及的跨國商務差旅、時差計算或運輸物流細節。","易混淆概念：考生應注意 England 與其首都 London 的關係。多益常在題目中提到倫敦，若選項中出現 England 作為地點範圍，兩者具備從屬關係，需在作答時進行邏輯連結。"]}],"g6-p1-p2:country:12:country":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02366:country","word":"country","partOfSpeech":["noun"],"chineseMeaning":"國家；國民；鄉土；（公司）總部所在地","categoryZh":"營運管理","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["country","countries"]}],"examples":[{"english":"Our company is expanding its operations into several new countries.","chinese":"我們公司正在將業務拓展到幾個新的國家。"},{"english":"The headquarters of our multinational corporation is located in the United States.","chinese":"我們跨國公司的總部設在美國。"}],"examTips":["常見搭配詞組：包含「across the country」或「throughout the country」（全國各地）、「developing country」（發展中國家）及「host country」（主辦國），這些片語常出現在閱讀測驗的市場分析或公司公告中。","多義詞辨析：在 TOEIC 中，「country」除了解釋為「國家」，在聽力測驗第一部分的圖片描述題中，「the country」常指「鄉間」或「郊外」，與城市（city）情境形成對比。","商業應用情境：常涉及企業的國際化擴展，例如「expand operations into other countries」（將業務擴充至其他國家），需注意其與國際貿易、跨國物流相關的上下文。","易混淆詞：應小心與「county」（郡、縣）區分，後者通常指國家內部的行政區劃。此外，在描述國家主權時，有時會與「nation」互換，但在商務情境下「country」更為普遍。","考試注意點：在閱讀 Part 5 語法題中，注意「country」為可數名詞，複數形式為「countries」，而表示「鄉下」概念時通常會加上定冠詞「the country」。"]}],"g6-p1-p2:people-language:1:french":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04182:french","word":"french","partOfSpeech":["noun","adjective"],"chineseMeaning":"法語；與法國相關的（形容詞）","categoryZh":"溝通互動","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["french","French"]}],"examples":[{"english":"Our French-speaking sales representatives will attend the conference in Paris next month.","chinese":"我們會說法語的業務代表將於下個月參加在巴黎舉行的會議。"},{"english":"Please have the legal document translated into French for our European partners.","chinese":"請將法律文件翻譯成法語，以供我們的歐洲合作夥伴使用。"}],"examTips":["常見搭配詞：在多益中常出現於餐飲、旅遊或房地產情境，如 'French fries' (薯條)、'French cuisine' (法國料理) 與 'French doors' (法式雙開門)。","詞性與國名辨析：考生需區分名詞 'France' (法國) 與形容詞/名詞 'French' (法國的、法語、法國人)。在 Part 5 填空題中，若名詞前需要修飾語，應選 'French'。","商業情境：常與企業分部或市場相關聯，例如 'the French branch' (法國分部) 或 'French market trends' (法國市場趨勢)，代表特定地理區域的業務。","書寫規範：作為國籍或語言的形容詞，首字母 'F' 在任何情況下都必須大寫，這在 Part 6 及 Part 7 的書信閱讀中是辨識專有名詞的基礎。","聽力關鍵字：在聽力測驗關於餐廳預約或機場廣播的場景中，'French' 常作為分類標籤出現，需快速反應其代表的文化或地理屬性以利作答。"]}],"g6-p1-p2:people-language:3:indian":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:05132:indian","word":"indian","partOfSpeech":["adjective","noun"],"chineseMeaning":"源自印度或與印度相關的；印度人（複數）。在商務情境中，通常指來自印度的員工或客戶。","categoryZh":"人力資源","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["indian","more indian","most indian"]},{"partOfSpeech":"noun","forms":["indian","Indians"]}],"examples":[{"english":"The company is actively seeking Indian engineers with expertise in AI.","chinese":"公司正在積極尋找在 AI 領域具有專業知識的印度工程師。"},{"english":"We need to ensure our marketing campaign is culturally sensitive to Indian consumers.","chinese":"我們需要確保我們的行銷活動對印度消費者具有文化敏感性。"}],"examTips":["常見搭配詞與情境：在多益中常出現於餐飲（Indian cuisine/restaurant）或商務市場（Indian market/economy）情境中。","商務應用：隨著全球貿易增加，多益閱讀文章可能提及印度作為新興市場或資訊科技（IT outsourcing）的服務中心，考點常圍繞在區域性的商務擴張。","易混淆辨析：注意區分 Indian（印度人/印度的）與 Indiana（美國印第安納州），多益考試內容多數以地理位置或國籍為主，較少涉及美國原住民（Native American）的語境。","聽力考點：在聽力測驗的旅遊或社交場合中，常出現在詢問異國料理偏好或安排國際差旅的對話中。","答題建議：若出現在職位描述或公司背景，多半與跨國企業在亞洲的業務點（Subsidiary/Branch）相關，考生應根據上下文判斷其地理含義。"]}],"g6-p1-p2:people-language:4:japanese":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:05463:japanese","word":"japanese","partOfSpeech":["adjective","noun"],"chineseMeaning":"日本的；日本人的；日本語的","categoryZh":"溝通互動","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["japanese","more japanese","most japanese"]},{"partOfSpeech":"noun","forms":["japanese","Japanese"]}],"examples":[{"english":"The company is expanding its operations into the Japanese market.","chinese":"該公司正在擴展其業務到日本市場。"},{"english":"He is fluent in Japanese and English.","chinese":"他精通日語和英語。"}],"examTips":["詞性辨析：'Japan' 為名詞表示國家，而 'Japanese' 既是形容詞（日本的）也是名詞（日語、日本人），在文法題中須注意後方是否接續名詞。","常見商務搭配：'Japanese yen' (日圓) 常用於涉及匯率轉換的商務對話；'Japanese headquarters' (日本總部) 常用於描述跨國企業背景。","聽力測驗關鍵點：在 Part 1 圖片題中，若出現日式料理或特定的日式建築風格，選項中可能出現 'Japanese-style' 作為干擾項或正確描述。","閱讀測驗應用：在 Part 7 的行程表或會議記錄中，常出現日本地名或與日本客戶的對接 (Japanese clients)，考生需具備識別國籍身份的能力。","縮寫與連結：在圖表題中常以 'JPN' 縮寫表示，看到此縮寫應立即聯想到與 'Japanese' 相關的訊息。"]}],"g6-p1-p2:people-language:6:american":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00385:american","word":"american","partOfSpeech":["adjective","noun"],"chineseMeaning":"美國的；美國人的；與美國相關的。","categoryZh":"辦公日常","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["american","more american","most american"]},{"partOfSpeech":"noun","forms":["american","Americans"]}],"examples":[{"english":"The company is expanding its operations to the American market.","chinese":"該公司正在擴展其業務到美國市場。"},{"english":"As an American company, we adhere to strict ethical guidelines.","chinese":"作為一家美國公司，我們遵守嚴格的道德準則。"}],"examTips":["常見搭配詞與商業情境：在 TOEIC 考試中常出現在企業組織結構，如 'American branch' (美國分部)、'American headquarters' (美國總部) 或 'American market' (美國市場)。","詞性辨析：'American' 兼具形容詞與名詞身分，閱讀填空題需注意其在句中是修飾名詞（例如 American culture）還是指代人（例如 He is an American）。","聽力測驗要點：考生需熟悉 'American accent' (美式口音) 與 British/Australian 等口音的發音差異，尤其是在 Part 1 與 Part 2 的情境對話中。","文檔來源判斷：在 Part 7 閱讀長文中，識別美式拼法（如 color, center, apologize）有助於判斷該商業文案、信件或合約的撰寫背景與文化語境。","注意事項：在寫作或閱讀理解中，'American' 通常特指美國（United States），但在極少數廣義情境下可能指代整個美洲（The Americas），應根據上下文邏輯進行判斷。"]}],"g6-p1-p2:people-language:8:british":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01270:british","word":"british","partOfSpeech":["adjective"],"chineseMeaning":"源自或與英國相關的；英國的","categoryZh":"溝通互動","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["british","more british","most british"]}],"examples":[{"english":"The company is expanding its operations to include a British branch.","chinese":"該公司正在擴展業務，包括設立英國分公司。"},{"english":"The British standard for this product is higher than the international one.","chinese":"此產品的英國標準高於國際標準。"}],"examTips":["腔調辨識：TOEIC 聽力測驗包含美、英、加、澳四種口音。British 常指英式發音（British accent），考生需熟悉其不捲舌音（如 car, hard）與 t 音在字中較清脆的特徵，這對聽力 Parts 1-4 至關重要。","拼寫與用詞差異：在閱讀測驗中，British English 與 American English 的拼寫（如 centre/center, colour/color）與用詞（如 lift/elevator, flat/apartment, CV/resume）可能出現，熟悉這些差異有助於快速理解商務書信內容。","貨幣與度量衡：在 Part 7 的財務報表或行程單中，British 常與貨幣單位 Pound (£) 或幣別縮寫 GBP 連用。考生需對這類符號有敏感度，以利回答與金錢計算相關的題目。","商業情境搭配：常見搭配詞包含 British subsidiary（英國分公司）、British pound（英鎊）或 British headquarters（英國總部）。在國際商務情境中，常作為說明跨國企業背景的關鍵形容詞。"]}],"g6-p1-p2:people-language:9:chinese":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01709:chinese","word":"chinese","partOfSpeech":["noun","adjective"],"chineseMeaning":"指來自中國或與中國相關的人、語言或文化。","categoryZh":"溝通互動","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["chinese","Chinese"]},{"partOfSpeech":"adjective","forms":["chinese","more Chinese","most Chinese"]}],"examples":[{"english":"Our company is expanding into the Chinese market to reach a wider customer base.","chinese":"我們公司正在擴展到中國市場，以接觸更廣大的客戶群。"},{"english":"He is fluent in Chinese and English, which makes him a valuable asset to our international team.","chinese":"他精通中文和英文，這使他成為我們國際團隊的寶貴資產。"}],"examTips":["詞性辨析：區分國家名 China (名詞) 與 Chinese (形容詞/語言/人)。在 Part 5 詞彙題中，需確認空格是修飾名詞用的形容詞(如 Chinese market)還是指稱國家。","常見搭配詞：在 Part 7 閱讀中，常見 Chinese cuisine (中式料理) 出現在餐飲廣告，或 Chinese branch (中國分公司) 出現在企業動向報導。","聽力陷阱：Part 1 或 Part 2 偶爾會出現國籍或語言的問答，注意 Chinese 除了指中國人，也可指中文(Mandarin/Cantonese 的統稱)。","商業情境：常用於討論市場擴張 (expanding into the Chinese market) 或供應鏈管理 (sourcing from Chinese manufacturers)，是商務對話的基本背景詞。","注意冠詞：'the Chinese' 作為集體名詞指全體中國人時，謂語動詞需用複數形式，此考點偶爾出現在難度較高的文法題中。"]}],"g6-p1-p2:people-language:10:canadian":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01442:canadian","word":"canadian","partOfSpeech":["adjective","noun"],"chineseMeaning":"加拿大人或加拿大的，指來自加拿大或與加拿大相關的事物。","categoryZh":"溝通互動","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["canadian","more canadian","most canadian"]},{"partOfSpeech":"noun","forms":["canadian","Canadians"]}],"examples":[{"english":"The company is expanding its operations to serve the growing Canadian market.","chinese":"該公司正在擴展業務以服務日益增長的加拿大市場。"},{"english":"Many Canadians enjoy outdoor activities like hiking and skiing.","chinese":"許多加拿大人喜歡遠足和滑雪等戶外活動。"}],"examTips":["詞性與用法辨析：'Canadian' 同時具備形容詞（加拿大的）與名詞（加拿大人）的身份。在閱讀測驗中，要注意其與國名 'Canada' 的區別，例如 'a Canadian company'（形容詞用法）與 'based in Canada'（國名用法）。","常見商業搭配詞：在 TOEIC 的商務情境中，常出現如 'Canadian dollar' (加幣, CAD)、'Canadian branch' (加拿大分部) 或 'Canadian head office' (加拿大總部) 等詞組。","聽力關鍵字：聽力測驗中若提及多倫多 (Toronto)、溫哥華 (Vancouver) 或蒙特婁 (Montreal) 等城市時，常會引導出與 'Canadian' 相關的人選或公司背景資訊。","國際貿易情境：常出現於討論跨國協議或進出口貿易的題目，如 'Canadian exporters' (加拿大出口商) 或 'Canadian market trends' (加拿大市場趨勢)。","拼寫與格式：注意作為專有名詞，其首字母必須大寫。在閱讀 Part 5 的詞性選擇題中，若空格位於名詞之前且需修飾該名詞，應選擇形容詞形式的 'Canadian' 而非 'Canada'。"]}],"g6-p1-p2:people-language:11:english":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:03436:english","word":"english","partOfSpeech":["noun","adjective"],"chineseMeaning":"英語；英國的，英國人的","categoryZh":"溝通互動","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["english","English"]},{"partOfSpeech":"adjective","forms":["english","more English","most English"]}],"examples":[{"english":"The meeting will be conducted in English to ensure everyone understands the discussion.","chinese":"為了確保每個人都能理解討論內容，會議將以英語進行。"},{"english":"Proficiency in English is a key requirement for this international sales position.","chinese":"精通英語是這個國際銷售職位的一項關鍵要求。"}],"examTips":["常見搭配詞：'English proficiency' (英語能力)、'Business English' (商務英語)、'English-speaking country' (英語系國家)。在多益招募廣告中，常出現 'fluency in written and spoken English' 作為職缺要求。","商業情境：常用於國際商務溝通、跨國會議記錄（minutes）或培訓課程的語言說明，例如 'The seminar will be conducted in English'。","易混淆辨析：注意 'English'（英格蘭的/英語）與 'British'（英國的/英國人）的區別，前者範圍較窄或僅指語言。多益聽力中可能出現不同口音（美、英、加、澳），皆統稱為英語。","考試重點：在 Part 7 的求職廣告中，'English' 常與 'requirement' 或 'qualification' 連用；Part 2 聽力中若問到語言能力，回答常包含 'proficient' 或 'bilingual'。","答題注意事項：'English' 作為語言或形容詞時，首字母必須大寫。此外，注意 'English' 也可以指 '英格蘭人'，但在多益考試中 99% 的情況是指語言能力。"]}],"g6-p1-p2:people-language:12:african":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00247:african","word":"african","partOfSpeech":["adjective"],"chineseMeaning":"與非洲相關的；非洲的；非洲人的","categoryZh":"行銷與銷售","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"adjective","forms":["african","more african","most african"]}],"examples":[{"english":"The company is launching a new line of African-inspired clothing.","chinese":"該公司正在推出一系列受非洲文化啟發的服裝。"},{"english":"Our marketing campaign will highlight the authentic African craftsmanship.","chinese":"我們的行銷活動將重點介紹正宗的非洲工藝。"}],"examTips":["詞性與名詞辨析：在 TOEIC 考試中需區分名詞 Africa（非洲）與形容詞或名詞 African（非洲的、非洲人）。常考點在於形容詞用法，如修飾市場（African market）或經濟（African economy）。","商務搭配詞組：此單字常出現在國際貿易或擴張情境，常見詞組包含 African trade relations（非洲貿易關係）、African branch office（非洲分公司）或 African emerging markets（非洲新興市場）。","大寫規範與識別：身為專有名詞派生詞，African 首字母必須大寫。在閱讀測驗 Part 7 的長文中，大寫字母能協助考生快速定位地理資訊或公司背景。","聽力測驗陷阱：在 Part 3 與 Part 4 中，若聽到 African 常與「國際出差」、「全球擴張」或「資源開發」等主題相關，考生需注意對話者是否正在討論特定的區域市場策略。","易混淆概念：考生應注意 African 與其他大洲名稱的字尾變化規律（如 Asian, European, American），在 Part 5 詞彙題中，這類詞彙常作為正確選項來描述商品的產地或服務的範圍。"]}],"g6-p1-p2:noun:1:pocket":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:07519:pocket","word":"pocket","partOfSpeech":["noun","verb"],"chineseMeaning":"口袋；金錢；錢包；袖珍的；把…裝入口袋","categoryZh":"辦公日常","starRating":4,"toeicScoreRange":"600-780","wordForms":[{"partOfSpeech":"noun","forms":["pockets"]},{"partOfSpeech":"verb","forms":["pockets","pocketing","pocketed"]}],"examples":[{"english":"He put his hands in his pockets as he waited.","chinese":"他等候時把手插在口袋裡。"},{"english":"She quickly pocketed the small note.","chinese":"她迅速將那張小紙條塞進口袋。"}],"examTips":["常見搭配詞：'out-of-pocket expenses'（代墊費用/自付費用）是多益考試的核心重點，指員工先行墊付並於事後申請報銷的費用。","商業情境：'out-of-pocket' 常用於差旅報帳、醫療保險（指個人需自付的部分）或預算討論中。另外，'deep pockets' 常用來形容某人或某機構財力雄厚。","易混淆辨析：需注意 'pocket money' 與 'allowance' 的差異，前者較生活化，多益正式商務情境多使用 'allowance'（津貼）或 'stipend'。","聽力與閱讀考點：在閱讀測驗的報銷單（reimbursement form）或公司政策說明中，此字常與 'reimburse'（核銷/補償）成對出現。","答題注意事項：當題目出現 'out-of-pocket' 時，答案選項通常與 'personal payment' 或 'reimbursement' 相關，考生應敏感捕捉這些關聯詞。"]}],"g6-p1-p2:noun:2:place":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:07459:place","word":"place","partOfSpeech":["noun","verb"],"chineseMeaning":"地點；位置；場所（通常指特定的區域或設施）","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["place","places"]},{"partOfSpeech":"verb","forms":["place","places","placing","placed"]}],"examples":[{"english":"The meeting will be held in the conference room on the third floor.","chinese":"會議將在三樓的會議室舉行。"},{"english":"Please place the documents in the designated storage place.","chinese":"請將文件放在指定的儲存地點。"}],"examTips":["常見固定搭配『place an order』：在多益聽力與閱讀（特別是 Part 7）中極高頻出現，意指『下訂單』，常出現在購物、物流或企業採購情境中。","動詞用法『place an advertisement』：指在報章雜誌或網路上『刊登廣告』，這在 Part 6 的商業書信或 Part 7 的廣告閱讀題中非常常見。","片語『take place』：意為『舉行、發生』，常用來描述會議、研討會或活動的舉辦，需注意此片語通常不使用被動語態，是 Part 5 常考的文法點。","商業專業用法『place emphasis on』：意為『強調、重視』，常出現在公司政策說明、年度報告或演講稿中，用來表示企業的發展重點。","易混淆詞辨析：在多益中要區分『place』(放置/下單) 與『replace』(更換/取代)，後者常出現在維修、升級設備或人事異動的情境中，答題時需根據上下文判斷是單純的『放置』還是『更新』。"]}],"g6-p1-p2:noun:3:radio":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08082:radio","word":"radio","partOfSpeech":["noun"],"chineseMeaning":"無線電；廣播（設備或媒體）","categoryZh":"行銷與銷售","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["radio","radios"]}],"examples":[{"english":"Our marketing team uses radio advertising to reach a wider audience.","chinese":"我們的行銷團隊使用廣播廣告來接觸更廣泛的受眾。"},{"english":"The company announced a new radio campaign to promote the product launch.","chinese":"公司宣布了一項新的廣播活動以推廣產品發布。"}],"examTips":["常見搭配詞與情境：在 TOEIC 中常以 'radio station' (廣播電台)、'radio advertisement' (廣播廣告) 或 'radio interview' (電台訪談) 出現。","聽力考題重點：在 Part 4 (簡短談話) 中，廣播廣泛用於交通更新 (traffic updates) 或天氣預報 (weather forecasts)，考生應注意開場白如 'You are listening to...' 或結尾 'Stay tuned to...'。","易混淆辨析：注意 'radio' (硬體或媒體) 與 'broadcast' (廣播/播放的動作) 的區別，在閱讀測驗中 'on the radio' 固定搭配 'the'。","商業情境：常出現在行銷預算討論中，作為一種傳播媒介 (medium)，例如討論 'radio spot' (廣播廣告時段) 的成本。","聽力關鍵字：聽到 'tuning in' 或 'frequency' 常暗示場景發生在 radio station，需迅速判斷說話者身份為廣播主持人 (radio host)。"]}],"g6-p1-p2:noun:4:reader":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08154:reader","word":"reader","partOfSpeech":["noun"],"chineseMeaning":"閱讀者；讀者，通常指閱讀商業文件或報告的人。","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["reader","readers"]}],"examples":[{"english":"The company is looking for skilled readers to review and approve marketing materials.","chinese":"公司正在尋找熟練的閱讀者來審閱和批准行銷材料。"},{"english":"Before submitting the report, please ensure all readers understand the key findings.","chinese":"在提交報告之前，請確保所有閱讀者都理解關鍵發現。"}],"examTips":["常見搭配詞與複合詞：在職場中常出現 'proofreader' (校對員) 或 'avid reader' (熱衷的讀者)；而在科技情境中，'card reader' (讀卡機) 或 'e-reader' (電子書閱讀器) 也是常見用法。","商業情境應用：在行銷或出版相關的文章中，常提及 'target reader' (目標讀者) 來分析受眾需求，或是在內部報告中指稱閱讀文件的對象。","聽力辨析要點：在聽力測驗中，需特別區分 'reader' 與 'leader' (領導者) 的發音差異，尤其是在 R 與 L 的發音細節，這是考題中常見的干擾項。","閱讀測驗考點：在 Part 7 的文章閱讀中，常見題目詢問 'Who is the intended reader of this letter?' (這封信的預定讀者是誰？)，考生須透過信件主旨、開頭稱呼或文中提到的職責來判斷讀者身份。","多義性注意：reader 除了指「讀者」外，在學術或特定職稱中也可指「講師」或「讀本」，但在 TOEIC 中多半以「讀者」或「讀取設備」為主。"]}],"g6-p1-p2:noun:6:closet":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01833:closet","word":"closet","partOfSpeech":["noun"],"chineseMeaning":"壁櫥；衣帽間；儲藏室","categoryZh":"物業與不動產","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["closets"]}],"examples":[{"english":"The hotel room has a spacious closet for guests to hang their clothes.","chinese":"飯店房間裡有一個寬敞的衣帽間供客人掛衣服。"},{"english":"We need to clear out the closet in the office to make more space for supplies.","chinese":"我們需要清理辦公室裡的儲藏室，以便騰出更多空間存放用品。"}],"examTips":["常見搭配詞組：在多益辦公室情境中，'supply closet' (辦公用品櫃) 是最高頻出現的組合，通常指存放紙張、文具等備品的地方。","聽力第一部分 (Photographs) 考點：常與動作動詞結合，如 'reaching into a closet' (正伸手進櫃子拿東西) 或 'organizing items in a closet' (正在整理櫃子裡的物品)，考生需留意圖片中的人物是否與儲藏空間有互動。","易混淆詞辨析：'closet' 通常指嵌入牆壁的小型儲藏間；'cabinet' 則多指有門、有抽屜的櫥櫃（如檔案櫃 file cabinet）；而 'wardrobe' 則專指衣櫃。在多益中，'closet' 較常出現在辦公或居家儲物情境。","商業情境應用：在 Part 3 或 Part 4 的對話與短文中，常提及物資短缺需要去 'supply closet' 查看，或是在維修情境中提到 'water heater' 位於 'utility closet' (工具間) 中。","答題注意事項：'closet' 也可作為形容詞使用，如 'closet space' (儲物空間)，在閱讀測驗中若看到相關廣告（如房地產租賃或辦公室設計），需注意空間大小的描述。"]}],"g6-p1-p2:noun:7:road":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08702:road","word":"road","partOfSpeech":["noun"],"chineseMeaning":"道路；供車輛或行人通行的路面，常用於描述運輸路線或交通狀況。","categoryZh":"旅遊與交通","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["road","roads"]}],"examples":[{"english":"The new highway will reduce delivery times for our trucks.","chinese":"新高速公路將縮短我們卡車的送貨時間。"},{"english":"Please note that the main road to the conference center is under construction.","chinese":"請注意，前往會議中心的主要道路正在施工中。"}],"examTips":["常見搭配詞與短語：TOEIC 中常出現 road construction (道路施工)、road closure (道路封閉) 以及 on the road (在旅途中或出差中)。例如業務代表常被描述為 'constantly on the road'。","商業與辦公情境：在聽力或閱讀的公告中，常見關於道路維修導致的通勤延誤通知。此外，roadmap 在商務情境中也常被引申為「發展藍圖」或「專案規劃」。","易混淆詞辨析：需區分 road (連接兩地之交通要道)、street (城鎮中兩旁有建築的街道) 與 route (特定的運輸或公車行駛路線)。在多益中，route 較常與物流和公眾運輸連結。","聽力與閱讀考點：Part 1 圖片題常考道路保養 (road maintenance) 或車輛停靠於路邊。Part 7 閱讀則常出現政府公告，需特別注意受影響的特定路段、日期、時間及建議的替代方案 (detours/alternate routes)。","答題注意事項：聽到 road 時，應留意是否與交通工具或旅行安排有關，若出現在會議日程中，通常指的是外地考察或業務拜訪。"]}],"g6-p1-p2:noun:8:roof":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08724:roof","word":"roof","partOfSpeech":["noun"],"chineseMeaning":"屋頂；建築物頂部覆蓋結構","categoryZh":"物業與不動產","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["roof","roofs"]}],"examples":[{"english":"The construction company is responsible for repairing the damaged roof after the storm.","chinese":"暴風雨過後，建築公司負責維修受損的屋頂。"},{"english":"The building's roof needs to be inspected annually to ensure it meets safety regulations.","chinese":"為了確保符合安全法規，建築物的屋頂需要每年檢查一次。"}],"examTips":["聽力第一部分照片描述考點：常出現『working on the roof』(在屋頂工作) 或『installing solar panels on the roof』(在屋頂安裝太陽能板)，需注意與『ceiling』(室內天花板) 的空間位置區分。","常見搭配詞與商業情境：在設施管理（Facility Management）情境中，常出現『leaking roof』(漏水的屋頂) 或『roof maintenance』(屋頂維護)，通常出現在維修請求書或維修進度公告中。","抽象用法辨析：『under one roof』在閱讀測驗中常用來形容公司資源整合或提供一站式服務，例如：『All departments are now located under one roof.』(所有部門現在都位於同一棟建築內/同一體系下)。","相似詞辨析：在工廠或倉庫情境中，需區分『roof』(屋頂外側) 與『top shelf』(貨架頂層)，聽力測驗中容易因發音或空間概念產生混淆。","答題注意事項：若在聽力測驗中聽到屋頂維修，答案選項常會連結到『renovation』(翻修) 或『building maintenance』(建築維護) 等更上位的分類詞彙。"]}],"g6-p1-p2:noun:9:row":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08748:row","word":"row","partOfSpeech":["noun","verb"],"chineseMeaning":"一排；一列；爭吵","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["row","rows"]},{"partOfSpeech":"verb","forms":["row","rows","rowing","rowed"]}],"examples":[{"english":"Please arrange the documents in a neat row on your desk.","chinese":"請將文件整齊地排放在你的桌面上。"},{"english":"The team members need to avoid rowing with each other and focus on the project goals.","chinese":"團隊成員需要避免互相爭吵，並專注於專案目標。"}],"examTips":["在多益聽力第一大題（照片描述）中，row 常出現於描述物體或人的排列，例如 'in a row'（排成一列）或 'the front row'（第一排），考生應觀察圖片中的座位或器材是否呈線性排列。","常見搭配詞 'in a row' 在閱讀測驗中代表『連續地』，如 'for the third year in a row'（連續第三年），常用於描述公司業績或獲獎情況。","注意名詞與動詞的差異：名詞為排、列；動詞則代表『划（船）』，例如 'rowing a boat'，常見於戶外活動的照片描述。","詞義辨析：row 通常指橫向的『排』，需與縱向的 column（行、欄）區分，這在描述辦公室格局或報表數據時非常重要。","聽力陷阱：row (/roʊ/) 的發音與 low (/loʊ/) 相似，在聽力測驗中應結合語境判斷，例如 'row of chairs' 與 'low price' 的語意截然不同。"]}],"g6-p1-p2:noun:10:ring":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08680:ring","word":"ring","partOfSpeech":["noun","verb"],"chineseMeaning":"電話鈴聲；(電話) 響鈴","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["ring","rings"]},{"partOfSpeech":"verb","forms":["ring","rings","ringing","rang","rung"]}],"examples":[{"english":"The phone rang three times before I could answer it.","chinese":"我還沒來得及接聽，電話就響了三聲。"},{"english":"Please ring the front desk to inform them that the delivery has arrived.","chinese":"請致電前台告知，貨物已送達。"}],"examTips":["電話通訊情境：在 TOEIC 聽力中，ring 常作為動詞表示「撥打電話」或名詞表示「鈴聲」。常見短語如 'give someone a ring'（打給某人）或 'ring back'（回電），這在 Part 3 與 Part 4 的商務對話中極為常見。","習慣用語辨析：慣用語 'ring a bell' 意指「聽起來很耳熟」，常用於商務會議中提到某人名或某項提議時。需注意其並非指實體的鐘響。","多義詞考點：ring 在 Part 1 照片描述題中常以名詞形式出現，指「戒指」或「環狀物」。考生需觀察照片中人物的手部裝飾或場景中的環形構造。","商業結帳情境：動詞片語 'ring up' 專指「在收銀機上登帳」或「結帳」。例如：'The clerk is ringing up the items.' 這在零售業相關的題目中是高頻出現的專業表達方式。","發音與近音詞注意：在聽力測驗中，需區分 ring 與 rank 或 wrong 的發音差異，並結合上下文情境（如電話響起 vs 錯誤訂單）來判斷正確字義。"]}],"g6-p1-p2:noun:11:set":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09049:set","word":"set","partOfSpeech":["noun","verb"],"chineseMeaning":"設置；安排；集合；一套（物）","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["set","sets"]},{"partOfSpeech":"verb","forms":["set","sets","setting"]}],"examples":[{"english":"The meeting is set for 3:00 PM in the conference room.","chinese":"會議已安排在下午三點在會議室舉行。"},{"english":"Please set up the projector and screen before the presentation.","chinese":"請在簡報前設置投影機和螢幕。"}],"examTips":["多功能的片語動詞：在TOEIC中最常出現的是'set up'，可用於『安排會議』、 『建立公司』或『安裝設備』；另一個常見片語是'set back'，指『進度延誤』，常出現在零件短缺或天氣因素的場景中。","預定行程的表達方式：常見句型為'be set to + V'，表示『預計做某事』或『準備好做某事』，例如：'The new branch is set to open next month.'。","商業場景固定搭配：常與目標或限制相關，如'set a deadline'（設定截止日期）、'set a goal'（設定目標）或'set a record'（創紀錄）。","詞性辨析與主動/被動：'set'作為及物動詞表示『放置或設定』，須注意其三態同形（set-set-set）。在閱讀測驗中常以被動式出現，如'The meeting is set for Friday'，意指會議定於週五。","聽力測驗的同義轉換：如果在聽力中聽到'set up the equipment'，閱讀選項常會出現'install the machinery'或'prepare the device'作為正確答案。"]}],"g6-p1-p2:noun:12:seat":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08933:seat","word":"seat","partOfSpeech":["noun","verb"],"chineseMeaning":"座位；（飛機、火車等交通工具上的）席位","categoryZh":"旅遊與交通","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["seat","seats"]},{"partOfSpeech":"verb","forms":["seat","seats","seating","seated"]}],"examples":[{"english":"Could you please reserve a window seat for me on the flight to Tokyo?","chinese":"您能幫我在飛往東京的航班上預訂靠窗的座位嗎？"},{"english":"The conference room has seating for 100 attendees.","chinese":"會議室可容納 100 名與會者。"}],"examTips":["區分動詞與名詞用法：在 TOEIC 聽力第一部分（照片描述）中，常出現「be seated」表示「坐著」的狀態，例如「They are seated at a table.」，這是考題中極高頻出現的被動用法。","常見商務與交通搭配詞：包含「aisle seat」（走道位）、「window seat」（靠窗位）、「seating capacity」（座位容量/容納人數）及「reserve a seat」（預訂座位），這些常出現在機票預訂或場地租借情境中。","易混淆詞辨析：「seat」可作為名詞或及物動詞（需受詞），而「sit」是不及物動詞（不需受詞）。考試中若看到「Please ___ yourself」，應選「seat」而非「sit」。","出題重點：在閱讀測驗的活動公告或研討會通知中，常出現「assigned seating」（對號入座）或「available on a first-come, first-served basis」（座位採先到先得制）。","聽力關鍵字：注意「unoccupied」或「vacant」常與「seat」連用表示空位，若照片中位子沒人，這類選項通常是正確答案。"]}],"g6-p1-p2:noun:13:sauce":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08852:sauce","word":"sauce","partOfSpeech":["noun"],"chineseMeaning":"醬汁；調味液，通常用於增強食物的味道。","categoryZh":"住宿與餐飲","starRating":3,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["sauce","sauces"]}],"examples":[{"english":"The restaurant offers a variety of sauces to complement the grilled meats.","chinese":"這家餐廳提供多種醬汁，以搭配烤肉。"},{"english":"Could you please pass the soy sauce? I'd like to add a little more flavor to my noodles.","chinese":"請問可以把醬油給我嗎？我想在我的麵條裡加一點味道。"}],"examTips":["常見搭配與情境：sauce 常出現在多益的餐廳、飯店或外燴（catering）情境中。常見詞組包括 dipping sauce（沾醬）、homemade sauce（手工醬汁）及 signature sauce（招牌醬汁）。在 Part 7 的菜單或餐廳評論中，常作為修飾餐點細節的關鍵字。","聽力發音辨析：考生需特別區分 sauce [sɔs] 與 source [sɔrs]（來源）的發音。在 Part 2 或 Part 3 聽力中，若對話情境發生在辦公室或會議室，提到 source 的機率較高；若情境在餐敘或超市，則通常指 sauce。此外，還需區分 saucer（茶杯托盤），這常出現在 Part 1 的圖片題。","Part 1 圖片描述考點：在第一部分圖片題中，若圖片顯示廚師在廚房工作或服務生在餐桌旁，正確選項可能為：The chef is preparing a sauce 或 A condiment is being served with the meal。","商業情境應用：在食品製造業或供應鏈（supply chain）相關的考題中，sauce 可能出現在產品包裝、成分清單或物流延遲的對話中。例如討論 sauce production line（醬汁生產線）的維護或 ingredients（原料）的採購。"]}],"g6-p1-p2:noun:14:salt":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08825:salt","word":"salt","partOfSpeech":["noun"],"chineseMeaning":"食鹽；鹽","categoryZh":"住宿與餐飲","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["salt","salts"]}],"examples":[{"english":"Could you please add a little salt to the soup? It needs more flavor.","chinese":"請問您可以幫忙在湯裡加一點鹽嗎？它需要更多味道。"},{"english":"The restaurant uses high-quality sea salt for its signature dishes.","chinese":"這家餐廳在其招牌菜餚中使用高品質的海鹽。"}],"examTips":["Usage in Hospitality Context (Part 1 & 3): In the Listening section, salt often appears in the context of restaurant settings or catering services. In Part 1 (Photographs), look for 'salt and pepper shakers' on a dining table. In Part 3 (Conversations), it may appear in discussions about food supplies or menu adjustments for health-conscious clients.","Idiomatic Expressions (Part 4 & 7): While 'salt' is a basic noun, the idiom 'to take something with a grain of salt' (meaning to be skeptical or not believe something completely) may appear in business readings or talks when discussing unreliable data or exaggerated marketing claims.","Phonetic Distractors in Listening: Be careful not to confuse the pronunciation of 'salt' with 'sort' or 'sold' in fast-paced listening exercises. Distinguish them by the context of seasoning versus organizing or commerce.","Business & Logistics Context: In passages related to infrastructure or manufacturing (Part 7), salt might refer to industrial road salt used for winter maintenance or as a raw material in chemical processing, emphasizing its role in supply chain and logistics.","Collocations with 'Salt': Common phrases include 'salt shaker', 'road salt', and 'low-salt diet'. Recognizing these pairings helps in identifying the specific industry context of a reading passage quickly."]}],"g6-p1-p2:noun:15:sheet":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09110:sheet","word":"sheet","partOfSpeech":["noun"],"chineseMeaning":"紙張；工作表（通常指用於記錄或處理資訊的單張紙）","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["sheet","sheets"]}],"examples":[{"english":"Please submit your expense sheet by the end of the week.","chinese":"請在週末前提交您的費用報表。"},{"english":"The spreadsheet contains a sheet for each department's sales figures.","chinese":"工作表包含各部門銷售數據的單張。"}],"examTips":["常見商務搭配詞：在 TOEIC 閱讀中，sheet 經常與其他字組成複合名詞，如 balance sheet (資產負債表)、time sheet (工時表)、spreadsheet (試算表) 或 fact sheet (資料表)，考生需能快速辨識其特定商業含義。","聽力測驗辨音：特別注意 sheet /ʃiːt/ 與 seat /siːt/ 的發音區別。在 Part 1 照片描述題中，sheet 常指床單，若照片出現飯店場景，聽到 changing the sheets 表示正在更換床單。","多義性辨析：sheet 可指一張紙、報表或床單。在財務情境指報表，在辦公情境指表格或紙張，在旅遊情境則指寢具。答題時需根據上下文判斷其確切指涉對象。","Part 7 常見考點：常出現 sign-up sheet (簽到/報名表) 或 spec sheet (規格表)，通常伴隨要求填寫資料或確認產品規格的指令。","文法與量詞用法：注意 sheet 作為量詞的用法，例如 a sheet of paper (一張紙)，在聽力或閱讀中若提到 sheets of glass 或 metal，則是指大片且平整的板材。"]}],"g6-p1-p2:noun:16:side":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09187:side","word":"side","partOfSpeech":["noun","adjective","verb"],"chineseMeaning":"邊；側面；側邊；一方；（爭論或比賽的）一方；方面；（物體的）面；側面的；次要的；非主要的；支持；贊同；與...站在一起","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["side","sides"]},{"partOfSpeech":"adjective","forms":["side"]},{"partOfSpeech":"verb","forms":["side","sides","sided","siding"]}],"examples":[{"english":"Please put the documents on the right side of the desk.","chinese":"請將文件放在辦公桌的右邊。"},{"english":"She always sides with her team during negotiations to ensure they get the best deal.","chinese":"在談判中，她總是支持她的團隊，以確保他們獲得最佳協議。"}],"examTips":["常見搭配詞與情境：在聽力第一部分的照片描述中，常出現「side by side」(並排)來形容物體或人的相對位置。此外，「on the side」在多益中常用來表示「額外地」或「兼職地」。","商業情境中的應用：在談判或合約情境中，「both sides」或「each side」用來指代參與協議的雙方。理解「side of the story」或「side of the argument」能幫助理解對話中的觀點差異。","易混淆詞辨析：應區分「side」(側面/方面)與「site」(地點/場所)及「sight」(視線/名勝)。這三個詞在聽力測驗中發音相似，需根據上下文判斷。例如：'construction site' (工地) 與 'side door' (側門) 的情境完全不同。","常見考點與片語：注意「aside from」(除了...之外) 的用法，這在閱讀測驗 Part 5 的文法題中極其常見，其義同「except for」或「in addition to」。","聽力答題技巧：當在 Part 2 聽到關於意見分歧的題目時，若出現「take someone's side」表示支持某方的立場，這是理解對話者關係的重要線索。"]}],"g6-p1-p2:noun:17:sign":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09198:sign","word":"sign","partOfSpeech":["noun","verb"],"chineseMeaning":"標誌；簽署；指示牌","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["sign","signs"]},{"partOfSpeech":"verb","forms":["sign","signs","signing","signed"]}],"examples":[{"english":"Please sign the contract before the deadline to finalize the deal.","chinese":"請在截止日期前簽署合約，以完成交易。"},{"english":"The 'No Parking' sign clearly indicates where vehicles are prohibited.","chinese":"「禁止停車」的標誌清楚地指示了車輛禁止停放的區域。"}],"examTips":["詞性辨析與易混淆詞：在TOEIC中，sign常作為動詞「簽名」或名詞「告示牌」。最常考的是它與signature（名詞：簽名）的區別，考生常在填空題中誤選。請記住：sign a contract (動詞)，而 Please provide your signature (名詞)。","商業常見搭配：動詞用法常搭配 contract、agreement、lease（租約）或 check（支票）；名詞用法常見於 sign-in sheet（簽到表）、sign-up sheet（報名表）或 for lease sign（出租告示）。","短語動詞考點：sign up for（報名參加課程或活動）是聽力與閱讀的高頻詞組；sign off on 則是商業情境中的「正式核准」，常用於上級批准計畫。","聽力情境重點：在 Part 1 照片描述中，若看到人物在寫字，選項常出現 \"signing some documents\"。在 Part 3 & 4 中，sign 常與辦公室規定（如 follow the signs）或合約簽署進度相關。","多義項注意：除了簽名和告示，sign 在進階商務閱讀中也可表示「跡象或徵兆」，例如 signs of economic recovery（經濟復甦的跡象）。"]}],"g6-p1-p2:noun:18:sport":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09514:sport","word":"sport","partOfSpeech":["noun"],"chineseMeaning":"運動；體育活動，通常指有組織且有競賽性質的活動。","categoryZh":"營運管理","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["sport","sports"]}],"examples":[{"english":"The company sponsors several local sports teams to enhance its brand image.","chinese":"公司贊助多支當地體育隊伍，以提升品牌形象。"},{"english":"Employee wellness programs often include opportunities to participate in various sports and recreational activities.","chinese":"員工健康計畫通常包含參與各種體育和休閒活動的機會。"}],"examTips":["動詞特殊用法：在多益 Part 1 照片描述題中，sport 有時作為動詞，意為「穿戴」或「展示」，例如 A man is sporting a hat. (男人正戴著帽子)，考生需識別此非運動情境的用法。","常見商務搭配：熟悉 sporting goods (體育用品) 與 sporting events (體育賽事)，這些詞組常出現在零售業報告或公司活動通知中。","企業文化情境：在 Part 3 與 Part 7 中，sport 常與 team-building (團隊建設) 或 employee benefits (員工福利) 相關聯，例如舉辦 corporate sports day 或提供 gym membership 作為福利。","營銷與贊助考點：多益常考 corporate sponsorship (企業贊助) 體育活動的情境，重點在於品牌宣傳與公共關係的建立。","詞彙辨析：區分 sport (具規則競爭性的運動) 與 exercise (泛指體能活動或練習)，在健康與休閒類文章中，後者更強調個人的體適能提升。"]}],"g6-p1-p2:noun:19:stair":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09557:stair","word":"stair","partOfSpeech":["noun"],"chineseMeaning":"樓梯；梯級","categoryZh":"物業與不動產","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["stairs"]}],"examples":[{"english":"Please take the stairs to the second floor.","chinese":"請走樓梯到二樓。"},{"english":"She climbed the stairs slowly, feeling tired.","chinese":"她感到很累，緩慢地爬著樓梯。"}],"examTips":["常見搭配詞：常用於 'climb the stairs' (爬樓梯)、'flight of stairs' (一段樓梯) 或 'stairwell' (樓梯井)。在 TOEIC 聽力中，'handrail' (扶手) 常與此詞一同出現。","聽力第一部分 (Photographs) 考點：常出現在描述人物動作的照片，如 'A person is walking up the stairs' 或 'Someone is holding onto the railing'。","易混淆詞辨析：注意同音異義詞 'stare' (凝視) 以及拼寫相近的 'steer' (駕駛)；此外，'stairs' (樓梯) 與 'steps' (階梯/步驟) 在描述建築結構時常可互換。","商業與辦公情境：常出現在辦公大樓的設施說明、修繕公告或緊急逃生指南 (emergency stairs) 中。","答題技巧：若在聽力測驗聽到 'stairs'，應同時留意照片中是否有相對應的垂直移動動作或階梯構造，避免被同音詞誤導。"]}],"g6-p1-p2:noun:20:stamp":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09564:stamp","word":"stamp","partOfSpeech":["noun","verb"],"chineseMeaning":"郵票；蓋章","categoryZh":"採購與物流","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["stamp","stamps"]},{"partOfSpeech":"verb","forms":["stamp","stamps","stamping","stamped"]}],"examples":[{"english":"Please ensure all outgoing packages are properly stamped with postage.","chinese":"請確保所有寄出的包裹都已正確蓋上郵票。"},{"english":"The customs officer stamped the document to verify its authenticity.","chinese":"海關人員蓋章以驗證文件的真實性。"}],"examTips":["常見搭配詞與多重義：名詞常見 postage stamp (郵票)、rubber stamp (橡皮圖章) 及 time stamp (時間戳記)；動詞則常用於 stamp the document (在文件上蓋章)。","商業情境應用：在辦公室與物流情境中，stamp 常指『核准』或『確認收貨』的動作，例如在發票或合約上蓋章以示正式生效。","易混淆詞辨析：需區分 stamp (蓋章) 與 sticker (貼紙) 或 label (標籤)，stamp 通常涉及墨水壓印或具有郵資價值的票證；聽力中需注意與音近詞 stomp (重踩) 的區別。","多益聽力考點：在第一部分圖片描述題中，常出現人員正在 'stamping a form' 或文件被放置在 'rubber stamp' 旁的場景。","閱讀與物流：在第七部分閱讀中，常出現於包裹寄送指示，如 'affix a stamp' (貼上郵票) 或提到 'postmark' (郵戳) 以確認寄件日期。"]}],"g6-p1-p2:noun:21:step":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09643:step","word":"step","partOfSpeech":["noun","verb"],"chineseMeaning":"步驟；程序；階梯","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["step","steps"]},{"partOfSpeech":"verb","forms":["step","steps","stepping","stepped"]}],"examples":[{"english":"Please follow these steps to complete the online registration.","chinese":"請按照這些步驟完成線上註冊。"},{"english":"The company is taking steps to improve employee morale.","chinese":"公司正在採取措施來提升員工士氣。"}],"examTips":["常用搭配詞與商業用法：在多益閱讀中，'take steps to' 是極高頻的搭配詞，意指『採取行動以...』，常與 'take measures' 或 'take action' 替換。在公司管理情境中，'step down' 常表示『辭職、退位』，而 'step up' 則表示『加強、提升（如生產力）』。","混淆詞辨析：'step' 通常指為了達成目標所做的『具體單一動作』，而 'stage' 或 'phase' 則指大型計畫中的『一個階段』。在 Part 7 流程圖或作業指引中，要特別注意順序連接詞與 step 的對應關係。","聽力測驗重點：在 Part 1 照片描述中，常出現與身體動作相關的描述，如 'stepping onto the train' (步上火車) 或 'walking down the steps' (走下階梯)。","職場變遷情境：當公司公告提到 'step into the role' 時，代表某人『接任』新職位，這是人力資源類題目中的常見表達方式。","注意介係詞搭配：'in step with' 表示『與...同步』，常用於市場趨勢或政策調整的情境，考生需注意其語意為保持一致。"]}],"g6-p1-p2:noun:22:storm":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09692:storm","word":"storm","partOfSpeech":["noun","verb"],"chineseMeaning":"（尤指突然的）風暴、嚴峻的局面或情況","categoryZh":"營運管理","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["storm","storms"]},{"partOfSpeech":"verb","forms":["storm","storms","storming","stormed"]}],"examples":[{"english":"The company is facing a storm of negative publicity following the product recall.","chinese":"由於產品召回，公司正面臨一陣負面新聞的風暴。"},{"english":"The project team needs to weather the storm and deliver the final report on schedule.","chinese":"專案團隊需要度過難關，並按時交付最終報告。"}],"examTips":["In Part 4 weather reports, 'storm' is a key keyword that frequently signals upcoming flight cancellations or event delays; look for synonyms like 'adverse weather' or 'severe conditions'.","In business contexts, the compound word 'brainstorm' is highly frequent, referring to group sessions for generating ideas or solving problems.","Be aware of the idiom 'take by storm', which means to become suddenly successful or popular, often appearing in reading passages about new market trends or product launches.","Distinguish 'storm' from similar-sounding words like 'stream' or 'store' in listening sections; 'storm' will be contextualized with words like 'thunder', 'wind', or 'forecast'.","Pay attention to the figurative use of 'stormy', such as 'a stormy meeting', which describes a session filled with strong conflict or heated debate rather than actual weather."]}],"g6-p1-p2:noun:23:swimming":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09952:swimming","word":"swimming","partOfSpeech":["noun","verb"],"chineseMeaning":"游泳；水域活動","categoryZh":"旅遊與交通","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["swimming","swims"]},{"partOfSpeech":"verb","forms":["swimming","swims","swam","swum"]}],"examples":[{"english":"The company offers wellness programs that include swimming lessons for employees.","chinese":"公司提供健康計畫，其中包含員工游泳課程。"},{"english":"After a long day of meetings, a quick swim in the hotel pool can be very refreshing.","chinese":"在漫長的一天會議結束後，在飯店游泳池裡快速游泳可以讓人感到非常清爽。"}],"examTips":["常見搭配詞：swimming pool (游泳池)、swimming gear (游泳裝備)、go swimming (去游泳)，此類詞彙常出現在聽力第一部分的照片描述中。","商業情境應用：在 TOEIC 中，swimming 常出現在員工福利計畫、公司健身中心設施說明或商務飯店的設施指南中。","易混淆詞辨析：在聽力測驗中需區分 swimming 與 wading (涉水) 的細微差別，wading 通常指在淺水中行走而非全身游動，這在照片描述題中是常見陷阱。","聽力與閱讀考點：Part 1 常考描述人正在游泳的動作（e.g., Some people are swimming in the ocean）；Part 7 則常見於休閒度假村或飯店的設施開放時間表（Opening Hours）或安全規範（Safety Regulations）中。","答題注意事項：聽力練習時應特別注意單字字尾 -ing 的連音，並小心與其發音相近的單字如 swinging (擺動) 或 slimming (減肥) 所造成的聽覺干擾。"]}],"g6-p1-p2:noun:24:tail":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10002:tail","word":"tail","partOfSpeech":["noun"],"chineseMeaning":"尾部；尾端（通常指動物或車輛的後部）","categoryZh":"營運管理","starRating":2,"toeicScoreRange":"780-900","wordForms":[{"partOfSpeech":"noun","forms":["tail","tails"]}],"examples":[{"english":"The truck's tail gate was damaged during the delivery.","chinese":"這輛貨車的後門在送貨過程中受損了。"},{"english":"The project is nearing its tail end; we should finalize the report next week.","chinese":"這個專案即將進入尾聲，我們下週應該完成報告。"}],"examTips":["常用於搭配詞 'tail end'：在 TOEIC 聽力與閱讀中，'tail end' 經常用來形容某個時間點或事件的「最後部分」，例如 'the tail end of the project'（專案的尾聲）或 'the tail end of the year'（年底）。","動詞用法表示「跟隨」：在商務安全或物流管理情境中，'tail' 可作為動詞，意指「尾隨」或「盯梢」，例如 'Security personnel were assigned to tail the suspect'。","區分相似詞辨析：在 Part 1 聽力中，需注意 'tail' 與 'retail'（零售）、'detail'（細節）的發音干擾；此外，也要區分同音異義詞 'tale'（故事/傳說），後者在商務情境中極少出現。","片語 'tail off' 的應用：此片語表示「逐漸減少」或「減弱」，在 Part 7 的商業報告或圖表分析中常出現，例如 'Sales figures started to tail off after the holiday season'（假期過後銷售數字開始下滑）。","答題注意事項：若在聽力測驗中聽到 'tail'，應結合上下文判斷其是名詞（尾部/後部）還是動詞（跟隨），避免僅從動物尾巴的基礎字義來解題。"]}],"g6-p1-p2:noun:25:taxi":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10092:taxi","word":"taxi","partOfSpeech":["noun"],"chineseMeaning":"計程車；出租車，通常指為乘客提供代客運輸服務的車輛。","categoryZh":"旅遊與交通","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["taxi","taxis"]}],"examples":[{"english":"The company will reimburse employees for taxi fares incurred during business trips.","chinese":"公司將會退償員工在商務旅行中產生的計程車費用。"},{"english":"To reach the airport on time, I took a taxi instead of the subway.","chinese":"為了準時到達機場，我搭計程車而不是捷運。"}],"examTips":["常見搭配與片語：熟悉 'hail a taxi' (招計程車)、'take a taxi' (搭計程車) 以及 'taxi stand' 或 'taxi rank' (計程車招呼站) 等用法。","多重字義考點：在聽力第一部分 (Part 1) 中，'taxi' 亦可當動詞，指飛機在跑道上「滑行」(e.g., The plane is taxiing on the runway)，這是考生容易忽略的高階考點。","商業出差情境：常出現在 Part 3 與 Part 4 的交通安排中，伴隨出現的關鍵字包括 'reimbursement' (報帳)、'receipt' (收據) 與 'fare' (車資)。","易混淆詞辨析：在聽力測驗中，需區分 'taxi' 與發音相近的 'tax' (稅務)，並注意同義詞 'cab' 的互換使用。","答題細節：若題目涉及車資計算，需特別留意是否提到 'tip' (小費) 或 'surcharge' (額外費用)，這常是 Part 2 或短文閱讀中的陷阱。"]}],"g6-p1-p2:noun:26:shampoo":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:09093:shampoo","word":"shampoo","partOfSpeech":["noun"],"chineseMeaning":"洗髮精；洗髮產品","categoryZh":"住宿與餐飲","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["shampoo","shampoos"]}],"examples":[{"english":"The hotel provides complimentary shampoo and conditioner for all guests.","chinese":"飯店為所有住客提供免費洗髮精和護髮素。"},{"english":"Our company is launching a new line of organic shampoos targeting eco-conscious consumers.","chinese":"我們公司即將推出全新系列有機洗髮精，鎖定重視環保的消費者。"}],"examTips":["常用搭配詞與情境：在 TOEIC 的飯店情境中，shampoo 常與 conditioner (潤髮乳)、lotion (乳液) 及 soap (肥皂) 一起出現在 'amenities' (飯店備品) 的清單中。常見搭配如 'complimentary shampoo' (免費洗髮精) 或 'travel-size shampoo' (旅行裝洗髮精)。","多重詞性應用：shampoo 除了作為名詞（洗髮精），也可作為動詞（清洗）。在辦公室維護情境中，'shampoo the carpet' 指的是專業地毯清洗，這在 Part 3 的對話或 Part 7 的設施維護公告中可能出現。","聽力與閱讀考點：在 Part 1 圖片描述題中，可能會出現藥妝店貨架上整齊排列的瓶子 (bottles are lined up on the shelf)。在 Part 3 飯店對話中，常出現顧客向櫃檯請求 'refill' 或 'restock' 洗髮精的情節。","易混淆詞辨析：需區分 shampoo 與 conditioner。在商業廣告或產品目錄中，這兩者常被統稱為 'hair care products'。此外，也要注意其與 soap (肥皂) 的區別，通常肥皂指的是塊狀，而 shampoo 是液態。","答題注意事項：注意 shampoo 作為名詞時通常為不可數名詞，但當指代『一瓶洗髮精』或『不同種類的洗髮精』時，在非正式語境或特定商業報表中有時會看到複數形式，但在文法選擇題中仍應視為不可數。"]}],"g6-p1-p2:noun:27:choice":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01714:choice","word":"choice","partOfSpeech":["noun","verb"],"chineseMeaning":"選擇；選項","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["choice","choices"]},{"partOfSpeech":"verb","forms":["choice","chooses","choosing","chose","chosen"]}],"examples":[{"english":"The company offers a wide range of health insurance choices for its employees.","chinese":"該公司為員工提供多樣的健康保險選擇。"},{"english":"After careful consideration, he chose the most cost-effective option.","chinese":"經過仔細考慮後，他選擇了最具成本效益的方案。"}],"examTips":["常用搭配詞組：多益中常出現 'make a choice' (做決定)，注意動詞使用 make 而非 do；此外 'a wide choice of' (多樣化的選擇) 常出現在零售或餐飲情境，用來描述商品種類繁多。","固定句型考點：'have no choice but to + 原形動詞' (別無選擇只能...) 是 Part 5 的高頻文法題，考生常在 to 之後誤選動名詞，務必記住此結構需接不定詞。","詞性與字形辨析：在詞性題中需區分名詞 'choice' 與動詞 'choose' (過去式為 chose，過去分詞為 chosen)，注意 choice 是名詞，常接在形容詞或冠詞之後。","同義詞替換：在 Part 7 閱讀理解中，'choice' 常與 'option' (選項) 或 'selection' (挑選的物品/精選) 進行同義詞替換，辨識這些字眼有助於快速定位答案。","商務情境應用：此單字常出現於人事招募 (the best choice for the position) 或採購契約 (final choice of vendor) 中，理解其代表『決定』或『首選的人事物』之意。"]}],"g6-p1-p2:noun:28:team":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10101:team","word":"team","partOfSpeech":["noun"],"chineseMeaning":"團隊；團隊成員","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["team","teams"]}],"examples":[{"english":"Our sales team is working hard to meet the quarterly targets.","chinese":"我們的銷售團隊正在努力達成季度目標。"},{"english":"The project team needs to collaborate effectively to ensure timely completion.","chinese":"專案團隊需要有效合作以確保按時完成。"}],"examTips":["常見搭配詞：'team up with' 表示與某人合作，'team player' 指具備團隊合作精神的人，'lead a team' 則為帶領團隊。","商業情境：常用於 Part 7 閱讀中的公司內部信件或公告，描述跨部門合作、團隊建設活動（team-building activities）或專案分工。","易混淆詞辨析：'team' 強調為特定目標合作的小組，而 'staff' 指公司整體的職員，'crew' 則多用於飛機、船隻或電影拍攝的專業工作組。","考試重點：在聽力測驗中，對話常涉及 'working as a team' 或 'joining the team'，考生需辨認說話者的身分與職責。","文法與介系詞：在多益中常考介系詞搭配，表示『在團隊中』通常用 'on the team' 而非 'in the team'。"]}],"g6-p1-p2:noun:29:telephone":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10132:telephone","word":"telephone","partOfSpeech":["noun"],"chineseMeaning":"電話；電話機，用於遠距離語音通訊的設備。","categoryZh":"溝通互動","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["telephone","telephones"]}],"examples":[{"english":"Could you please leave a message on the telephone?","chinese":"您好，請問可以留言嗎？"},{"english":"The company policy requires all employees to use the office telephone for business calls.","chinese":"公司規定所有員工必須使用辦公室電話進行商務電話。"}],"examTips":["常見搭配詞：'telephone extension' (電話分機)、'telephone directory' (電話簿)、'by telephone' (透過電話)。","商業情境：在多益聽力中常出現在預約會議、客戶服務或留言的情境，注意其作為動詞 'to telephone someone' 的正式用法。","聽力考點：Part 1 常考圖片描述，如 'A man is using a telephone'；Part 3/4 則常涉及 'telephone message' (電話留言) 或 'return a call' (回電)。","易混淆辨析：注意與 'cellphone' 或 'mobile phone' 的區別，在正式辦公室情境中 'telephone' 多指桌上型分機，而口語中多簡稱為 'phone'。","答題注意：當聽到相關動詞片語如 'on hold' (等候接聽)、'put through' (轉接) 或 'hang up' (掛斷) 時，通常暗示該段落為電話溝通場景。"]}],"g6-p1-p2:noun:30:television":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10135:television","word":"television","partOfSpeech":["noun"],"chineseMeaning":"電視機；電視廣播","categoryZh":"科技與技術支援","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["television","televisions"]}],"examples":[{"english":"The company is considering installing televisions in the waiting area to entertain clients.","chinese":"公司正在考慮在等候區安裝電視機，以娛樂客戶。"},{"english":"The marketing team used television advertising to promote the new product line.","chinese":"行銷團隊利用電視廣告來推廣新的產品線。"}],"examTips":["常見搭配詞組：常用搭配包括 'on television'（在電視上）、'television commercial'（電視廣告）、'television broadcast'（電視廣播）及 'television network'（電視網）。","商業情境應用：在 TOEIC 中，此單字常出現在市場行銷與廣告討論中，例如討論廣告預算分配或電視廣告（TV spots）的播出時段。","易混淆詞辨析：需區分 'television'（硬體或媒介）與 'program'（節目內容）。此外，需與 'monitor' 辨析，monitor 多指電腦螢幕或監視器，而 television 專指接收廣播訊號的設備。","聽力與閱讀考點：在聽力第一部分照片描述中，若出現螢幕，選項可能使用 'television set' 或 'monitor'。在聽力第三、四部分，常涉及媒體公關或產品發佈的宣傳渠道討論。","答題注意事項：注意 'television' 的縮寫 'TV' 在非正式對話中極其常見，但在閱讀測驗的合約、正式報告或公告中，多使用全稱或更專業的術語如 'broadcast media'。"]}],"g6-p1-p2:noun:31:tennis":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10153:tennis","word":"tennis","partOfSpeech":["noun"],"chineseMeaning":"網球；網球運動","categoryZh":"旅遊與交通","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["tennis","tennis courts"]}],"examples":[{"english":"The company is offering tennis lessons to employees as part of its wellness program.","chinese":"公司將網球課程提供給員工，作為其健康促進計畫的一部分。"},{"english":"The conference venue includes a tennis court for attendees to relax and network.","chinese":"會議場地設有網球場，供與會者放鬆身心並建立聯繫。"}],"examTips":["常見搭配詞：'play tennis' (打網球)、'tennis court' (網球場)、'tennis racket' (網球拍) 以及 'tennis match/tournament' (網球比賽)。在聽力測驗中，這些搭配詞常出現在安排休閒活動的對話中。","商業與社交情境：此單字常出現在 TOEIC 的社交場合（Socializing）或員工福利（Employee Benefits）主題。例如：描述商務招待活動、公司贊助的體育賽事，或同事間下班後的休閒邀約。","詞意辨析：需區分 'tennis' 與 'table tennis' (桌球)；此外，注意 'court' 在多義詞考點中，除了指網球場，也可能指法庭，應從上下文如 'racket' 或 'judge' 判斷其意。","考試出題重點：在第一部分圖片描述題中，若出現球場景觀，應注意 net (網子)、baseline (底線) 等相關詞彙；在第三、四部分對話或短文，則常用來作為約會提議或討論活動行程的選項。","答題注意事項：'tennis' 作為運動名稱是不可數名詞，通常直接搭配 play 使用，不需要加冠詞 a 或 an。"]}],"g6-p1-p2:noun:32:toilet":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10316:toilet","word":"toilet","partOfSpeech":["noun"],"chineseMeaning":"廁所；盥洗室（通常指公共廁所或辦公室廁所）","categoryZh":"辦公日常","starRating":1,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["toilet","toilets"]}],"examples":[{"english":"Could you please tell me where the nearest toilet is?","chinese":"請問最近的廁所在哪裡？"},{"english":"The cleaning staff is responsible for maintaining the cleanliness of the toilets.","chinese":"清潔人員負責維護廁所的清潔。"}],"examTips":["多樣化的替代詞彙：在 TOEIC 考試（特別是聽力測驗）中，較正式或美式商務情境常使用 restroom、washroom 或 bathroom 取代 toilet。在飛機情境中，則固定使用 lavatory。考生應熟悉這些同義詞以應對不同的對話背景。","設施維修情境：此單字常出現在辦公室設施報修的情境中，常見搭配詞組包括 out of order (故障中)、clogged (堵塞的) 或 under maintenance (維修中)。若在 Part 1 圖片題看到清潔人員，選項可能會出現 cleaning the facilities。","易混淆詞辨析：需區分 toilet 與 toiletries (盥洗用品)。toiletries 指的是肥皂、洗髮精、牙刷等個人清潔用品，這在飯店住宿或旅行用品的閱讀題組中非常常見。","方位引導關鍵字：在聽力 Part 2 或 Part 3 的方向詢問中，toilet/restroom 常與方位詞連用，例如 at the end of the hallway (走廊盡頭)、opposite the elevator (電梯對面) 或 adjacent to the break room (茶水間隔壁)。","公共設施的泛稱：在正式通知或辦公室公告中，有時會以 facilities 一詞概括包含廁所在內的各項公共設備，考生需具備從上下文判斷具體指涉對象的能力。"]}],"g6-p1-p2:noun:33:top":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10341:top","word":"top","partOfSpeech":["noun","adjective","verb","adverb"],"chineseMeaning":"頂部、最高處；蓋子、頂蓋；上衣；最佳的、頂級的、最高的；達到頂點、超越、加蓋、給…封頂","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["top","tops"]},{"partOfSpeech":"adjective","forms":["top"]},{"partOfSpeech":"verb","forms":["top","tops","topped","topping"]},{"partOfSpeech":"adverb","forms":["top"]}],"examples":[{"english":"The meeting notes are on the top of the pile.","chinese":"會議紀錄在檔案堆的最上面。"},{"english":"Our team aims to top the sales figures this quarter.","chinese":"我們的團隊目標是本季度超越銷售額。"}],"examTips":["動詞用法：在多益商務情境中，top 常解釋為「超過」或「勝過」，例如「Sales topped $1 million this quarter」(本季銷售額突破百萬)，考生應注意其作為動詞的數據描述功能。","常見搭配詞：'top priority' (首要任務) 是閱讀測驗中極高頻出現的片語，通常與時間管理或專案目標相關；'top-tier' 則用來形容「一流的」產品或服務。","介系詞搭配 'on top of'：除了實體方位外，多益聽力中常表示「除了...之外 (還有)」，語意同 in addition to，常用於追加工作任務或額外費用的情境。","職位與等級：'top executive' 指的是「高階主管」，這與 'management' 或 'senior leaders' 互為同義替換詞，是聽力測驗中題目與選項互換的常客。","辨析 peak 與 top：雖然兩者皆有最高之意，但 peak 常用於描述「高峰期」(peak season) 或數據曲線的頂點，而 top 則更廣泛用於形容重要性、職位或品質的等級。"]}],"g6-p1-p2:noun:34:towel":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10368:towel","word":"towel","partOfSpeech":["noun","verb"],"chineseMeaning":"一種吸水性織物，通常由棉製成，用於擦拭或擦乾身體或物體。毛巾。","categoryZh":"住宿與餐飲","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["towels"]},{"partOfSpeech":"verb","forms":["toweling","towelling","toweled","towelled","towels"]}],"examples":[{"english":"Please hang your wet towel to dry after showering.","chinese":"淋浴後請將濕毛巾掛起來晾乾。"},{"english":"She used a paper towel to wipe up the spilled coffee.","chinese":"她用一張紙巾擦拭灑出來的咖啡。"}],"examTips":["常見搭配詞與情境：在 TOEIC 考試中常出現於飯店、健身房或辦公室設施情境。常見搭配詞包含 'fresh towels' (乾淨的毛巾)、'bath towel' (浴巾) 以及 'paper towel dispenser' (擦手紙分配器)。","聽力陷阱辨析：在聽力測驗（特別是 Part 1）中，要注意其發音與 'tower' (塔、大樓) 相似，考生應根據圖片背景判斷是生活用品還是建築物。","飯店住宿考點：常出現在 Part 3 聽力或 Part 7 閱讀的對話與信件中，例如顧客要求 'extra towels' (額外毛巾) 或飯店告知 'towel reuse policy' (毛巾重複使用環保政策)。","圖片題狀態描述：在 Part 1 描述物品狀態時，常考 'towels are folded' (毛巾已摺好)、'towels are stacked' (毛巾被堆疊著) 或 'towels are hanging on a rack' (毛巾掛在架上)。","職場環境應用：在辦公室維修或清潔的對話中，可能提到補充 'paper towels' (紙巾) 於茶水間或盥洗室，是生活化商務英文的常見字彙。"]}],"g6-p1-p2:noun:35:town":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10372:town","word":"town","partOfSpeech":["noun"],"chineseMeaning":"城鎮；市鎮（通常指規模較小，且具有地方特色或歷史意義的居住區）","categoryZh":"旅遊與交通","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["town","towns"]}],"examples":[{"english":"The company is planning to open a new branch in a small town outside the city.","chinese":"公司計畫在市郊的一個小鎮開設新分店。"},{"english":"The conference attendees will be staying in hotels located in the nearby town.","chinese":"會議的參與者將住在附近小鎮的飯店。"}],"examTips":["常見搭配詞組：最常出現的是 'out of town'（出差或不在城裡）以及 'downtown'（市中心/商業區）。在聽力測驗中，'He is out of town on business' 是解釋某人缺席會議的經典理由。","商業情境應用：常用於地方政府公告或社區事務，如 'town hall meeting'（市民大會/公眾諮詢會）或 'town council'（鎮議會），這在閱讀測驗 Part 7 的地方新聞或公告中十分常見。","易混淆詞辨析：需區分 'town'（城鎮）、'city'（大城市）與 'village'（鄉村）。在 TOEIC 中，'town' 較強調在地社區感，而 'city' 則多與國際化、大型企業總部聯繫。","聽力與閱讀考點：Part 1 照片描述中若出現街道或小商店，可能會考到 'town square'（城鎮廣場）；Part 7 則常出現有關當地店家開業或搬遷（relocating within the town）的訊息。","答題注意事項：注意 'down' 字根的字，不要將 'downtown'（市中心）與 'downstairs'（樓下）混淆，兩者在聽力選項中常作為干擾項出現。"]}],"g6-p1-p2:noun:36:wave":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:10985:wave","word":"wave","partOfSpeech":["noun","verb"],"chineseMeaning":"（手或旗幟的）揮舞；波動；（電磁波等）波","categoryZh":"溝通互動","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["wave","waves"]},{"partOfSpeech":"verb","forms":["wave","waves","waving","waved"]}],"examples":[{"english":"The CEO waved to the departing employees as a gesture of appreciation.","chinese":"CEO 在離職員工離開時揮手致意，以表達感謝。"},{"english":"The company is riding the wave of increased demand for its products.","chinese":"公司正乘著對其產品需求增加的浪潮。"}],"examTips":["在多益聽力第一部分（照片描述）中，'Waving to someone' 是常見的高頻短語，用來描述人物對著他人揮手致意或道別。","商業閱讀中，該詞常以比喻用法出現，如 'A wave of new technology' 或 'A wave of mergers'，意指某種現象的大量湧現或一波趨勢。","需特別注意音近詞 'waive' (動詞：放棄、免除) 的辨析，'waive the fee'（免除費用）在商務契約或服務說明中非常常見，而 wave 則多與手勢、物理波浪或抽象浪潮有關。","在氣象或環境議題的閱讀測驗中，'heat wave' (熱浪) 是固定搭配詞，考生應能迅速辨識其含意。","注意其名詞與動詞的轉換：名詞除了指水波，也可指頭髮的捲曲度或手的揮動；動詞則聚焦於擺動或揮動的動作。"]}],"g6-p1-p2:noun:37:weekend":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:11017:weekend","word":"weekend","partOfSpeech":["noun"],"chineseMeaning":"週末；週六和週日的假期","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["weekend","weekends"]}],"examples":[{"english":"The deadline for the project has been extended until next weekend.","chinese":"這個專案的截止日期已延遲到下週末。"},{"english":"Many employees look forward to the weekend to relax and recharge.","chinese":"許多員工期待週末來放鬆和充電。"}],"examTips":["介系詞的精確使用：在 TOEIC 考試中，美式用法常用 'on the weekend'，而 'over the weekend' 則常用於描述在整個週末期間發生的活動（例如：The office was painted over the weekend.）。","常見搭配詞組：留意 'long weekend'（連假/長週末）、'weekend shift'（週末班次）與 'weekend getaway'（週末短期旅遊），這些詞彙頻繁出現在聽力的對話與閱讀的廣告郵件中。","易混淆詞辨析：務必區分 'weekend'（週六、週日）與 'weekday'（週一至週五的平日），題目常在行程安排的對話中利用這兩者的區別設置陷阱。","商業與辦公情境：在 Part 3 與 Part 4 中，常出現員工討論週末加班、維修人員在週末進行器材檢修、或是餐廳/飯店提供的週末折扣優惠（weekend special rates）。","答題重點：若題目詢問活動何時發生，注意對話中提到的日期（如 Saturday）與 'this weekend' 的對應關係，避免被干擾選項中提到的平日時間所誤導。"]}],"g6-p1-p2:noun:38:bridge":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01251:bridge","word":"bridge","partOfSpeech":["noun","verb"],"chineseMeaning":"橋；橋樑；連接；彌合；渡過；（牌戲的）橋牌","categoryZh":"一般專業","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["bridges"]},{"partOfSpeech":"verb","forms":["bridged","bridging"]}],"examples":[{"english":"The new government project aims to build a bridge that connects the island to the mainland.","chinese":"政府的新專案旨在建造一座連接島嶼和大陸的橋樑。"},{"english":"Good leadership can bridge the differences between team members and foster collaboration.","chinese":"良好的領導能力可以彌合團隊成員之間的分歧並促進合作。"}],"examTips":["實體與比喻用法辨析：在多益第一部分圖片描述題中，bridge 常指實體的橋樑建築；但在閱讀與商務對話中，多用作動詞意為『彌補』或『連結』。","常見搭配詞組：最常見的用法是 bridge the gap (彌補差距)，例如 bridge the communication gap 或 bridge the skills gap。看到 gap 一詞時，應優先考慮 bridge 作為動詞。","商業情境應用：常出現在解決問題、跨部門協作或市場分析的情境中，指連結兩個不同的觀點或縮小意見分歧。","易混淆詞辨析：需區分 bridge (連接/橋樑) 與 breach (違反/缺口)，在多益中 bridge 通常帶有建設性與連結的正面意涵。","聽力考點提醒：在交通報導或廣播中，常出現 bridge maintenance (橋樑維修) 或 bridge closure (橋樑封閉)，考生需注意相關的延誤資訊。"]}],"g6-p1-p2:noun:39:brush":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01292:brush","word":"brush","partOfSpeech":["verb","noun"],"chineseMeaning":"清潔（刷子或刷洗）；（電郵等）快速瀏覽","categoryZh":"辦公日常","starRating":4,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"verb","forms":["brush","brushes","brushing","brushed"]},{"partOfSpeech":"noun","forms":["brush","brushes"]}],"examples":[{"english":"Before the meeting, please brush up on the latest sales figures.","chinese":"在會議前，請快速瀏覽最新的銷售數據。"},{"english":"The cleaning staff will brush the floors every evening.","chinese":"清潔人員將在每個晚上刷地板。"}],"examTips":["片語重點：'brush up on' 是多益常見片語，意指『溫習、磨練某種技能』，常出現在辦公室訓練或出差前的準備情境。","聽力 Part 1 考點：常作為動詞描述動作，如 'brushing the floor'（刷洗地板）或作為名詞 'paint brush'（油漆刷），考生需留意動作與工具的對應。","易混淆辨析：在聽力中需與 'blush'（臉紅）區分發音；在閱讀中需區分 'brush'（輕微接觸/刷子）與 'flush'（沖洗）。","商業情境運用：'brush aside' 常出現在閱讀測驗中，用來描述主管或客戶『忽視、不理會』某項建議或問題。","搭配詞組：常用搭配如 'scrub brush'（洗刷刷子）或 'wire brush'（鋼絲刷），多見於描述工廠維護、建築工程或環境清潔的對話中。"]}],"g6-p1-p2:noun:40:basket":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00886:basket","word":"basket","partOfSpeech":["noun"],"chineseMeaning":"籃子；一籃的量；（籃球）籃框；投籃得分","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["baskets"]}],"examples":[{"english":"Please put the dirty towels in the laundry basket.","chinese":"請把髒毛巾放到洗衣籃裡。"},{"english":"The company offers a gift basket to new clients.","chinese":"公司會提供一份禮物籃給新客戶。"}],"examTips":["多出現於聽力第一部分（照片描述）：常搭配購物情境（shopping basket）或辦公空間情境（wastebasket/trash basket）。考生需留意籃子的擺放位置（如 placed on the counter）或是否被提著（being carried）。","辨析相似容器：需區分 basket（編織或有孔的籃子）、bucket（裝水用的桶子）以及 cart/trolley（有輪子的推車），這在照片描述題中是常見的干擾項。","商業與禮品情境：在閱讀測驗中，'gift basket'（禮物籃）常出現在訂單、感謝信或節慶促銷廣告中；而在經濟文章中，'a basket of goods' 則是指用來計算物價指數的『一籃子商品』。","常見動詞搭配：聽力中常出現 carry a basket（提籃子）、fill a basket（裝滿籃子）或 empty a basket（清空籃子），須注意主動與被動語態的聽取。","複合詞彙：熟悉 wastebasket（垃圾桶）和 laundry basket（洗衣籃）等詞，這類單字常在辦公室或飯店服務情境的對話中出現。"]}],"g6-p1-p2:noun:41:bookcase":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01164:bookcase","word":"bookcase","partOfSpeech":["noun"],"chineseMeaning":"書架；書櫃","categoryZh":"辦公日常","starRating":4,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["bookcase","bookcases"]}],"examples":[{"english":"The office manager asked the new employee to arrange the documents on the bookcase.","chinese":"辦公室經理請新進員工整理書架上的文件。"},{"english":"We need to purchase additional bookcases to accommodate the growing collection of training manuals.","chinese":"我們需要購買更多的書架來容納不斷增加的培訓手冊。"}],"examTips":["多見於聽力測驗第一部分（Photographs）：bookcase 是描述辦公室、圖書館或家居場景的基礎單字。考生需注意物品的擺放狀態，常見句型如「Books have been arranged in a bookcase」或「A bookcase is standing in the corner」。","易混淆詞辨析：常與 bookshelf（書架）混用，在多益中兩者通常可互換，但需與 cabinet（櫥櫃）區分，後者用途較廣，可用於存放檔案或雜物。此外，注意 shelf（單層架）與 bookcase（整體書櫃）的層次差異。","常見搭配詞組：常用動詞包括 arrange（整理）、stock（存放）、lean against（靠在...旁邊）。例如：「A ladder is leaning against the bookcase」是照片描述題的經典陷阱或正確選項。","物品狀態描述：在照片題中，若看到書櫃沒滿，可能會聽到「The bookcase is partially empty」；若書本整齊，則常出現「neatly organized」或「stacked on the shelves」。","商業情境應用：在聽力長對話或閱讀短文中，bookcase 可能出現在辦公室裝修、搬遷或採購家具的討論中，屬於 Office Supplies 或 Facilities 相關主題。"]}],"g6-p1-p2:noun:42:season":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:08931:season","word":"season","partOfSpeech":["noun"],"chineseMeaning":"季節；（商業語境下）特定時期或階段","categoryZh":"營運管理","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["season","seasons"]}],"examples":[{"english":"Our sales typically peak during the holiday season.","chinese":"我們的銷售額通常在節假日期間達到高峰。"},{"english":"The company is planning a new marketing campaign for the upcoming season.","chinese":"公司正在為即將到來的季節規劃新的行銷活動。"}],"examTips":["常見搭配詞：多益考試中常出現 peak season（旺季）、off-season（淡季）及 holiday season（假期時節），主要應用於旅遊業、航空業或零售業情境。","商業情境應用：常用於描述季節性需求 (seasonal demand) 或季節性員工 (seasonal staff)，例如在聖誕節或暑假期間增加的人力需求。","易混淆詞辨析：需區分 season (季節/時期) 與 session (會議/期間)，後者常用於 training session 或 information session，在聽力測驗中發音相近需仔細判別。","詞性與衍伸義考點：season 作為動詞時為『調味』，其形容詞形式 seasoned 常在閱讀 Part 7 出現，意為『經驗豐富的』(experienced)，如 a seasoned professional（資深專業人士）。","聽力及答題重點：在聽力 Part 3 或 Part 4 的對話中，若提到 season，通常伴隨著特定產業的折扣優惠或促銷活動 (promotion)，考生應對相關的時間詞彙保持敏感。"]}],"g6-p1-p2:noun:43:window":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:11088:window","word":"window","partOfSpeech":["noun"],"chineseMeaning":"窗戶；視窗；機會","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["windows"]}],"examples":[{"english":"Please close the window; it's getting cold outside.","chinese":"請關上窗戶；外面越來越冷了。"},{"english":"We have a small window of opportunity to submit the proposal.","chinese":"我們有很短的時間來提交這份提案。"}],"examTips":["常見搭配詞與圖片描述：在多益第一部分（Part 1）中，'window' 常出現在辦公室或商店場景，例如 'cleaning the window' (擦窗戶) 或 'gazing out the window' (凝視窗外)。此外，'store window' (店面櫥窗) 與 'display window' 常用於零售購物情境。","商業抽象用法：在閱讀測驗（Part 7）中，'window of opportunity' 意指短暫的時機，'time window' 指特定時間段，這在討論專案進度或排程時非常常見。","容易混淆的相似詞：需辨析 'window' 與 'mirror' (鏡子) 的差異，特別是在聽力測驗中，注意圖片中反射的是物體還是透明可看穿的。","辦公室文化情境：'window office' (靠窗的辦公室) 在對話中常暗示較高級別的職位或更佳的工作環境。","介係詞運用：掌握 'through the window' (透過窗戶)、'by the window' (在窗戶旁邊) 或 'against the window' (靠在窗戶上) 等空間表達，能有效提升聽力測驗的反應速度。"]}],"g6-p1-p2:noun:44:airport":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00295:airport","word":"airport","partOfSpeech":["noun"],"chineseMeaning":"機場，是飛機起降及旅客搭乘的設施。","categoryZh":"旅遊與交通","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["airport","airports"]}],"examples":[{"english":"The flight is scheduled to depart from Narita Airport at 10:00 AM.","chinese":"這趟航班預計在上午 10:00 從成田機場起飛。"},{"english":"Please remember to arrive at the airport at least two hours before your international flight.","chinese":"請記得在國際航班起飛前至少兩小時抵達機場。"}],"examTips":["常見搭配詞：包含 'airport terminal' (機場航廈)、'airport shuttle' (機場接駁車) 與 'airport security' (機場安檢)，常出現在 Part 7 的行程表或 Part 3 的商務旅行對話中。","聽力常見考點：注意 Part 4 的機場廣播，通常涉及航班延誤 (delays)、登機門變更 (gate change) 或最後登機通知 (final boarding call)。","辨析相似詞：'Terminal' 指的是大型航廈建築，而 'Gate' 則是具體的登機口，兩者在聽力測驗中常被替換出現以測試理解度。","商業情境：常與商務出差 (business travel) 連結，出現在討論預約接送服務 (airport transfer) 或報支交通費用 (transportation expenses) 的情境。","介係詞搭配：在機場通常使用 'at the airport'，代表在該地點範圍內，這是在 Part 5 語法題中偶爾會出現的基礎考點。"]}],"g6-p1-p2:noun:45:airplane":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00294:airplane","word":"airplane","partOfSpeech":["noun"],"chineseMeaning":"飛機，一種用於空中運輸人員或貨物的交通工具。","categoryZh":"旅遊與交通","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["airplane","airplanes"]}],"examples":[{"english":"The company is considering purchasing a new airplane to expand its international routes.","chinese":"公司正在考慮購買一架新飛機以擴展其國際航線。"},{"english":"Due to the delayed airplane, the meeting will be rescheduled for tomorrow morning.","chinese":"由於飛機延誤，會議將改在明天上午舉行。"}],"examTips":["同義詞替換技巧：在 TOEIC 聽力與閱讀中，airplane 常與 aircraft 或 plane 進行同義替換，考生應具備跨單字識別能力。","常見搭配詞：需掌握 boarding pass (登機證)、overhead compartment (頭頂置物櫃) 以及 flight attendant (空服員)，這些詞彙常出現在差旅或交通情境中。","聽力第一部分 (照片描述)：常考動作包括 taking off (起飛)、landing (降落) 或 being stationed on the tarmac (停在停機坪上)，需注意動詞狀態。","商業情境應用：此單字常出現在商務旅行 (business trip) 的行程安排 (itinerary) 或交通費用報支 (reimbursement) 的考題中。","音近詞辨析：聽力中需區分 airplane 與 plan (計畫) 或 plain (簡單的)，透過上下文語境判斷是否與交通工具相關以避免落入陷阱。"]}],"g6-p1-p2:noun:46:autumn":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:00773:autumn","word":"autumn","partOfSpeech":["noun"],"chineseMeaning":"秋季；秋天","categoryZh":"一般專業","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["autumn","autumns"]}],"examples":[{"english":"The leaves turn golden and red in autumn.","chinese":"樹葉在秋天變成金黃色和紅色。"},{"english":"Many people enjoy hiking during the beautiful autumn season.","chinese":"許多人喜歡在美麗的秋季徒步旅行。"}],"examTips":["英美用法區別：TOEIC 考試中，美式英文常用 'fall'，而英式英文常用 'autumn'，考生需熟悉兩者皆指秋季。","商業情境應用：常用於提到季度營收或季節性促銷，例如 'autumn collection' (秋季系列) 或 'autumn sale' (秋季大拍賣)。","常見搭配詞：'in the autumn' (在秋天)、'late autumn' (深秋)，聽力測驗中常以此作為時間線索，用來判斷活動舉辦的月份（約 9-11 月）。","詞彙辨析：雖然此字較基礎，但需注意其字尾 'n' 不發音，且在閱讀測驗中不要與 'column' (專欄/圓柱) 產生視覺上的混淆。","聽力考點：在 Part 3 或 Part 4 的對話與簡短演講中，秋季常與年度預算審核或下半年度計畫相關聯，是判斷商務日程的關鍵資訊。"]}],"g6-p1-p2:noun:47:calendar":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:01412:calendar","word":"calendar","partOfSpeech":["noun"],"chineseMeaning":"日曆；行事曆，用於記錄日期和安排行程的工具。","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["calendar","calendars"]}],"examples":[{"english":"Please mark the deadline on your calendar so you don't miss it.","chinese":"請在你的日曆上標記截止日期，以免錯過。"},{"english":"The marketing team needs to update the calendar with the new product launch date.","chinese":"市場團隊需要將新產品發布日期更新到行事曆上。"}],"examTips":["常見搭配詞：'mark your calendar'（在行事曆上記下重要日子）、'academic calendar'（學年行事曆）、'busy calendar'（行程滿檔）。","商業情境：用於確認會議空檔（check one's availability）或專案時程安排。","聽力考點：常出現在 Part 2 的 When 問句中，或 Part 3 關於約會時間的討論，需對日期、星期、月份的縮寫極為敏感。","閱讀考點：Part 7 常出現以行事曆表格呈現的閱讀題，需注意備註欄位（Notes）中關於活動更動或取消的資訊。","易混淆辨析：'calendar' 指顯示日期的行事曆工具，而 'schedule' 更強調具體事件的時間表，兩者在職場溝通中常互換使用，但 'calendar' 更偏重於長期規劃。"]}],"g6-p1-p2:noun:48:dish":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:02990:dish","word":"dish","partOfSpeech":["noun"],"chineseMeaning":"餐盤；菜餚（指食物種類或一道菜）","categoryZh":"住宿與餐飲","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["dish","dishes"]}],"examples":[{"english":"The restaurant offers a wide variety of dishes to cater to different tastes.","chinese":"這家餐廳提供多種菜餚，以滿足不同顧客的口味。"},{"english":"Please clear the dishes from the table after the meal.","chinese":"用餐完畢後，請將餐盤從桌子上移開。"}],"examTips":["多重詞義辨析：在 TOEIC 考試中，dish 同時具備『餐具（盤子）』與『菜餚』兩種含義。在第一部分（照片描述）中，常指實體的盤子或碗（如：Dishes are stacked in the sink）；而在第三、四部分（聽力對話/短文）或第七部分（閱讀），則多指特定的一道菜。","常見搭配詞組：考生應掌握『side dish』（配菜）、『main dish』（主菜）以及『signature dish』（招牌菜）。在商業外燴（catering）情境中，也常出現『vegetarian dish』（素食餐點）的說法。","易混淆詞辨析：需區分 dish 與 plate。plate 特指扁平的盤子，而 dish 是所有餐具容器（含碗、盤）的總稱，且只有 dish 能廣泛用來指代烹飪好的『菜餚』。","聽力圖片題考點：在 Part 1 中，常出現『A waiter is carrying some dishes』或『Dishes are being arranged on a table』等描述，需注意動作與物品的對應關係。","商業與服務情境：在餐廳評論、飯店服務或商務午餐的閱讀材料中，dish 常伴隨形容詞出現，如『exotic dish』（異國料理）或『specialty dish』（特色菜），用來描述餐飲品質。"]}],"g6-p1-p2:noun:49:history":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04788:history","word":"history","partOfSpeech":["noun"],"chineseMeaning":"歷史；過去的事件或發展。","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["history","histories"]}],"examples":[{"english":"The company's history of innovation has made it a leader in the industry.","chinese":"公司在創新方面的歷史使其成為業界的領導者。"},{"english":"During the meeting, we reviewed the project's history to understand the challenges faced.","chinese":"在會議中，我們回顧了專案的歷史，以了解所面臨的挑戰。"}],"examTips":["常見搭配詞組：在多益考試中 history 鮮少指學科，多指「過往紀錄」，常見詞組如 employment history (工作經歷)、credit history (信用紀錄) 與 medical history (病史)。","商業情境應用：常用於求職（Resume/CV）與銀行業務情境。例如，銀行會審查貸款人的 credit history 以決定是否核貸。","易混淆詞辨析：需區分 historic 與 historical。historic 指「歷史上著名的、具重大意義的」（如：a historic agreement），而 historical 僅指「有關歷史的、過去的」（如：historical documents）。","聽力與閱讀考點：history 常與 track record (績效紀錄) 互為換句話說。在 Part 7 閱讀中，若提到公司過去十年的表現，選項中常會出現 history 來歸納該段內容。","答題注意事項：注意 history 與 story 的區別，story 多指虛構或描述性的故事，而 history 在多益商務語境下代表真實發生的數據或經歷，具備可查證性。"]}],"g6-p1-p2:noun:50:hospital":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04840:hospital","word":"hospital","partOfSpeech":["noun"],"chineseMeaning":"醫院；醫療機構","categoryZh":"營運管理","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["hospital","hospitals"]}],"examples":[{"english":"The company's health insurance plan covers hospitalization and outpatient care.","chinese":"公司的健康保險計畫涵蓋住院和門診治療。"},{"english":"Due to the sudden increase in patients, the hospital is experiencing a shortage of medical supplies.","chinese":"由於病人數量突然增加，醫院正遭受醫療用品短缺。"}],"examTips":["常見搭配詞：常與 'admitted to' (入院) 或 'discharged from' (出院) 連用，在聽力測驗中若聽到這些片語，通常與健康狀況或病假有關。","商業情境應用：此單字常出現在 'Health Insurance' (醫療保險) 或 'Employee Benefits' (員工福利) 的情境，例如保險給付範圍是否包含住院費用。","易混淆詞辨析：注意與 'hospitality' (款待、服務業) 的區別。後者常指飯店或觀光產業 (hospitality industry)，與醫療機構完全不同。","閱讀考點：在 Part 7 的閱讀中，hospital 常出現在保單條款或公司政策中，考生需注意 'coverage' (承保範圍) 是否包含 hospital expenses。","聯想詞與替換詞：應同時熟悉 'clinic' (診所)、'specialist' (專科醫生) 及 'treatment' (治療)，這些詞常與 hospital 出現在同一個情境區塊。"]}],"g6-p1-p2:noun:51:hour":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04855:hour","word":"hour","partOfSpeech":["noun"],"chineseMeaning":"小時","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["hours"]}],"examples":[{"english":"The meeting is scheduled to begin in one hour.","chinese":"會議預計在一小時後開始。"},{"english":"She works eight hours a day from Monday to Friday.","chinese":"她週一到週五每天工作八小時。"}],"examTips":["常見搭配詞：常用於 'business hours' (營業時間)、'rush hour' (通勤尖峰時段)、'peak hours' (高峰時段) 以及 'after hours' (下班後)，這些詞組頻繁出現在 Part 7 的公司公告或電子郵件中。","商業情境應用：在合約或費用估算中，常出現 'hourly rate' (時薪) 或 'billable hours' (可計費工時)，考生需注意其在商業成本計算中的意義。","聽力辨析要點：'hour' 與 'our' 發音完全相同，在 Part 2 的簡短對答中，需根據上下文判斷是時間單位還是代名詞。此外，'an hour' 的連音發音也是聽力測驗的重點。","冠詞與語法規則：雖然首字母是 'h'，但其發音為元音起始 [aʊə]，因此不定冠詞必須使用 'an' (an hour)，這在 Part 5 的文法題中偶爾會出現。","時間跨度理解：閱讀測驗中需區分 'in an hour' (一小時後) 與 'within an hour' (一小時內) 的時間限制差異，這對於回答 Part 7 的細節題至關重要。"]}],"g6-p1-p2:noun:52:husband":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04893:husband","word":"husband","partOfSpeech":["noun"],"chineseMeaning":"丈夫；配偶（男性）","categoryZh":"人力資源","starRating":2,"toeicScoreRange":"400-600","wordForms":[{"partOfSpeech":"noun","forms":["husband","husbands"]}],"examples":[{"english":"The company offers generous parental leave benefits for both husbands and wives.","chinese":"公司為丈夫和妻子提供慷慨的育嬰假福利。"},{"english":"Mr. Chen mentioned that his husband is a successful entrepreneur.","chinese":"陳先生提到他的丈夫是一位成功的企業家。"}],"examTips":["多重詞性辨析：在多益考試中，'husband' 最常見的是名詞『丈夫』，但在 850 分以上的進階考題中，它可能以動詞形式出現，意為『節約、勤儉管理（資源或金錢）』，例如：'to husband one's resources'（節省資源），考生需依上下文判斷。","常見搭配與同義詞：在商業醫療保險或員工福利（Employee Benefits）的閱讀測驗中，'husband' 常與 'spouse'（配偶）互換使用，常見短語如 'spousal coverage'（配偶保險範圍）。","聽力考點與干擾項：在聽力 Part 1 或 Part 3 中，'husband' 常與 'household'（家庭、住戶）或 'house' 產生諧音干擾，應注意發音尾音的區別。","情境應用：在 Part 7 的公司福利手冊或遺囑、法律文件中，常出現 'husband' 提及眷屬權益，此時需注意其與 'dependent'（扶養親屬）的關聯。","答題注意：若在閱讀測驗的選項中看到 'husband'，應確認文章是指稱特定人物關係，還是涉及資源的『節約與管理』，避免誤選。"]}],"g6-p1-p2:noun:53:hotel":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:04850:hotel","word":"hotel","partOfSpeech":["noun"],"chineseMeaning":"旅館；飯店，通常提供住宿、餐飲及其他服務的商業機構。","categoryZh":"住宿與餐飲","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["hotel","hotels"]}],"examples":[{"english":"The company negotiated a discounted rate for the conference attendees at the nearby hotel.","chinese":"公司就附近飯店的住宿費與會者議價成功，獲得了折扣。"},{"english":"Please confirm your hotel reservation and provide your arrival time.","chinese":"請確認您的飯店預訂，並提供您的抵達時間。"}],"examTips":["常見搭配詞：'hotel reservation' (訂房)、'book a hotel' (預訂飯店)、'hotel amenities' (飯店設施)。","聽力考點：常出現在 Part 3 與 Part 4 的商務旅行情境中，需注意 check-in/check-out 時間、房型升等或取消政策。","詞義辨析：注意 'hotel' 與 'hostel' (青年旅館) 的差異，後者通常設施較簡單且需共用房間。","換句話說技巧：在閱讀 Part 7 中，飯店常以 'accommodation' 或 'lodging' 等更正式的單字替代，考生需具備同義詞轉換能力。","商業應用：常涉及 'corporate rate' (企業專案價) 或 'conference venue' (會議場地)，考題可能圍繞在預約飯店會議室舉辦活動。"]}],"g6-p1-p2:noun:54:newspaper":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06643:newspaper","word":"newspaper","partOfSpeech":["noun"],"chineseMeaning":"報紙；新聞報導","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["newspaper","newspapers"]}],"examples":[{"english":"The company's announcement was featured prominently in the business newspapers.","chinese":"該公司的公告在商業報紙上刊登了顯著的位置。"},{"english":"Please review the latest newspapers for any relevant industry trends.","chinese":"請查閱最新的報紙，了解任何相關的行業趨勢。"}],"examTips":["常見搭配詞與商業情境：在多益考試中，常出現 subscribe to a newspaper (訂閱報紙) 或 newspaper advertisement (報紙廣告)。在商業背景下，報紙常用於刊登招聘啟事或作為宣傳媒介。","易混淆詞辨析：注意 newspaper 與 newsletter (內部通訊/簡報) 的差異，前者為大眾媒體，後者多用於公司內部或特定社團。此外，journal 通常指專業期刊或學術雜誌，與大眾性質的報紙不同。","聽力與閱讀考點：Part 1 照片題常出現人物正在 reading a newspaper；Part 7 閱讀則常出現新聞報導 (News Article) 格式，須注意日期、地點、記者姓名等資訊。","相關專業詞彙：熟悉 classifieds (分類廣告)、circulation (發行量)、editorial (社論) 等與報業相關的詞彙，這些詞常在閱讀測驗中與 newspaper 一併出現。","答題注意事項：遇到新聞文章類型的題目時，標題 (Headline) 往往精簡且省略冠詞，理解標題能快速掌握文章核心主旨。"]},{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06644:newspaper","word":"newspaper","partOfSpeech":["noun"],"chineseMeaning":"一份定期發行的報紙，通常包含新聞、商業資訊和廣告。","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["newspaper","newspapers"]}],"examples":[{"english":"The CEO reads the financial section of the newspaper every morning to stay informed about market trends.","chinese":"執行長每天早上閱讀報紙的金融版，以了解市場趨勢。"},{"english":"Our marketing team analyzes newspaper advertisements to assess competitor strategies.","chinese":"我們的行銷團隊分析報紙廣告，以評估競爭對手的策略。"}],"examTips":["常見搭配詞與商業情境：在多益考試中，常出現 subscribe to a newspaper (訂閱報紙) 或 newspaper advertisement (報紙廣告)。在商業背景下，報紙常用於刊登招聘啟事或作為宣傳媒介。","易混淆詞辨析：注意 newspaper 與 newsletter (內部通訊/簡報) 的差異，前者為大眾媒體，後者多用於公司內部或特定社團。此外，journal 通常指專業期刊或學術雜誌，與大眾性質的報紙不同。","聽力與閱讀考點：Part 1 照片題常出現人物正在 reading a newspaper；Part 7 閱讀則常出現新聞報導 (News Article) 格式，須注意日期、地點、記者姓名等資訊。","相關專業詞彙：熟悉 classifieds (分類廣告)、circulation (發行量)、editorial (社論) 等與報業相關的詞彙，這些詞常在閱讀測驗中與 newspaper 一併出現。","答題注意事項：遇到新聞文章類型的題目時，標題 (Headline) 往往精簡且省略冠詞，理解標題能快速掌握文章核心主旨。"]}],"g6-p1-p2:noun:56:net":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06622:net","word":"net","partOfSpeech":["noun"],"chineseMeaning":"網路；淨值（在商業語境中，通常指網路或網際網路）","categoryZh":"科技與技術支援","starRating":4,"toeicScoreRange":"600-780","wordForms":[{"partOfSpeech":"noun","forms":["net","nets"]}],"examples":[{"english":"The company is investing heavily in its online presence to expand its reach across the net.","chinese":"公司正在大力投資其線上存在，以擴展其在網路上的影響力。"},{"english":"Please ensure all data is securely transmitted over the net.","chinese":"請確保所有資料透過網路安全傳輸。"}],"examTips":["淨值 vs. 總額：在 TOEIC 閱讀的財務報表中，最常出現 'net profit' (淨利) 與 'gross profit' (毛利) 的對比，考生需注意兩者差異，淨利是扣除成本與稅後的實際金額。","常見搭配詞組：常用於 'net weight' (淨重)、'net worth' (淨值) 以及 'net income' (淨收入)，這些詞組常出現在物流或財務類題目。","相似詞辨析：'Net' 作為動詞時意為「淨賺」，須與 'gross' (總共賺取) 區分；同時要注意與 'network' (網絡) 的區別，在商業通訊情境中 'net' 有時簡指網絡。","考試出題重點：在 Part 7 的表格或收據中，'Net' 常出現在最後一列，代表最終應付金額或結餘。","答題注意事項：看到 'net' 時應反射性尋找扣除額 (deductions) 或支出 (expenses) 的資訊，以確認計算邏輯是否正確。"]}],"g6-p1-p2:noun:57:nest":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06621:nest","word":"nest","partOfSpeech":["noun"],"chineseMeaning":"巢穴；（比喻）穩固的地位或環境","categoryZh":"營運管理","starRating":2,"toeicScoreRange":"780-900","wordForms":[{"partOfSpeech":"noun","forms":["nest","nests"]}],"examples":[{"english":"The company is trying to build a stable nest for its employees, offering competitive salaries and benefits.","chinese":"該公司正努力為員工建立穩固的環境，提供具競爭力的薪資和福利。"},{"english":"After years of hard work, she finally built a successful nest for her family.","chinese":"經過多年的辛勤工作，她最終為她的家庭建立了一個成功的事業。"}],"examTips":["財經情境常考「nest egg」一詞，意指為了退休或緊急用途所儲蓄的一大筆錢，常出現在個人理財或福利計畫的閱讀篇章中。","在技術或資料處理情境，「nested」常用於描述結構，如 nested folders（嵌套資料夾）或 nested tables，指一個物件包含在另一個同類物件之中。","聽力辨析：注意 nest 與 net（淨值）的發音，net 在多益商業情境（如 net profit）極為常見，需依上下文判斷。","詞性轉換：nest 可作為動詞使用，表示「築巢」或「套疊」，在物流或倉儲管理中，可能描述貨物或容器的擺放方式以節省空間。","常見搭配詞包括 empty nest（空巢期）或 hornet's nest（棘手的狀況），雖然多益以後者較少見，但了解其比喻用法有助於理解複雜語文情境。"]}],"g6-p1-p2:noun:58:noon":[{"vocabularySetId":"toeic-vocab-tw","wordId":"toeic-vocab-tw:06691:noon","word":"noon","partOfSpeech":["noun"],"chineseMeaning":"中午；正午","categoryZh":"辦公日常","starRating":5,"toeicScoreRange":"0-400","wordForms":[{"partOfSpeech":"noun","forms":["noon","noons"]}],"examples":[{"english":"The meeting is scheduled for noon.","chinese":"會議預計在中午舉行。"},{"english":"Please submit your expense report by noon on Friday.","chinese":"請在週五中午前提交您的費用報表。"}],"examTips":["介係詞搭配：最常見的用法是 \"at noon\" (在正午) 與 \"by noon\" (在正午之前)。需注意不與介係詞 \"in\" 連用，這在 Part 5 文法題中是基礎考點。","商業情境應用：常用於標註截止時間 (deadline) 或會議安排，例如 \"The documents must be submitted by noon.\" (文件必須在中午前繳交)。","相似詞辨析：與 \"midnight\" (午夜) 相對。在 TOEIC 中需明確知道 noon 為 12:00 PM。應避免與 \"afternoon\" (下午) 混淆，後者指的是正午之後的一段時間。","聽力與閱讀考點：在 Part 3 和 Part 4 的對話與短文中，noon 常作為約會或交貨的精確時間指標。當提到 \"lunch hour\" 或 \"midday\" 時，考生應聯想到 noon。","答題注意事項：在 Part 7 的行程表或電子郵件閱讀題中，若出現 noon，應將其視為 12:00 PM，以確保在回答有關時間差或日程安排的題目時計算正確。"]}]}};
